local Text_Mail = readonly({
  Mail_100480_Desc = {
    Text = [[
Penjaga, apakah kamu sudah mendengar? Galeri seni terpencil di pinggiran kota akan segera tutup, tepat di hari ulang tahunku.
Galeri itu adalah freak di dunia seni, setengah tubuhnya merupakan eksperimen futuristik yang dangkal, setengahnya lagi merupakan sisa-sisa sampah dari dua abad yang lalu. Perutnya yang sempit dipenuhi benda aneh yang tidak ada yang berani menyentuh di rumah lelang: potret yang mengumpat, burung mekanik yang tidak pernah berhenti terbang, ukiran laut yang membuat orang merasa mual, patung yang sepenuhnya terbuat dari air mata, manuskrip hantu yang terus menulis secara otomatis, tengkorak manusia yang bersenandung lagu anak-anak saat berciuman...
Sangat sulit untuk menggambarkan betapa aku sangat mencintai galeri ini! Lima puluh tahun yang lalu, ia lahir diam-diam di sudut yang tidak ada yang peduli. Lima puluh tahun setelahnya, ia diam-diam punah di sudut itu.
Sejak masa kecilku, ada yang memberitahuku bahwa hari ini adalah kutukan, seperti aku sendiri. Aku rasa takdir mungkin telah ditentukan, tetapi bagaimana dengan takdir yang ditentukan itu! Apa yang diciptakan galeri tersebut adalah dunia yang tidak ada duanya, begitu banyak ide gila menumpuk di ruang kecil itu, betapa indahnya pemandangan! Sejak hari kelahirannya, ia telah menciptakan dengan pamerannya. Pada hari berakhirnya, sahabat dan teman lamanya juga akan mengucapkan selamat tinggal terakhir.
Penjaga, kamu telah melihat dunia di mataku dalam tautan, aku yakin, kamu juga pasti ingin ikut melihat galeri yang unik ini, bukan?!

Pikman]]
  },
  Mail_100480_Name = {
    Text = "Pameran yang tidak ada yang peduli"
  },
  Mail_100480_Sender = {Text = "Pickman"},
  Mail_116602_Desc = {
    Text = "Kepada Penjaga yang terhormat:\n Acara \"Malam Tanpa Akhir Siang Abadi\" telah berakhir. Saat ini, sisa \"Mengunjungi Persembahan\", \"Pengakuan dosa dan persembahan\", dan \"Kesetiaan Persembahan\" milik Penjaga akan dikonversi dengan rasio setiap item menjadi \"Rose Scrip\"× 40. Harap Penjaga ingat untuk memeriksa."
  },
  Mail_116602_Name = {
    Text = "Penghargaan yang dikembalikan"
  },
  Mail_116602_Sender = {
    Text = "Dewan Sekolah Mythag"
  },
  Mail_117308_Desc = {
    Text = "Kepada Penjaga yang terhormat:\n        Terima kasih atas dukungan dan pengakuan Anda terhadap \"Morimens\". Untuk memberikan pengalaman bermain yang lebih baik bagi Penjaga di Universitas Mythag, kami dengan hormat mengundang Anda untuk mengisi kuesioner pengalaman berikut. Sebagai tanda terima kasih atas kerjasama Anda, kami telah menyiapkan \"Perak\"× 200 sebagai hadiah, yang dapat Anda ambil setelah menyelesaikan kuesioner. Batas waktu pengisian kuesioner adalah 10 November pukul 09:00, harap diisi tepat waktu.\n        <SurveyLink:[Klik di sini untuk mengisi]>\n        Kami akan mendengarkan setiap saran dari Penjaga, dan umpan balik Anda pasti akan membuat Universitas Mythag semakin baik!\n        ——Semoga Kunci Perak menuntun jalanmu."
  },
  Mail_117308_Name = {
    Text = "Kuesioner Penelitian Pengalaman Versi V2.3.4"
  },
  Mail_117308_Sender = {
    Text = "Mythag Bureau of School Affairs"
  },
  Mail_117309_Desc = {
    Text = "Kepada Penjaga yang terhormat: \n        Terima kasih atas dukungan dan pengakuan Anda terhadap \"Morimens\". Untuk memberikan pengalaman bermain yang lebih baik bagi para Penjaga di Universitas Mythag, kami dengan hormat mengundang Anda untuk mengisi kuesioner survei pengalaman berikut. Sebagai ungkapan terima kasih atas kerjasama Anda, kami telah menyiapkan \"Perak\" × 200 sebagai hadiah, yang dapat Anda ambil setelah menyelesaikan kuesioner. Batas waktu pengisian kuesioner adalah 30 Maret pukul 9:00, harap perhatikan untuk mengisi tepat waktu. \n        <SurveyLink:[Klik di sini untuk mengisi]>\n        Kami akan mendengarkan setiap saran dari Penjaga, dan umpan balik Anda pasti akan membuat Universitas Mythag semakin baik! \n        ——Semoga Kunci Perak menuntun jalanmu."
  },
  Mail_117309_Name = {
    Text = "Kuesioner Penelitian Pengalaman Versi V2.4.3"
  },
  Mail_117309_Sender = {
    Text = "Mythag Bureau of School Affairs"
  },
  Mail_120374_Desc = {
    Text = "Perjanjian dua tahun telah tiba, Penjaga.\n Kita pernah saling menjaga di tepi akhir.\n Kamu telah mengubah perasaan dan memori menjadi harapan yang menerangi cahaya harapan.\n Meskipun terpisah dari rekan-rekan masa lalu di dua alam semesta yang berbeda, kamu tidak pernah menyerah pada perjalanan melawan Pelarutan.\n Memiliki kamu adalah keberuntungan kami, juga keberuntungan dunia ini.\n Sekarang keinginanmu telah memicu keajaiban—— Mythag masih ada di sini dan akan terus melanjutkan.\n Silakan terus genggam Kunci perak, suatu hari nanti, itu dapat menjadi kunci penting yang menghubungkan dua dunia yang jauh.\n Kami akan melakukan yang terbaik untuk membuka kemungkinan masa depan, menerangi jalan kembalimu."
  },
  Mail_120374_Name = {
    Text = "Saat Keajaiban, Cahaya Pulang"
  },
  Mail_120374_Sender = {
    Text = "Kucing sekolah Mythag · Light"
  },
  Mail_120909_Desc = {
    Text = [[
