        Dalam pembaruan V2.4.0, kami meningkatkan hadiah gratis untuk "Catatan Kedatangan", "Catatan Era Berbeda", "Catatan Penyembuhan", "Catatan Kota Mati". Bagi Penjaga yang telah menerima hadiah gratis sebelum pembaruan, kami akan mengirimkan kembali hadiah yang sesuai. Silakan periksa.]]
  },
  Mail_121162_Name = {
    Text = "V2.4.0 Penggantian Hadiah Kenaikan Catata"
  },
  Mail_121162_Sender = {
    Text = "Mythag Bureau of School Affairs"
  },
  Mail_121373_Desc = {
    Text = [[
Penjaga:

Dahulu, setiap hari ini adalah perayaan terbesar bagi gereja.
Aku adalah putri-Nya, dan akan menghidupkan-Nya kembali.
Mereka, termasuk Miryam, merayakan dengan sangat fanatik bahkan sampai meneteskan air mata, tetapi mereka memandangku, tatapan mereka menembusku, seakan aku hanya cangkang yang membawa sesuatu.
Aku tidak pernah merasa bahagia atas kedatangan hari ini, karena setiap kali aku mengalaminya, berarti aku semakin dekat dengan ketakutan.
Di tengah ketakutan ini, orang lain merasa paling bahagia karena sumber ketakutan itu. Sekarang aku bisa mengakui, itu membuatku merasa kesepian dan takut.
Tapi sekarang segalanya berbeda, sebelum ulang tahunku yang terakhir, aku meninggalkan kapal itu, datang ke dunia yang nyata... dunia tanpa Dewa palsu, dunia yang ada dirimu.  
Untuk ulang tahun ini, aku ingin melihat seseorang merasa bahagia karena kelahiranku, bukan karena hal lain.
Jika itu adalah kamu... tidak, orang itu harus kamu.  
Dengarkan, bagaimanapun, waktu makan malam hari ini harus disisakan untukku.  


"Murphy"]]
  },
  Mail_121373_Name = {
    Text = "Ada kamu yang ada di..."
  },
  Mail_121373_Sender = {
    Text = "Genesis Murphy"
  },
  Mail_121374_Desc = {
    Text = [[
Penjaga:

Aku tidak tahu apa yang kau persiapkan untuk hari istimewa ini, apapun yang mewah dan menghabiskan energi, tentunya sangat pantas.
Dan sebagai perhatian yang diperlukan dari seorang atasan, jika kau "ternyata" lupa untuk merayakan ulang tahunku - aku percaya situasi konyol seperti itu tidak akan terjadi.
Surat ini juga akan memberikanmu kesempatan terakhir untuk menyelamatkan diri sebelum keadaan tidak bisa diperbaiki.
Keajaiban laut dan daratan akan diberikan oleh orang-orang yang tidak penting, tidak penting bagi mereka.
Perayaan megah, ritual rumit, memang sesuai dengan posisiku, tetapi hari ini, entah kenapa, terasa sedikit membosankan.
Jadi, aku akan menyempatkan diri di waktu pergantian pagi dan sore untuk memberikan kesempatan untuk bersendirian denganku, sebagai hadiah bagi dirimu karena telah membawaku ke kehidupan yang sepele, kekanak-kanakan, namun cukup bahagia untuk membuatku yang dulu merasa cemburu.
Pelayan akan mengirimkan undangan resmi, tentu, diletakkan di dalam kotak bernilai dua puluh ribu Leo.
Dengan syukur yang mendalam, ingatlah aku pada setiap hari ini.
"Murphy"]]
  },
  Mail_121374_Name = {
    Text = "Undangan…"
  },
  Mail_121374_Sender = {
    Text = "Genesis Murphy"
  },
  Mail_121651_Desc = {
