  },
  Mail_122522_Desc = {
    Text = "Yth. Penjaga: \n Acara \"Bayang-bayang Kota Hujan·Replikasi\" telah berakhir. Saat ini, sisa \"Skull Binatang Pucat\", \"Tulang Kepala Hewan Bayangan\", dan \"Tulang Belakang Binatang Merah Marun\" milik Penjaga akan dikonversi dengan rasio setiap item menjadi \"Rose Scrip\"× 40. Harap Penjaga ingat untuk memeriksa."
  },
