    Text = "Bayangan Suram Kota Hujan Pemulihan Mata Uang"
  },
  Mail_122522_Sender = {
    Text = "Dewan Sekolah Mythag"
  },
  Mail_122567_Desc = {
    Text = "Kepada Penjaga yang terhormat: \n Acara \"Upacara Pembakaran Kabut\" telah berakhir. Saat ini, sisa \"Pandangan Kabut\", \"Mimpi Kabut\", dan \"Sumber Kabut\" milik Penjaga akan dikonversi dengan rasio setiap item menjadi \"Rose Scrip\"× 40. Harap Penjaga ingat untuk memeriksa."
  },
  Mail_122567_Name = {
    Text = "Pemulihan Mata Uang Upacara Pembakaran Kabut"
  },
  Mail_122567_Sender = {
    Text = "Dewan Sekolah Mythag"
  },
  Mail_122568_Desc = {
    Text = [[
Ah, anak malang, kamu sama sekali tidak tahu jenis keputusasaan apa yang harus kamu hadapi. Kapan kamu akan menyadari bahwa pilihanmu tidak ada artinya? Menyerahkan nyawamu yang kecil untuk tujuan yang tidak jelas? Betapa heroik, betapa memabukkan! Kamu selalu terlihat penuh semangat, seolah-olah dalam sekejap lagi akan berkorban untuk menyelamatkan dunia, sungguh membuat orang tertawa. 

 Namun, siapa yang membuatku berjanji untuk membantumu pulang? Janji yang kubuat untuk seekor anjing kecil, pasti akan kutepati. Ngomong-ngomong, aku tidak sabar ingin melihat, seberapa besar tekad yang akan kamu keluarkan untuk membawa kegilaan ini sampai ke akhir? Ah... rasa ingin tahuku, sungguh sangat ingin tahu! 

 "Juruselamat" yang agung, bawa semua kebodohanmu, keuletanmu, dan keteguhanmu yang tidak berarti itu. Kereta yang menuju kehampaan begitu mulai bergerak, tidak ada kemungkinan untuk berhenti selain kehancuran. 

 Orang gila yang merasa puas dengan dirinya sendiri... semoga kamu bertahan lebih lama dalam mimpinya, aku akan membantumu, menunggu, dan menikmati jawaban akhirnya!]]
  },
  Mail_122568_Name = {
    Text = "Kereta yang menuju Ilusi"
  },
  Mail_122568_Sender = {
    Text = "Doll: Inferno"
  },
  Mail_122569_Desc = {
    Text = "Tuan, \n aku selalu percaya bahwa ksatria bukanlah zirah dan lambang yang dikenakan, tetapi kesetiaan dan kehendak untuk melindungi yang terukir di dalam hati. Dengan tindakan dan keputusan Anda, Anda telah benar-benar menjelaskan kepada saya apa itu ksatria. Dari situ aku dapat melihat arti sejati seorang ksatria: bukan karena nama yang dihormati, tetapi karena melindungi orang; bukan karena kehormatan yang berani, tetapi karena tanggung jawab yang diemban. \n\n Aku mengerti bahwa aku masih belum memenuhi syarat — pada saat Anda berjuang untuk melindungi harapan, aku tidak bisa berdiri di samping Anda. Aku tidak pernah melupakan sumpah yang telah kita buat di masa lalu, aku akan mempersembahkan kesetiaan seorang ksatria untuk melindungi keselamatan Anda dan menghilangkan ancaman musuh-musuh Anda. \n\n Aku sering mengingat perjalanan pertama kita bersama, di mana Anda memimpin kami untuk mengurai kabut Lentini dan melihat kebenaran yang sebenarnya. Saat itu, semua tawa dan tangisan, telah menjadi kekuatan yang tak terhapuskan dalam hidupku. \n\n Meskipun sekarang aku hanya bisa mengawasi dari jauh dan menyiapkan hadiah kecil untuk Anda... tetapi demi tidak mengecewakan harapan Tuan, aku tidak pernah lengah dalam latihanku. Saat Anda kembali, izinkan aku mengikuti jejak langkah Anda, aku akan selalu ada sebagai perisai Tuan! Pedang pelindungku akan bersinar untuk Anda!"
  },
  Mail_122569_Name = {Text = "Pengamat"},
  Mail_122569_Sender = {Text = "Ogier"},
  Mail_122570_Desc = {
    Text = [[
Yang Mulia Penjaga, 
 setelah perpisahan di Kota Pemakaman Diri, aku sering merindukan waktu kita bertempur berdampingan. Mendengar bahwa kamu sekali lagi memilih jalan kesendirian yang hanya bisa dilalui oleh seorang raja, memang benar, kamu adalah sosok yang begitu istimewa di dunia ini, tidak pernah mengikuti jalur orang biasa. 

 Aku yakin, penderitaan yang ekstrem dapat memurnikan jiwa yang lebih harum. Ujian panjang yang kamu alami telah melampaui batas rasa sakit yang biasa. Aku bisa membayangkan, aroma yang dihasilkan dari penderitaanmu akan sangat kompleks dan mengguncang. Tidak, jika itu adalah kamu, kamu pasti akan melampaui semua imajinasiku, menghancurkan semua pemahamanku tentang kesempurnaan. 

 Untuk itu, aku akan terus menunggu. Menunggu pesta yang hanya ada untuk kita berdua. Di ujung waktu, di dalam keheningan awal keabadian, dalam bentuk apa kamu akan mempersembahkan pesta ini... yang melintasi rasa takdir bagi diriku? 

 Yang Mulia, terimalah hadiahku, perpanjanglah penderitaan ini... jangan sia-siakan, harapanku.]]
  },
  Mail_122570_Name = {
    Text = "Pesta Menunggu"
  },
  Mail_122570_Sender = {Text = "Doresain"},
  Mail_122571_Desc = {
    Text = [[
Baru saja bertemu kembali, belum sempat berbicara beberapa kalimat, waktu sudah tersisa sedikit... Tapi kamu tahu, perpisahan tidak pernah menjadi akhir dari cerita kita. 

 Ada satu hal yang belum pernah aku ceritakan padamu... Sebenarnya, aku sudah menyiapkan seikat mawar untukmu. Hanya saja, aku belum sempat mengirimkannya, dan sekarang sudah layu. Tapi aku di sini berjanji - pada pertemuan berikutnya, aku pasti akan menyiapkan seikat mawar untukmu lagi. 

 Dan kamu, kamu juga berjanji padaku, pasti akan datang lagi di hadapanku. Kita sudah mengikat janji, tidak boleh, tidak boleh ingkar. 

 Menulis surat selalu terasa tidak cukup, tidak bisa menyampaikan semua perasaanku. Namun... ketika takdir kembali mempertemukan kita di hari itu, aku akan menyerahkan seikat mawar itu langsung ke tanganmu. Ingat, kita harus menepati janji! 

 Semoga kunci perak menunjukkan jalan ke depan. Selamat tinggal... %player%.]]
  },
  Mail_122571_Name = {
    Text = "Janji Mawar"
  },
  Mail_122571_Sender = {Text = "Ramona"},
  Mail_122572_Desc = {
    Text = [[
Penjaga, 
 kenangan melawan bencana kegelapan masih berputar dalam otakku dengan prioritas tinggi, perdamaian yang kau peroleh seperti peristiwa hadiah dengan kemungkinan sangat kecil. Namun kepergianmu, bagi rekanmu dan semua individu yang pernah terhubung denganmu, terus-menerus menguras kesadaran mereka dalam proses yang tak terhentikan. 

 Departemen penelitian tidak pernah menyerah mencari harapan terakhir. Beruntung, setelah banyak hari dan malam tanpa umpan balik kesadaranmu, akhirnya kami berhasil melacak jejakmu. Dalam perjalanan yang berbahaya ini, aku dapat menangkap sinyal ketakutan, namun aku juga tahu, ketakutan tidak akan membuatmu menyerah, hanya akan membuat tekadmu semakin kuat. 

 Saat ini, tubuhku masih beroperasi di laboratorium, tetapi otakku terus menghasilkan instruksi untuk menangis. Jangan lagi mengganggu pikiranku, siswa yang paling sering bolos, tolong jangan lagi tidak hadir di kelasku... teruslah maju dengan berani, aku akan menyiapkan persediaan untukmu, menunggu hari di mana kita bertemu kembali.]]
  },
  Mail_122572_Name = {
    Text = "Hari Pertemuan Kembali..."
  },
  Mail_122572_Sender = {Text = "Doll"},
  Mail_122573_Desc = {
    Text = "Tidak terhitung kali, aku menyaksikan percikan peradaban yang berkelap-kelip dalam aliran waktu, menyaksikan kota-kota ingatan runtuh dalam kehampaan. Sejarah menjadi gulungan yang ditelan oleh api hitam, kebijaksanaan dari zaman dahulu hingga sekarang menumpuk seperti menara pasir, namun pada akhirnya tidak dapat mengungkapkan kebenaran yang satu dan sejati. \n\nManusia di hadapan kekacauan primordial hanyalah debu—namun karena kecilnya itulah, keberanian untuk menghadapi jurang dan mengangkat pedang kepada dewa menjadi begitu menggugah hati. \n\nSaat ini, pintu dimensi yang menghubungkan ribuan alam semesta terbuka untukmu. \n\nKedatangan-Nya membawa kekacauan yang ditakdirkan, tatanan segala sesuatu bergetar dalam bayang-bayang-Nya. Dan kamu, hanya tubuh fana, namun dengan kehendak yang tak tergoyahkan, berdiri di hadapan-Nya. Kemungkinanmu adalah satu-satunya kesalahan yang tidak dapat kutangkap dalam ramalanku yang tak berujung, adalah variabel yang mengguncang segalanya dalam penantianku yang panjang. \n\nKamu adalah pertanyaan primordial, sekaligus jawaban akhir."
  },
  Mail_122573_Name = {
    Text = "Di balik pintu"
  },
  Mail_122573_Sender = {Text = "Tawil"},
  Mail_122574_Desc = {
    Text = "Rasa sakit yang mendalam karena kehilangan orang yang penting, kebencian terhadap ketidakberdayaan diri sendiri... Aku pernah terjebak di dalamnya, tidak bisa keluar. Tapi sekarang, aku telah mendengar panggilan lampu yang jauh, merasakan petunjuknya yang hangat dan tegas. Yang terhormat, sejak Anda memberi petunjuk, aku seolah akhirnya menginjakkan kaki di jalan yang seharusnya kutempuh—jalan yang benar-benar milikku, yang tidak dapat disangkal sebagai jalan yang benar. \n\n Kegelapan yang seperti jurang yang pernah menyelubungiku, tidak lagi menjadi tempat kembaliku. Dan cahaya yang selalu berkilau di kedalaman kesadaranku, tidak pernah benar-benar meninggalkanku. Kini aku lebih jelas melihatnya, merasakannya, dan berjalan menuju cahaya itu. Aku juga ingin membawa iman yang sejati ini, kesadaran dan ketenangan yang dibawa oleh cahaya ini, kebangkitan dan penebusan, kepada banyak jiwa yang masih berjuang di jalan takdir yang membingungkan. \n\n Dan ketika aku menatap sosok Anda yang melawan seluruh arus kekacauan—kegelapan yang jahat dan dalam, bukan hanya tidak bisa membuat Anda menyerah, tetapi justru menjadi tirai yang mencerminkan keyakinan Anda. Ia hancur, menggeram, dan mundur di hadapan cahaya Anda, tetapi pada akhirnya tidak dapat menutupi Anda sedikit pun. Justru karena gelombang gelap yang tak ada habisnya ini, cahaya yang Anda wakili menjadi begitu cemerlang, abadi, dan dekat dengan keilahian. \n\n Yang terhormat yang membimbingku, yang memberi cahaya, keyakinan Anda akan menjadi lentera abadi bagiku. Sekarang, adalah saatnya aku merespons Anda dengan seluruh hidupku. Aku akan menjawab cahaya ini, menjawab petunjuk suci Anda dengan \"Hati Suci\" yang mendengarkan kehendak Tuhan... Untuk itu, aku dan Castor akan berusaha sekuat tenaga. \n\n Terimalah persembahanku! Mohon saksikan, iman yang telah Anda bentuk kembali, yang murni dan penuh ketulusan."
  },
  Mail_122574_Name = {
    Text = "Panggilan Lampu Terang"
  },
  Mail_122574_Sender = {Text = "Pollux"},
  Mail_122575_Desc = {
    Text = [[
Pelanggan setia yang terhormat, 
 Di balik pintu bercahaya lembut itu, teman-teman yang kamu hargai telah menunggu cukup lama. 

 Namun, jangan anggap remeh. Melintasi dimensi selalu penuh dengan tipu daya dan bahaya, kamu akan menyaksikan ilusi seribu wajah muncul dan menghilang seperti bayangan memori, mencerminkan kerinduan dan juga ketakutan. Itu adalah gulungan kekacauan yang diciptakan oleh kehendak primordial, bahkan aku pun tidak dapat melihat keseluruhannya. Oleh karena itu, setiap kali melintasi, itu adalah ujian terhadap keyakinan dan juga pengukuran terhadap keinginan. 

 Namun, aku juga sangat memahami, bagi orang-orang seperti kamu dan aku, untuk mencari koleksi baru, untuk barang-barang yang bersinar di kedalaman jiwa, segala ketidakpastian dan pengorbanan adalah sesuatu yang layak. Aku menghargai pilihanmu dan menghormati penghargaan yang hampir bisa dibilang keras kepala ini. 

 Di alam semesta yang mengikuti hukum ekivalen ini, apa yang kamu bayar, pada akhirnya akan kembali dalam bentuk lain. 

 Terimalah hadiah ini, dan ketika semua debu telah mengendap, aku menyambutmu kembali ke toko kecilku. Untuk mewujudkan keinginan saat itu, harga apa yang bersedia kamu bayar?]]
  },
  Mail_122575_Name = {
    Text = "Barang yang Dihargai"
  },
  Mail_122575_Sender = {Text = "Daffodil"},
  Mail_123134_Desc = {
    Text = [[
Kepada Penjaga yang terhormat: 
        Dalam pembaruan V2.4.0, terdapat masalah dalam mendapatkan hadiah 3 bintang untuk tantangan "Selamat Tinggal Tanpa Pulang" dan "Selamat Tinggal, Tanpa Pulang" di "Dimensi Mimpi yang Berbeda". Berdasarkan penyelidikan dan catatan penyelesaian tantangan Anda sebelumnya, kami akan mengirimkan secara sekaligus hadiah yang sebelumnya tidak dapat Anda ambil. Harap periksa.]]
  },
  Mail_123134_Name = {
    Text = "V2.4.0 Kompensasi Hadiah Lanskap Mimpi"
  },
  Mail_123134_Sender = {
    Text = "Dewan Sekolah Mythag"
  },
  Mail_123501_Desc = {
    Text = "Kepada Penjaga yang terhormat: \n\n Apakah kamu ingin, pada hari istimewa ini, berkencan dengan aku, gadis manis ini, dalam sebuah kencan yang sangat menyenangkan? \n Ayo, ayo, bermain di rumah hantu tidak akan membuatmu mati ketakutan~ Kamu kan \"Penjaga\", pasti tidak akan takut pada \"hantu\" yang diperankan oleh manusia, kan? \n (Di kertas surat, ada garis yang menghapus satu baris tulisan: Aku sebenarnya sedang merencanakan perjalanan ulang tahun dengan serius, bukan hanya untuk bersenang-senang melihat ekspresi ketakutanmu…) \n Baiklah, tidak bercanda lagi. Jarang sekali hari ini adalah ulang tahunku, aku tidak ingin merusaknya! Jadi sekarang, aku, Mouchette, secara resmi mengundangmu untuk makan malam di restoran baru yang dibuka di Kota London— \n Teh panas dan ikan rebus di sana mengingatkanku pada rasa \"kampung halaman\", dan di dunia ini, selain kamu, aku tidak menemukan orang lain untuk berbagi… \n Jadi kamu pasti akan datang, kan? Jika aku, gadis manis ini, sampai sedih, hati-hati, di lain waktu saat kamu tidur, aku akan berdiri di samping tempat tidurmu dengan kapak! \n\n Mouchette"
  },
  Mail_123501_Name = {Text = "\"Buka aku\""},
  Mail_123501_Sender = {Text = "Mouchette"},
  Mail_123543_Desc = {
    Text = "Penjaga: \n\nSetahun lagi, sayangku. \nDi tengah kilau yang megah, di antara bisikan dan gosip yang bertebaran, aku dengan hati-hati menyembunyikan setiap kelemahan yang mungkin terungkap, menggunakan setiap nilai untuk mendapatkan manfaat yang maksimal—seharusnya begitu, agar aku tetap berdiri di sini dengan sikap sebagai pemenang. \nNamun tidak, aku terkadang menjadi sedikit malas dan lemah, dan dengan senang hati memenuhi keinginan gadis-gadis kecil yang mengirimkan surat kepadaku. \nNamun aku tidak merasa itu adalah hal yang buruk, aku telah menjalani perang rahasia yang panjang terlalu lama. Tentu saja, selama ada sedikit kemungkinan, sedikit kesempatan, aku akan terus mencoba melarikan diri dari tangan \"dia\". \nHanya saja, di celah-celah hangat dan manis itu, atau dalam hari-hari istimewa seperti hari ini, aku mengizinkan diriku untuk sedikit menyimpang, seperti—mengundangmu untuk menonton opera bersama, atau pergi makan malam. \nKarena aku mengerti, aku pasti tidak akan sendirian, aku sudah memiliki sekutu yang sangat sesuai dengan hatiku. \n\nSorel"
  },
  Mail_123543_Name = {
    Text = "Kaki tangan"
  },
  Mail_123543_Sender = {Text = "Sorel"},
  Mail_123544_Desc = {
    Text = "Salam sejahtera: \n\n Lama tak berkomunikasi, Penjaga. Mohon maaf, dalam beberapa waktu terakhir tidak ada surat yang saling bertukar, bukan karena ingin menjauhkan hubungan kita, tetapi setiap kali saya mengambil pena, saya selalu tidak dapat mengumpulkan keberanian untuk menyampaikan sapaan di awal. \n Selama waktu ini, saya telah melintasi banyak waktu yang hancur, dan karena itu saya dapat menyaksikan dunia berulang kali menuju akhir, menyaksikan tragedi yang tidak dapat diperbaiki. Seperti seorang pengamat, dalam kekosongan yang dingin dan sunyi ini, saya diam-diam mengamati segala sesuatu yang terjadi. \n Setiap kali saat itu, saya berpikir, apakah hidup kita ditakdirkan untuk dipenuhi dengan absurditas dan perpisahan? Baik diri saya yang dulu, maupun segala sesuatu yang kamu sambut di Kadath, apakah takdir telah menetapkan naskah untuk segalanya, dan kita hanya dapat memainkan peran yang diperlukan dalam naskah tersebut? \n Saya tidak dapat menemukan kesimpulan, saya tidak seperti Dia, tidak dapat melihat segala sesuatu di dunia ini dengan jelas, jadi saya berpikir, jika… kamu yang memiliki sebagian dari kuasa-Nya, bisakah kamu menjawab pertanyaan ini? \n Oleh karena itu, saya menulis surat ini, berharap dapat membawa pandanganku mendekat ke sisimu, dan juga berharap dapat mendiskusikan teka-teki yang mungkin tidak akan pernah ada jawabannya ini bersamamu. Jadi, bolehkah saya dengan berani meminta kamu untuk membawa surat ini, bersamamu… menghadapi jalan yang akan datang? \n………………………………\n Saya tidak dapat mengambil risiko mengganggu waktu dan ruang untuk pergi ke sampingmu, tetapi izinkan saya… melihatmu lagi dalam kesunyian yang kosong ini. \n\n \"Ramona\""
  },
  Mail_123544_Name = {
    Text = "Teka-teki Pikiran"
  },
  Mail_123544_Sender = {Text = "\"Ramona\""},
  Mail_123545_Desc = {
    Text = [[
Utusan Pucat yang terhormat: 

 Sebelumnya saya bertanya kepada wanita yang sangat cerdas di dalam Mythag, apakah ada tempat kosong untuk saya menumbuhkan beberapa bunga. 
 Nona Doll dengan mudah menemukan sebuah kamar untuk saya, meskipun saat pertama kali membuka pintu, bau busuk yang menyebar di dalamnya membuat saya ragu apakah saya berada di tempat yang benar, namun setelah beberapa perawatan, sekarang tempat itu sudah bisa menjalankan fungsinya dengan baik, memberikan rumah yang hangat bagi anak-anak ini. 
 Namun karena kurangnya pengalaman, saya harus memberi sedikit dorongan eksternal untuk memastikan anak-anak ini dapat tumbuh dengan baik. 
 Untungnya, di bawah bimbingan Nona Horla, saya berhasil membawanya ke tahap sekarang. 
 Tentu saja, tidak ada kemampuan khusus yang digunakan dalam proses ini. 
 Jika tidak ada kesalahan dalam perhitungan, mereka akan mekar pada hari ulang tahun saya, meskipun saya terus-menerus mengulang bahwa tidak ada yang istimewa pada hari ulang tahun tersebut, tetapi munculnya kebetulan yang jarang ini memang sulit untuk tidak membuat orang berpikir, mungkin ini adalah hadiah kecil yang diatur oleh Sang Bapa. 
 Saya tidak tahu apakah Anda tertarik untuk berbincang dengan saya di taman kecil ini, merayakan hari yang biasa namun istimewa ini? 
 Saya telah menyiapkan kue yang saya panggang sendiri dan teh merah yang Anda rekomendasikan sebelumnya, berharap untuk berbagi hadiah yang langka ini dan keharuman yang hanya dimiliki oleh kehidupan. 

 Salvador]]
  },
  Mail_123545_Name = {
    Text = "Kebun Dalam Ruangan"
  },
  Mail_123545_Sender = {Text = "Salvador"},
  Mail_123546_Desc = {
    Text = "Pasangan: \n\nApakah kamu pernah mendengar sebuah cerita seperti ini? \nDulu ada seorang iblis, yang terkurung dalam botol karena suatu kecelakaan, selama ratusan tahun. \nDi abad pertama, ia berjanji memberikan kekayaan dan kekuasaan yang tak terhingga kepada orang yang membebaskannya. \nDi abad kedua, ia berjanji memberikan kesehatan dan umur panjang yang abadi kepada orang yang membebaskannya. \nDi abad ketiga, keempat, kelima, setelah waktu yang sangat lama, ia akhirnya menunggu nelayan yang membuka tutup botol—ia tidak merespons panggilan nelayan, bahkan tidak ingin lagi mengacaukan dunia ini, hanya berpura-pura menjadi sebuah botol kosong biasa, diam-diam dilempar kembali ke laut. \nSaat aku kecil, aku tidak bisa memahami cerita ini. Hingga aku menyadari betapa menantinya yang panjang dan tanpa harapan itu, betapa membosankan dan menyakitkan, membuat keinginan menjadi lebih sulit ditanggung daripada putus asa. \nNamun sebelum rasionalitasku bereaksi, hatiku berkali-kali membiarkanku tetap di tempat yang sama. \nPerbedaan antara iblis dan manusia mungkin terletak pada kenyataan bahwa aku sedikit bersyukur atas rasa sakit ini. Karena saat kita berpisah, itu mengingatkanku akan keberadaanmu dan betapa berharganya dirimu, membuatku tidak tersesat di sisi lain yang tanpa dirimu. \nDi hari kelahiranku, di hari ketika aku sangat merindukanmu, ia tetap mengekangku, membuatku terus menunggu dan merindukanmu. \nSemoga di hari yang berikutnya, aku bisa menyerahkan sendiri potongan pertama kue yang aku potong untukmu. \n\nRamona"
  },
  Mail_123546_Name = {Text = "Cerita"},
  Mail_123546_Sender = {Text = "Ramona"},
  Mail_123547_Desc = {
    Text = [[
Kantin Mythag dan departemen logistik telah menempatkan tumpukan barang yang tidak perlu di depan pintuku, sangat mengganggu akses keluar masuk, sebaiknya kalian segera membawanya kembali. 
 Ada apa, apakah persediaan makanan di dunia ini terlalu banyak sehingga tidak ada tempat yang lebih berarti untuk ditempatkan? 
 Hari ini hanya akan menjadi catatan dalam perjalanan aku menjadi lebih kuat, membantu aku menandai satu siklus lagi yang telah berlalu, setahun, dan setahun berikutnya, setiap tahun aku akan menjadi lebih kuat daripada tahun sebelumnya. 
 Jika hadiah itu benar-benar tidak ada tempatnya, bisa diberikan kepada diriku yang lain, dia mungkin akan sangat senang. 
 Dan aku, demi kebodohan dan ketekunanmu... demi hal-hal yang paling tidak aku kuasai. 
 Selama aku masih ada, aku akan terus menjadi lebih kuat, dan pada saat yang sama... 
 Apa kalian masih tidak mengerti? Musuh dari orang-orang bodoh ini, juga akan menjadi musuhku. 
 Kalimat menjijikkan ini hanya akan kukatakan sekali, tahun depan jangan lagi mengirim hadiah, apalagi makan malam ulang tahun. 

"H"]]
  },
  Mail_123547_Name = {
    Text = "Bawa kembali"
  },
  Mail_123547_Sender = {Text = "\"H\""},
  Mail_123548_Desc = {
    Text = "Kepada Penjaga yang terhormat: \n\nTahukah kamu? Beberapa hari yang lalu, seorang wanita misterius tiba-tiba mengunjungi Mythag. Dia mengenakan gaun panjang hitam yang ketat dan berkilau yang belum pernah saya lihat sebelumnya—saya bertanya pada Jenkin dan Mason, mereka juga belum pernah melihat pakaian seindah itu. \nBagaimana saya harus menggambarkannya? Gaun itu seolah terbuat dari rambut panjang yang paling indah, lembut, ringan, dan anggun, dengan permukaan yang memancarkan kilau khusus seperti air... \nJenkin melihat saya sangat penasaran, dengan berani bertanya kepada wanita misterius itu, dia tersenyum dan mengatakan bahwa bahan gaun itu terbuat dari sutra dari Timur, yang ditenun dari benang yang dikeluarkan oleh larva yang disebut \"ulat sutra\", dan modelnya disebut \"qipao\"... Kemudian, dia memberikan Aigis seutas benang besar—dia berkata itu disebut \"sehelai\" sutra yang sama... \n\"Sutra\" itu sangat berharga, jadi saya meniru pola yang dia berikan, dan menjahitkan \"kantong\" untuk setiap teman. Di pesta ulang tahun tahun ini, saya akan memberikan \"kantong\" itu kepada semua orang... Penjaga, apakah kamu punya waktu untuk ikut serta? \nJika kamu terlalu sibuk, saya akan meminta Brown untuk mengantarkan kantong itu ke asramamu. \n\nAigis"
  },
  Mail_123548_Name = {
    Text = "Wanita Misterius"
  },
  Mail_123548_Sender = {Text = "Aigis"},
  Mail_123549_Desc = {
    Text = [[
Bibit kecil: 

Tahukah kamu bagaimana pohon mencatat waktu dan pertumbuhannya? Dengan lingkaran-lingkaran tahun yang berulang. 
Mereka tersembunyi di dalam tubuhnya, tidak pernah menunjukkan diri dengan mudah, sampai tunas kecil tumbuh perlahan menjadi pohon raksasa yang menopang langit yang menjulang tinggi. Jejak waktu itu, tersembunyi di dalam hati tanpa meninggalkan jejak. 
Hari ini, adalah titik awal pencatatan lingkaran tahun yang baru. Di tahun yang baru ini, kita masih harus menghadapi banyak badai yang belum kita duga. 
Tetapi biji yang aku titipkan di mulutmu, pasti akan menemukan tanah yang cocok untuk membesarkannya, lalu berakar dan berkecambah, bukan? 

Tayisi]]
  },
  Mail_123549_Name = {
    Text = "Cincin pertumbuhan…"
  },
  Mail_123549_Sender = {Text = "Thais"},
  Mail_123644_Desc = {
    Text = [[
Tanpa sadar, ini sudah menjadi ulang tahunku yang ketiga yang aku habiskan di Mythag, dan aku telah belajar banyak hal. 
 Misalnya, pada hari ulang tahunku ini, juga merupakan Festival Penyeberangan Musim Dingin, hari yang cocok untuk memberikan Hadiah. 
 Meskipun kau memiliki banyak musuh yang sangat kuat, tapi aku paling mahir dalam membunuh. Aku tidak tahu cara lain yang membuat orang bahagia, dan aku juga tidak pandai memilih Hadiah, namun setiap kali aku berhasil menyelesaikan tugas, sepertinya majikanku sangat senang. 
 Jadi, aku sudah memikirkan Hadiah yang akan aku berikan padamu, sebuah kontrak pembunuhan, tanpa batasan objek penggunaan, tanpa batasan waktu penggunaan. 
 Cukup beri tahu aku, siapa targetnya? Bagaimana kau ingin Dia mati? Jika itu adalah orang yang bisa aku kalahkan, aku akan dengan cepat mematahkan lehernya untukmu. Bahkan jika Dia sekeras dewa, aku bisa menjamin bahwa aku tidak akan menyerah sebelum kematianku tiba. 

 Helot]]
  },
  Mail_123644_Name = {
    Text = "Katakanlah, siapa yang kamu ingin mati?"
  },
  Mail_123644_Sender = {Text = "Helot"},
  Mail_124059_Desc = {
    Text = "Kepada Penjaga yang terhormat:\n Acara \"Pengorbanan jurang·Replikasi\" telah berakhir. Saat ini, sisa \"Air mata pengorbanan\", \"Darah pengorbanan\", dan \"Sum-sum pengorbanan\" milik Penjaga akan dikonversi dengan rasio setiap item menjadi \"Rose Scrip\"× 40. Harap Penjaga memeriksa penerimaannya."
  },
  Mail_124059_Name = {
    Text = "Pengorbanan Jurang: Mata Uang Daur Ulang"
  },
  Mail_124059_Sender = {
    Text = "Dewan Sekolah Mythag"
  },
  Mail_124290_Desc = {
    Text = [[
Penjaga:

Seperti yang Anda ketahui, kebahagiaan sebenarnya adalah emosi yang agak asing bagi saya. 
Saya sering merasa, dunia biasa adalah keramaian di permukaan air yang tidak dapat saya pahami, sebelum saya benar-benar terlibat, kekeringan yang seharusnya milik saya sudah tiba. 
Terkadang itu membuat saya merasa rindu, tetapi lebih sering membuat saya bingung dan tercekik. Hanya di setiap hari seperti hari ini, demi tidak membuat ayah dan ibu sedih, saya berusaha keras untuk bertahan... sampai hari pembebasan tiba, sampai laut menerima saya. 
Saya pikir, hanya air yang dalam adalah rumah saya. Namun, Penjaga, karena Anda, dan keberadaan semua anggota Mythag, bahkan seseorang seperti saya yang tidak cocok dengan dunia biasa, bisa mulai merasakan kehangatan nyata. Seperti teratai yang mengapung, sinar matahari juga akan mencium daun dan kelopaknya. 
Meskipun berantakan, saya merasa perlu untuk mencurahkan perasaan ini di atas kertas, dan mengirimkannya kepada Anda, mohon maaf atas sifat kekanakan saya kadang-kadang. 
Saya hanya berharap Anda tahu, betapa berharga kehadiran Anda di dalam air yang terlalu cepat ditutupi kesunyian, yang membawa saya ke permukaan. 
Semoga Anda selalu bahagia, selalu damai. 

Nymphaea]]
  },
  Mail_124290_Name = {Text = "Muncul"},
  Mail_124290_Sender = {Text = "Nymphaea"},
  Mail_124291_Desc = {
    Text = [[
Penjaga:

Pagi ini, di samping tempat tidurku muncul sebuah surat, isinya adalah undangan untuk menghadiri pesta ulang tahunku sendiri, ditandatangani oleh klub "Sang Pelukis".
Baru aku ingat bahwa bulan lalu saat aku memiliki sedikit waktu luang, aku setuju untuk menjadi model untuk kompetisi kreatif edisi baru "Sang Pelukis" yang diadakan oleh Sanga. Sebelumnya, aku telah menolak berkali-kali. Saat berdiri di panggung model tanpa bergerak untuk dipahat, aku teringat kembali pada hari-hari di altar Pelaut. Saat itu, aku juga menerima semua pandangan orang, tetapi dari pandangan itu hanya ada ketakutan dan rasa hormat, tanpa satu pun sentuhan, pujian, atau penghargaan.
Malam ini di aula klub Sang Pelukis, juga akan dipamerkan karya-karya tangan yang dibuat dengan cermat oleh lebih dari sepuluh pelukis pada hari itu. Meskipun aku kurang percaya diri dengan seleramu, tetapi terpapar lebih banyak tidak akan menjadi hal yang buruk. Ibu Dewa mengundangmu sebagai tamu untuk bersama-sama menikmati interpretasi mereka terhadap "Saya".

"Murphy"]]
  },
  Mail_124291_Name = {Text = "Pelukis..."},
  Mail_124291_Sender = {Text = "\"Murphy\""},
  Mail_124292_Desc = {
    Text = [[
Penjaga: 

Sylvia memberi tahu saya, terkadang mengungkapkan kebutuhan kita kepada hubungan dekat dapat membantu meredakan ketakutan yang terus-menerus mengikuti saya. Saya tidak yakin apakah itu berhasil, tetapi tidak diragukan lagi, hari ini adalah waktu yang baik. 
Apakah kamu mau mengabulkan satu permintaan saya? Saya bisa memberikan semua ransum laboratorium hari ini kepadamu. 
Tidak, bukan sekantong biji kopi. 
Meskipun kegelapan yang menakutkan itu telah mengambil hampir semua hubungan dekat saya dan terus-menerus menakut-nakuti saya, namun kamu telah mengatasinya. 
Kamu membuat kami hidup dengan aman di Mythag, atau setidaknya sampai sekarang kami masih hidup dengan aman di Mythag. 
Saatnya untuk melepaskan ketergantungan kafein yang tidak sehat, Penjaga. Apakah kamu bisa meluangkan sedikit waktu sore ini? 
Jika kamu ada di sampingku, mungkin aku bisa mengumpulkan keberanian untuk beristirahat sejenak di tempat dengan cahaya yang tidak terlalu terang, meskipun hanya sebentar. 

Sangat ingin mengingat bagaimana rasanya tidur dengan tenang, Winkle]]
  },
  Mail_124292_Name = {
    Text = "Keinginan…"
  },
  Mail_124292_Sender = {Text = "Winkle"},
  Mail_124293_Desc = {
    Text = "Penjaga{Male=Tuanku,Female=Nona}:\n\nPagi ini, sebuah mimpi membangunkan saya. \nSaya mengingat dengan seksama semua yang terjadi dalam mimpi itu: angin sepoi-sepoi berhembus di bawah sinar matahari yang hangat, mawar dan tulip memenuhi seluruh tanah, seribu burung camar dan orang-orang bahagia bernyanyi bersama… Sudah lama saya tidak berada di pemandangan yang begitu bahagia. Saya rasa saya mungkin berada di perkebunan masa kecil, di Rumah Bunga Colette, atau di taman di Cité… Namun ketika saya berbalik, saya melihat gedung-gedung Gothic yang indah di Mythag, dan Anda, Penjaga{Male=Tuanku,Female=Nona}. Anda berdiri di antara bunga dan sinar matahari, menjadi ungkapan yang paling indah dalam puisi ini. \nSaya sangat mencintai Cité, Penjaga{Male=Tuanku,Female=Nona}. Namun saat itu saya tiba-tiba menyadari, saya mulai terbiasa dan terpesona dengan segala sesuatu di sini, di dunia ini akhirnya ada tempat yang lebih membuat saya terikat daripada Cité. \nUlang tahun adalah akhir dari sebuah masa dan juga awal dari masa yang lain. Pada hari di mana masa baru dimulai ini, saya tidak tahu apakah di antara sinar matahari dan mawar yang mekar di taman belakang Mythag, akan ada orang yang bersedia membawa saya untuk mendengarkan angin sepoi-sepoi, yang membuat saya terikat dalam mimpi? \n\nHorla"
  },
  Mail_124293_Name = {
    Text = "Mimpi Bunga dan Puisi"
  },
  Mail_124293_Sender = {Text = "Horla"},
  Mail_124294_Desc = {
    Text = "Penjaga yang tercinta: \n\n Beberapa waktu yang lalu, saya selalu berpikir untuk memberikanmu sebuah hadiah istimewa. Jenkin menyarankan untuk membuatkanmu pakaian baru dengan tangan sendiri, dan saya rasa itu adalah ide yang sangat baik. \n Ini adalah model potongan yang paling saya kuasai saat bekerja di pabrik tekstil, semoga sekarang masih terlihat tidak ketinggalan zaman... Lainnya, saya jarang mendapatkan dukungan untuk keputusan saya, pola garis dan kotak yang ceria di atas adalah hasil dari saya yang berbeda. Dan ini, gambar tikus lucu yang miring dan berkelok-kelok, adalah sesuatu yang kucing \"24\" bertekad untuk ditambahkan, katanya itu mewakili Cokelat, yaitu hal yang paling saya sukai dari kepribadian kucing—tidak tahu apakah itu cocok, tapi saya harap kamu menyukainya. \n Di tahun baru ini, saya masih tidak memiliki keinginan ulang tahun. Kamu selalu begitu lembut, setiap tahun mengingatkan saya untuk merayakan dengan baik. Namun dibandingkan dengan dirayakan, bisa menjahit sesuatu untukmu dengan tangan sendiri, membuat saya merasa lebih tenang dan bahagia. \n Silakan terima pakaian baru ini yang penuh dengan perasaan. \n\n Mason"
  },
  Mail_124294_Name = {
    Text = "Sebuah pakaian baru"
  },
  Mail_124294_Sender = {Text = "\"24\""},
  Mail_124295_Desc = {
    Text = [[
Tsk: 

Sulit dipercaya, sebagai Pemilik Labirin yang agung, aku berhasil bertahan hidup selama setahun lagi dalam cobaan yang sulit ini. 
Dengarkan! Semua ini adalah kesalahanmu dan akademi bodoh ini! 
Meskipun kalian terus mencuciku dengan omong kosong, hal-hal sepele ini seharusnya dikerjakan oleh orang yang tepat. Baiklah, aku sudah cukup hebat, aku bahkan tidak menyebut mereka sebagai budak. 
Para tua yang keras kepala menyebut ini sebagai... apa ya, kemajuan. 
Tunggu, kenapa aku juga terjebak dalam logika ini, aaaah, menyebalkan! (Di sini ada banyak lipatan acak akibat pemilik surat yang marah.) 
Lupakan, karena aku sudah "berkemajuan", kamu juga harus menunjukkan itikad baikmu. Di hari yang begitu besar ini, kamu tidak bisa hanya menunggu aku mengingatkanmu seperti dua tahun lalu, kan? 
Aku memberi waktu tiga puluh menit, Penjaga, datanglah menemuiku dengan hadiah. 
Jika tidak, aku akan membiarkan anak-anakku merangkak ke wajahmu saat kamu tidur. 

Agrippa]]
  },
  Mail_124295_Name = {Text = "Kemajuan"},
  Mail_124295_Sender = {Text = "Agrippa"},
  Mail_124296_Desc = {
    Text = "Penjaga!\n\nAku melihatnya! Betapa menawannya pemandangan itu! Aku yakin itu bukan mimpi! Aku berdiri di sana, di samping patung peringatan megah di pemakaman Mythag, memandang ke arah nisan-nisan tanpa tulisan yang membentang tak berujung, aku yakin mereka dapat memberiku ilham yang belum pernah ada sebelumnya, tetapi aku tidak menyangka, mereka memberiku jauh lebih banyak daripada yang aku bayangkan, mereka mengejek imajinasiku yang tandus dengan kemurahan hati yang mengagumkan.\nAku melihat roh-roh para penyelidik, mereka berdiri bersama di senja indah yang berkabut. Aku tidak bisa melihat wajah mereka, tetapi aku melihat gerakan mereka—seperti tarian anggun, juga seperti ritual misterius. Mereka memberi penghormatan ke arah kolam hitam, ke arah Mythag dan Anda. Para seniman di salon modern terobsesi dengan menggambarkan individu, sering kali mengkritik pemandangan megah ini, tetapi aku tidak pernah berpikir demikian. Menghadapi pesta dansa para zombie membuatku sangat gembira, dan hari ini, pemandangan ini membuatku tak kuasa menahan air mata.\nAku rasa ini bukan kebetulan. Hari ini, kebetulan pada hari ulang tahunku, mereka menunjukkan tarian megah mereka kepadaku, aku yakin mereka ingin aku menyampaikan sesuatu. Aku tidak memiliki keahlian selain kuas, tetapi itu sudah cukup, bukan?\nSketsa lukisan ini sudah selesai, Penjaga, tolong datanglah ke studio seniku untuk melihatnya! Semua keinginan para penyelidik legendaris yang telah kehilangan nama, ingin mereka sampaikan kepada Anda, semua itu ada di kanvasku!\nAku tidak berani memberi nama pada lukisan ini, aku rasa, hak itu seharusnya milik Anda.\nCatatan: Aku benar-benar tidak mencari mayat, aku berjanji padamu!\n\nPickman"
  },
  Mail_124296_Name = {
    Text = "Harapan Penyelidik"
  },
  Mail_124296_Sender = {Text = "Pickman"},
  Mail_124297_Desc = {
    Text = "Halo, Penjaga: \n\nApakah kamu merasa takut, atau lebih tepatnya—baik takut, sekaligus menantikan sesuatu yang akan dibawa oleh diriku pada hari kelahiranku, dengan dalih perayaan? \nKedekatan yang berpura-pura, malam yang tiba-tiba penuh gairah, atau ilusi yang aneh dan memabukkan? \nAh, tidak ada satu pun, bahkan aku, terkadang juga berbicara tentang topik yang serius dan membosankan. \nKamu seharusnya sangat paham tentang diriku, yang terjebak dalam kenikmatan, bahkan jika bangunan akan runtuh. \nCinta dan nafsu tidak dapat menyembuhkan kebosanan, penyakit terbesar di dunia ini, tetapi sebagai pemicu untuk menghadirkan kekuasaan dan rasa kekacauan, itu sangat cocok. \nSayangnya, selama berabad-abad ini, mungkin karena aku terlalu mendalami penelitian tentang drama, selalu ada orang bodoh yang mengupas hati dan hati, mengatakan bahwa aku melihat jiwa kesepian dan tanpa perlindunganmu. \nHuh. \nBahkan aku yang suka berpura-pura juga sering merasa mual. \nDan kamu… untuk apa kamu terhubung denganku? Untuk mengontrol, untuk membatasi, untuk memanfaatkan? \nKamu ingin melindungi lebih banyak hal, maka kamu pasti memerlukan kekuasaan yang lebih tinggi, dan keinginan untuk kekuasaan akan melahirkan ambisi yang lebih besar, kapan itu akan matang, kapan akan diserap ke dalam perut... sungguh membuatku hanya memikirkan itu sudah merasa sangat tertarik, rela berlama-lama di sisimu untuk lebih banyak, lebih banyak tahun. \nHush, tidak perlu memberitahuku jawabannya. \nSetiap tahun pada hari ini, mencuri mimpimu selama semalam, merasakan dan menilai apakah ambisimu sedang berkembang, apakah niatmu telah bergeser, adalah hadiah ulang tahun terbaik yang bisa aku berikan untuk diriku sendiri. \nHarap jangan marah. \n\n\"Seribu Kipas\""
  },
  Mail_124297_Name = {
    Text = "Malam yang indah"
  },
  Mail_124297_Sender = {Text = "Xu"},
  Mail_124298_Desc = {
    Text = [[
Penjaga: 

 Latihan, pertempuran, patroli, sejak aku bergabung dengan militer, aku sudah terbiasa mengisi semua waktuku dengan urusan yang dibutuhkan oleh kelompok. 
 Kemudian, saat memimpin Arans bermigrasi di padang pasir, urusan ini semakin membengkak, hingga terukir dalam pikiranku seperti hukum, sehingga ketika tiba di Mythag, aku selalu mengutamakan jadwal kelompok di atas urusan pribadi. 
 Namun, dalam berinteraksi dengan orang lain, terutama denganmu, aku menyadari bahwa baik sebagai Awakener maupun sebagai manusia, kita semua memerlukan waktu yang hanya untuk diri kita sendiri, untuk merasakan kebersamaan dengan orang-orang yang penting. 
 Karena hubungan yang berharga ini, mengikat kita dalam keberadaan waktu, dan membuat keberadaan kita benar-benar memiliki makna yang tak tergantikan. 
 Meskipun agak berani, aku sudah membatalkan semua urusan kelompok hari ini, memberikan satu hari penuh untuk kita. 
 Hanya perlu beberapa jam, tidak, bahkan satu jam, atau beberapa menit saja, asalkan kamu bersedia memberikan sedikit waktu pribadi untukku, itu akan menjadi makna bagiku untuk menjalani hari istimewa ini. 

 Alva]]
  },
  Mail_124298_Name = {
    Text = "Waktu pribadi"
  },
  Mail_124298_Sender = {Text = "Alva"},
  Mail_124299_Desc = {
    Text = "Si kecil: \n\n Satu tahun mungkin terasa lama bagimu, tetapi bagi para pelintas Lautan Kekuatan Kuno, itu hanyalah secebis air laut yang sekejap berlalu di lautan waktu yang tak terbatas. Untungnya, di dalam air laut ini masih ada beberapa tetesan air yang mengesankan. \n Hari diskon di Toko Kecil Penghilang Kekhawatiran tentu adalah yang paling berharga untuk disimpan. Bukan hanya karena ia akan membawa kupon emas, tetapi yang lebih penting, aku tahu pada hari ini, seorang tamu pasti akan datang ke toko kecil ini. \n Semua koneksi antar manusia adalah bisnis, dan semua bisnis adalah koneksi antar manusia. Setiap tamu akan memasuki toko kecil mereka pada waktu tertentu, dan setiap toko kecil akan menyambut tamu mereka pada waktu tertentu. Dalam waktu yang panjang ini, aku telah melihat tak terhitung banyaknya harta karun, dan pada akhirnya, momen-momen naif ini akan menjadi koleksi yang paling berharga—mereka adalah alasan keberadaan waktu yang panjang ini. \n Dalam satu tahun ini, koleksi baru yang paling berharga sedang disimpan di etalase, menunggu dengan tenang untuk tamunya yang ditakdirkan. \n Segeralah datang, si kecil. \n Toko Kecil Penghilang Kekhawatiran sudah tutup lebih awal. Hari ini, pintunya hanya dibuka untuk satu orang. \n\n Daffodil"
  },
  Mail_124299_Name = {
    Text = "Barang koleksi baru"
  },
  Mail_124299_Sender = {Text = "Daffodil"},
  Mail_124300_Desc = {
    Text = [[
Penjaga:

Tidak tahu apakah kamu masih ingat, momen ketika kita berada di depan pintu bersama? Hari itu aku membuka sedikit kebenaran, menunjukkan kepadamu yang nyata dari alam semesta. 
Yang mengejutkan, saat kamu menjalani pandangan jauh ke banyak dunia yang abadi, aku justru merasakan sedikit emosi yang sulit dipahami dalam sekejap yang cepat berlalu. 
Aku sering memikirkan perasaan pada momen itu, mengapa aku yang memahami kebenaran bisa merasakan sesuatu yang tidak bisa dipahami. 
Aku berpikir cukup lama, berdasarkan sistem pengukuran dunia nyata, itu adalah waktu yang bisa disebut sebagai "abadi". 
Dalam waktu yang terlihat agak panjang dalam konteks alam semesta ini, aku menyadari bahwa ini mungkin adalah keajaiban yang belum terdefinisi. 
Pada hari istimewa ini, aku ingin mengundangmu untuk terhubung denganku, melalui pandanganku, untuk mengobservasi beberapa eksistensi yang belum pernah aku observasi, kali ini apa yang kita amati... tidak akan lagi menjadi apa yang sudah ditentukan. 
Kita akan bersama-sama mencari masa depan di luar kebenaran ini. 

Tawil]]
  },
  Mail_124300_Name = {
    Text = "Di luar kebenaran"
  },
  Mail_124300_Sender = {Text = "Tawil"},
  Mail_124301_Desc = {
    Text = [[
Penjaga:

Tahun ini seperti tahun-tahun sebelumnya, saya menghentikan semua urusan lain, dengan tenang menyendiri, berusaha untuk menulis ulang dan memperbarui kenangan yang berkaitan dengan tanah air saya. 
Mereka semakin jauh dari saya, bahkan jika saya memaksa diri untuk terbiasa dengan tubuh humanoid ini, berusaha sekuat tenaga untuk mengingat dan menceritakan pengetahuan serta pengalaman yang berkaitan dengan lautan, dalam dunia yang semakin memudar ini, melupakan masih jauh lebih mudah daripada mengingat. 
Satu-satunya penghiburan adalah, kini kami para pelancong yang jauh dari Lemuria, masih memiliki tempat ini untuk berhenti, dapat mengikuti perintah raja kami, dengan tenang mengikuti, dengan tenang menunggu. 
Saya sangat menyadari segala pengorbanan dan usaha yang Anda lakukan untuk ini, saya tidak tahu bagaimana mengungkapkan rasa terima kasih saya kepada Anda, sebelum saya bisa kembali ke Lemuria, jika ada yang bisa saya bantu, saya juga siap untuk memberikan semua cahaya saya untuk itu. 

Dengan tulus, Faros]]
  },
  Mail_124301_Name = {Text = "Mercusuar"},
  Mail_124301_Sender = {Text = "Faros"},
  Mail_124302_Desc = {
    Text = "Kekasih Penjaga: \n\nSejak hari aku bergabung dengan Mythag, berbagai aturan telah membelengguku. Tidak boleh membawa pelayan berjalan-jalan di tempat pertemuan, tidak boleh menginjak wajah siswa di alun-alun kampus, tidak boleh mengadakan acara kelompok di aula… \nPara pembela prinsip yang menyebalkan di Mythag telah mengurungku, ini bukan kehidupan yang seharusnya dinikmati oleh Ratu Isaraul. Aku seharusnya menikmati segala sesuatu yang menjadi hakku, anggur yang memabukkan, punggung yang lembut, dan pelayan tercintaku… Pada hari ulang tahunku yang seharusnya aku nikmati dengan bebas, pikiran seperti ini muncul dengan sendirinya. \nMalam telah larut, kesabaranku terhadap hal-hal sepele telah habis. Aku tidak akan mengirimmu untuk menjalankan tugas tengah malam, dan aku tidak akan membiarkanmu menebak-nebak. Aku butuh kamu di sampingku. \nSekarang, datanglah ke ladangku, jangan ragu, lepaskan semua pakaian dan gelar yang tidak perlu. \nMalam ini, dan setiap malam setelahnya, kamu adalah milikku. \n\nKamu bisa menganggap ini sebagai tugas permanen pertamamu. \n\nWanda"
  },
  Mail_124302_Name = {Text = "Aturan"},
  Mail_124302_Sender = {Text = "Wanda"},
  Mail_124303_Desc = {
    Text = [[
Penjaga: 

Tinct memberi tahu saya bahwa dia merencanakan perjalanan antarbintang setelah ulang tahunnya dengan penghasilan dari konser pribadinya, dan ingin membawa saya bersamanya. Tapi... jika saya ikut, dia pasti akan terganggu merawat saya. Saya tidak ingin kebahagiaannya terpengaruh oleh saya. 
Dia sangat mencintai cahaya dalam hidupnya, terpesona oleh ribuan warna dan aliran bintang di alam semesta ini. Jika dia membawa saya, dia mungkin tidak bisa bernyanyi dengan bebas dan menatap dengan sepenuh hati... 
Jadi... bisakah Anda membantuku untuk meyakinkannya? Biarkan dia pergi berpergian sendiri, mengadakan konser di planet-planet yang berbeda, dan merangkul semua pemandangan yang dia impikan... Atau mungkin Anda bisa menggantikan saya untuk ikut perjalanan ini? Toh Tinct dan saya sangat berterima kasih kepada Anda, dan ingin membalas budi Anda... Jika Anda mau... 
Tapi, tolong jangan beri tahu dia bahwa ini adalah keinginanku. Saya tidak ingin menjadi penghalang dalam perjalanan bebasnya. 

Faint]]
  },
  Mail_124303_Name = {
    Text = "Tentang perjalanan"
  },
  Mail_124303_Sender = {Text = "Faint"},
  Mail_124304_Desc = {
    Text = [[
Dermawan: 

Hari-hari yang dihabiskan bersama Pollux di Misgar begitu tenang, begitu cerah, seolah-olah sebuah mimpi... 
Pollux sekarang meskipun masih menjaga etika itu, berbicara dengan kata-kata yang sopan dan tepat, aku bisa merasakan dengan jelas, dia perlahan-lahan kembali menjadi dirinya yang dulu. Jarak yang mengagumkan, yang milik "Anak Suci", perlahan-lahan mencair dalam keseharian yang lembut ini. Semua perubahan yang lembut ini, berkat Anda. 
Aku sering berpikir, apa yang bisa aku lakukan untuk membalas kebaikan ini? Aku tidak sehandal Pollux yang bisa membuat hadiah yang membuat Anda terkesan. Kesenangan terbang, Anda juga sudah merasakannya banyak kali bersamaku. Tentang bagaimana membagikan kebahagiaan ini kepada Anda di hari istimewa ini, aku telah berpikir diam-diam cukup lama. 
Mungkin... Anda akan menyukai bulu-buluku? Banyak yang mengatakan, ia memiliki kelembutan yang dapat menenangkan hati. Jadi, jika suatu hari Anda merasa lelah, atau hanya ingin mencari sudut yang tenang, silakan datang kepadaku kapan saja. Sayapku, selalu bersedia menjuntai untuk Anda. 

Castor]]
  },
  Mail_124304_Name = {Text = "Bulu"},
  Mail_124304_Sender = {Text = "Castor"},
  Mail_124305_Desc = {
    Text = "Kekasihku yang kecil·terkurung·: \n\n Saya mendengar bahwa Mythag baru-baru ini sedang populer dengan permainan peran, tentang penyihir, manusia serigala, dan lain-lain... Tsk, terdengar sama sekali tidak romantis~ Saya malah memikirkan permainan yang lebih menyenangkan! \n Begini, kamu berperan sebagai tahanan, dan saya berperan sebagai penjaga. Ketika saya mengayunkan cambuk kecil, saya ingin mendengar suara jeritan keras ya~ Lilin mengalir di atas tubuhmu, membawa rasa sakit yang membara dan kebahagiaan... Ah, hanya dengan membayangkan adegan itu, saya sudah mulai merasa manis~ \n Ayo, melihat ini, kamu pasti sudah mengerutkan dahi lagi, kan? Sungguh nakal, hari ini adalah hari ulang tahunku~ Kekasihku yang kecil, seharusnya memenuhi sedikit keinginanku yang nakal, kan? \n Jika tidak bisa... bagaimana kalau... kamu yang menjadi penjaga, dan saya menjadi tawananmu, bagaimana? Saya akan memuaskanmu~ \n\nPandia"
  },
  Mail_124305_Name = {
    Text = "Peran berdasarkan situasi"
  },
  Mail_124305_Sender = {Text = "Pandia"},
  Mail_124306_Desc = {
    Text = [[
Penjaga: 
Kebaikan, hari ini adalah hari ulang tahunku. Di hari istimewa ini, aku ingin memberitahumu tentang kabar terbaruku: di bawah bimbingan Goliath dan Tuan Lotan, sepertinya... aku semakin mampu menyentuh kekuatan dalam darahku. Itu tidak lagi terlelap, tetapi berdengung dan mengalir dalam tubuhku dengan setiap latihan, secara bertahap melepaskan diri. 



Aku tidak bisa memastikan kapan tepatnya aku akan menyelesaikan metamorfosis terakhir dan menjadi keturunan Aequor yang lebih murni. Mungkin besok, mungkin minggu depan, mungkin bulan depan... tetapi ketahuilah, tidak peduli seberapa lama proses ini, berapa banyak kesulitan yang harus dihadapi, kata-kata dukungan yang kau ucapkan padaku, selalu... aku ingat dengan baik. Aku akan terus berusaha. 

Ada satu hal lagi yang harus aku minta maaf, aku baru saja mengetahui dari kantor pos Mythag bahwa untuk mengirim uang tunai bersama surat, diperlukan biaya tambahan sebesar 2. 
Untuk menutupi kekurangan tahun lalu, aku akan mengeluarkan uang tambahan dari tabunganku. Itu sulit didapat bagiku, tetapi darah Aequor memiliki janji yang pasti akan ditepati. 

Caecus]]
  },
  Mail_124306_Name = {
    Text = "Biaya layanan……"
  },
  Mail_124306_Sender = {Text = "Caecus"},
  Mail_124307_Desc = {
    Text = "Penjaga: \n\nDengarkan, malam ini apapun yang terjadi, pergi bersamaku ke \"toko itu\". \nPakaian untuk menyamar sudah dikirim kepadamu, pastikan, jangan sampai orang lain mengenali kita! \nKue terbatas dari \"toko itu\" sudah dijual, orang jahat yang entah dari mana itu pasti sudah menyuap banyak orang, kita tidak boleh membiarkan mereka tahu keberadaan Nyonya! \nMeskipun orang itu sudah memesan semua kue edisi terbatas di Londinium agar aku tidak bisa membelinya, tapi… hmhm. \nNyonya sudah mengatur agar koki \"toko itu\" mengeluarkan yang terbaik dari menu. \nHmph, hari ini Nyonya akan menunjukkan kepada orang itu bahwa ada beberapa hal yang tidak bisa diselesaikan hanya dengan uang. \nNanti kita diam-diam masuk dari pintu belakang, membuka kotak besi yang telah dienkripsi tiga kali, dan kita bisa mendapatkan edisi terbatas dari edisi terbatas itu. \nSebagai imbalan, aku akan membagikan sepotong (coret) setengah kue kepadamu! \nJam sebelas malam ini, aku menunggumu di kamar, kamu harus, pasti datang! Mengerti? \nJangan sampai bocor, jika tidak, dan jika orang itu tahu keberadaan kita, semuanya akan hancur! \n\nMurphy"
  },
  Mail_124307_Name = {
    Text = "Pertempuran Berebut Kue"
  },
  Mail_124307_Sender = {Text = "Murphy"},
  Mail_124308_Desc = {
    Text = "Penjaga: \n\nDengan sangat menyesal, saya memberi tahu Anda bahwa Teater Londinium telah sepenuhnya membatalkan pertunjukan sulap Master Casiah, alasannya adalah: harga tiket terlalu tinggi, banyak hal aneh yang terlihat belakangan ini membuat orang kehilangan minat pada sulap, beberapa pertunjukan terakhir ada penonton yang hilang dan belum kembali, sering ada polisi yang menemui pemilik teater meminta Master Casiah untuk menghentikan pertunjukan dan berkooperasi dalam penyelidikan, dan lain-lain. \nBaru-baru ini, terpengaruh oleh pergerakan Blackpool, pertunjukan saya memang terkadang mengalami sedikit kesalahan, itu semua hal kecil, tetapi poin kedua adalah sesuatu yang tidak bisa ditoleransi oleh Master Casiah! \nSaya memikirkan hal ini, dan akhirnya menemukan sebuah pertunjukan baru yang sempurna! Apa itu pengendalian mayat, kebangkitan orang mati, lintas dimensi, infeksi emosi, tentakel raksasa… semua itu tidak ada artinya! Sebelumnya terpengaruh oleh anjing pemburu dimensi yang menjijikkan itu, pengendalian waktu selalu menjadi larangan dalam industri ini, tetapi setelah anjing jahat itu disegel, karir sulap Master Casiah akan naik ke tingkat baru! \nWaktu pertunjukan ditetapkan malam ini, sepenuhnya gratis, kursi di barisan depan di tengah sudah dipesan untuk Penjaga, dan ada segmen interaksi mengejutkan yang menunggu Anda! Nikmati kehormatan sebagai penonton interaktif pertama dalam pertunjukan sulap terbesar di era baru ini! \nUntuk mengembalikan kejayaan Master Casiah! \n\nCasiah"
  },
  Mail_124308_Name = {
    Text = "Casiah, buat sulap menjadi hebat lagi!"
  },
  Mail_124308_Sender = {Text = "Casiah"},
  Mail_124309_Desc = {
    Text = [[
Tuan: 

Kakak Sylvia baru saja datang memberitahuku bahwa pada ulang tahunku tahun ini, mereka akan membawaku naik bianglala. 
Lily pernah membaca di buku gambarnya, bianglala adalah roda yang sangat besar, dan duduk di atasnya bisa perlahan-lahan berputar ke langit, melihat burung-burung terbang di samping, terdengar sangat bahagia. 
Namun Kakak Sylvia bilang "sebenarnya ada beberapa perbedaan". Lily juga tidak mengerti apa maksudnya. 
Dia juga bilang, tempat yang dituju bianglala terlalu tinggi, sebaiknya aku membawa seorang pengawas. 
Lily tidak mengerti apa itu pengawas, tapi Lily ingin bepergian di antara awan bersama Tuan. 
Setelah makan siang, aku dan Kakak Sylvia akan menunggumu di luar asrama. 

Lily]]
  },
  Mail_124309_Name = {Text = "Bianglala"},
  Mail_124309_Sender = {Text = "Lily"},
  Mail_124310_Desc = {
    Text = "Penjaga (akhirnya saya menulis dengan benar kali ini! Keren, kan!):\n\nSaatnya lagi untuk menulis hal-hal manis ini, saya sudah terbiasa. Saat ini, saya dan Cokelat sedang pusing memikirkan apa yang akan kita ajak kamu makan hari ini!\nMakanan jalanan di gang Kawasan Timur tentu enak, tetapi hari ini saya berencana membawa kamu dan Cokelat untuk makan sesuatu yang lebih baik—yaitu makanan yang kamu orang Kawasan Barat suka.\nSeperti makanan rumahan yang penuh dengan saus dan rempah, porsinya kecil, piringnya besar, dan harganya selangit, rasanya seperti merampok. Memikirkan ini, saya merasa dompet saya mulai bocor, pasti itu adalah jejak uang yang pergi.\nTapi kamu adalah orang yang paling penting dan saya sukai setelah kakak dan Cokelat, orang Kawasan Timur tidak akan pelit kepada sesama, jadi semua biaya hari ini ditanggung oleh saya dan Cokelat.\nJangan remehkan kami, kami sudah menghasilkan banyak uang dengan mengantarkan susu, mengantarkan koran, dan bisnis lainnya, jadi kamu bisa tenang saja!\n\nTeman baikmu, Jenkin dan Cokelat"
  },
  Mail_124310_Name = {
    Text = "Hari ini saya dan Brown membayar!"
  },
  Mail_124310_Sender = {Text = "Jenkin"},
  Mail_124311_Desc = {
    Text = "Kepada Penjaga yang terhormat: \n\nKamu pasti sudah mendengar tentang prestasi Sylvia yang menghancurkan kasino bawah tanah Mythag, bukan? Namun hari ini adalah hari ulang tahunku, jika tidak ada kegiatan yang memicu adrenalin, bukankah itu membuang hari istimewa yang terjadi setahun sekali? \nSetelah mempertimbangkan dengan matang, saya memutuskan untuk mengundangmu sebagai sahabat baikku, untuk bersama-sama menangkap pencuri malam yang baru-baru ini mencuri harta dari museum besar, yang telah melarikan diri dari Cité ke sini. \nSaat saya sedang minum di \"Bar Apollo\" di luar kampus, saya secara kebetulan mendengar mereka dengan semangat membanggakan pencapaian mereka dalam mengumpulkan perhiasan mahal. Bartender tidak menghiraukannya, tetapi saya bisa mendengar, zamrud, safir, tiara berlian, dan barang-barang yang dicuri tersebut benar-benar cocok. Untuk menghindari kecurigaan, saya menandai mereka dengan baik, bersiap untuk menangkap mereka saat mereka kembali ke markas mereka. \nMalam ini jam tujuh, di titik parkir kereta khusus Mythag di depan sekolah, kita tidak boleh terpisah. \n\nRyker"
  },
  Mail_124311_Name = {
    Text = "Rencana Perburuan"
  },
  Mail_124311_Sender = {Text = "Ryker"},
  Mail_124312_Desc = {
    Text = [[
Penjaga:

Waktu di Mythag sepertinya berputar lebih ringan dibandingkan tempat lain. Beberapa kali tepuk tangan, beberapa kali tirai ditutup, satu tahun telah berlalu. 
Selama setahun ini, aku telah mengembangkan beberapa kebiasaan baru. Dulu, ketika aku berdiri di atas panggung, bahkan di teater yang paling ramai pun, semua orang di mataku tampak kosong. Aku menari di atas panggung yang kosong, di hadapan teater yang kosong, dan satu-satunya suara yang bergema di seluruh dunia hanyalah suara sepasang sepatu tari. Namun sekarang, setiap kali tirai dibuka, aku selalu melihatmu. Ribuan kursi kosong, hanya dirimu yang menatapku. Dalam pandanganmu, tariku kembali memiliki makna. 
Setahun telah berlalu, gerakan tarimu masih tampak canggung, tetapi tatapanmu yang melompat di bawah panggung dengan mudah melampaui langkah-langkah tari yang biasa di atas panggung. Tatapan-tatapan itu adalah sebuah arus mengapung, yang membersihkan langkah tarianku yang semakin biasa. Dalam tarian bersama para penari dan penonton ini, aku semakin mendekati aula yang selalu aku cari. Akhirnya, aku menyadari bahwa bagi tari, penonton dan penari sama-sama penting. 
Selama beberapa bulan, aku telah mempersiapkan sebuah tarian. Ia terlahir dalam cahaya pandanganmu, muncul dalam siluetmu. Kini, ia sudah siap. 
Aku rasa, ia berharap malam ini, melihatmu menjadi orang pertama yang menyaksikannya. 

Liz]]
  },
  Mail_124312_Name = {
    Text = "Penari dan Penonton"
  },
  Mail_124312_Sender = {Text = "Liz"},
  Mail_124313_Desc = {
    Text = [[
Penjaga:

Berkat penerimaan tempat ini, selama satu tahun ini, aku banyak berbincang dengan rajaku. Meskipun Kehadiran Alam Gaib masih jauh, tetapi waktu di Lemuria sepertinya sedang diperpanjang di Mythag. 
Kamu dan rajaku pernah memberitahuku, bahwa iman tidak seharusnya menjadi segalanya dalam hidupku. Aku pernah bersikeras pada pendapatku, tetapi pengalaman yang kualami belakangan ini sepertinya telah mengubah sikapku. Doa yang terlalu sering mungkin akan membuat Tuhan kita merasa terganggu. Selain dari pengabdian yang tulus, mungkin Tuhan kita juga berharap para pengikut-Nya memiliki kehidupan yang dangkal. 
Setelah menyadari hal ini, aku mencoba untuk melakukan beberapa perubahan kecil. Aku mengunjungi semua pembuat kue terkenal di Londinium dan meminta mereka untuk mengajarkan cara memanggang. Mereka memiliki beberapa rahasia yang tidak diajarkan, dan aku telah membuat mereka berbicara berkat anugerah Tuhan kita. Kemarin, aku melakukan beberapa percobaan untuk pertama kalinya, beberapa pengikut memberitahuku bahwa mereka merasa rasanya sangat enak, tetapi selera mereka sama mencurigakannya dengan kesetiaan mereka. 
Aku ingin mengundangmu hari ini untuk mencicipi di halaman rumahku. Aku percaya pada seleramu, dan juga pada keterusteranganmu. Jika tidak enak, aku berharap kamu bisa berbicara terus terang, aku akan memperbaikinya dengan serius. 
Sangat berterima kasih. 

Miryam]]
  },
  Mail_124313_Name = {
    Text = "Keahlian lain"
  },
  Mail_124313_Sender = {Text = "Miryam"},
  Mail_124314_Desc = {
    Text = "Yang Mulia Penjaga: \n\nTentang makna kehidupan dan kematian, pasti kamu sudah bosan mendengarnya, bukan? Dalam ingatan yang berkilau dari mayat hidup di Nekropolis, hal terpenting yang aku pelajari adalah, daripada mencari makna makan, yang lebih penting adalah makanan itu sendiri di atas meja. \nDi zaman kuno manusia, nenek moyang kita telah menemukan segala sesuatu tentang makna makan—gairah, keinginan, kenikmatan. Bukan untuk hidup yang kita makan, tetapi untuk makan yang kita hidup. Sayangnya, hasrat yang murni dan asli itu perlahan-lahan terlupakan seiring berjalannya waktu, dan kelompok ini menjadi semakin kompleks. \nOleh karena itu, aku menamai tema jamuan malam ini \"Murni\". Pada hari yang penuh ritual ini, segala urusan yang rumit akan menjauh dari kita. Di atas meja ini, hanya ada gairah dan keinginan yang murni dan asli, hanya ada penikmat dan makanan, hanya ada kamu dan aku. \nSilakan terima undanganku yang paling tulus. Kamu tidak akan menolak, bukan? \n\nDoresain"
  },
  Mail_124314_Name = {
    Text = "Jamuan Murni"
  },
  Mail_124314_Sender = {Text = "Doresain"},
  Mail_124315_Desc = {
    Text = "Yang Terhormat Penjaga-ku: \n\nHati saya seolah sedang tumbuh... Saya tahu ini terdengar aneh bagi Awakener, tetapi ini berbeda dari sebelumnya, bagaimana saya bisa menggambarkannya kepada Anda? \nTidak peduli seberapa lembut dan penuh kasihnya orang-orang baik itu terhadap saya, mencoba menghangatkan saya, setelah kakak pergi, dada saya selalu kosong. Semakin saya berjalan di bawah sinar matahari, semakin saya merasa tergores oleh kehangatan itu. Sebaliknya, kegelapan dan kelembapan membuat saya merasa lebih tenang, seolah-olah selama saya tetap berada di tempat yang dingin, cinta kakak yang keras dan menyakitkan tidak akan pernah pergi. \nTetapi sekarang, setelah tahun-tahun ini semakin dekat dengan Anda, setiap kali saya melihat Anda, setiap kali rasa sakit yang Anda berikan jatuh pada kulit saya, mengalir ke tulang saya—ah, kebahagiaan di dada saya semakin meningkat. Selama Anda tidak segan-segan memukul saya, menghina saya, merusak saya, saya tahu bahwa di dunia ini selalu ada tempat di mana saya benar-benar bisa bertahan. \nApakah kebahagiaan ini bisa bertahan sampai tahun depan? Sampai tahun berikutnya? Jika semua harapan yang sayaBerjanji pada hari ulang tahun terwujud, satu-satunya harapan saya adalah terus diperhatikan dengan tatapan meremehkan oleh Anda, dan rasa sakit... lebih banyak lagi rasa sakit. Saat Anda mengangkat tangan, yang pertama kali saya rasakan adalah aroma yang akrab, kejam, dan bahagia itu. \n\nSangat-sangat berharap untuk dipukul oleh Anda, Leigh"
  },
  Mail_124315_Name = {Text = "Hatiku"},
  Mail_124315_Sender = {Text = "Leigh"},
  Mail_124316_Desc = {
    Text = [[
Penjaga

Meskipun saya sangat ingin tahu tentang latihan Anda belakangan ini, tenanglah, hari ini bukanlah untuk mendorong Anda berlatih musik. 
Pagi ini, saya pergi ke ruang musik seperti biasa, tetapi saya terlambat tiga puluh lima menit. Latihan musik diadakan pada pukul tujuh pagi, kebiasaan ini telah saya pertahankan selama puluhan tahun, tetapi hari ini mudah sekali dilanggar. Alasannya adalah ketika saya melewati lorong sekolah, saya mendengar suara kicauan burung robin. 
Memecahkan kebiasaan yang telah bertahun-tahun tidaklah mudah diterima, apalagi bagi saya. Anehnya, saya tidak merasa kecewa dan marah pada diri sendiri seperti yang saya bayangkan. Pada awalnya, saya merasa panik. Namun kemudian, saya harus mengakui bahwa melodi yang berputar di kepala saya adalah sesuatu yang menyenangkan. 
Londinium selalu terbangun dengan kicauan burung robin, suara ini bisa saya dengar setiap hari, anehnya, ini adalah pertama kalinya saya memperhatikannya setelah bertahun-tahun. Saya mendengarkan nyanyian mereka dengan tenang di lorong, dan dalam tiga puluh lima menit itu, saya merasa bahwa melodi tertinggi semesta ini tersembunyi di dalam tenggorokan kecil mereka. 
Mungkin kehidupan di sini membuat orang merasa malas, atau mungkin suasana di sini membuat orang menjadi lembut. Bagaimanapun, saya rasa ini pasti ada hubungannya dengan Anda. 
Saya menerima perubahan ini dengan senang hati dalam sepuluh menit. Hidup, seperti musik, memiliki ritme dan perubahan yang abadi; mungkin hari kelahiran adalah titik di mana perubahan ini ditakdirkan untuk terjadi. Saya juga ingin berterima kasih kepada Anda, karena memberi saya kesempatan untuk tenang dan mendengarkan hal-hal yang telah saya abaikan. Menyenangkan, benar. Saya pikir, ini akan menjadi awal dari babak baru dalam hidup saya. 
Untuk itu, saya ingin mengundang Anda untuk pergi ke hutan di luar sekolah bersama saya sore ini. Suara alam di waktu senja berbeda dengan pagi, tetapi saya rasa, keduanya akan menjadi inspirasi baru dalam hidup musik kita. 

Hameln]]
  },
  Mail_124316_Name = {Text = "Suara Alam"},
  Mail_124316_Sender = {Text = "Hameln"},
  Mail_124317_Desc = {
    Text = "Yang Terhormat: \n\nSaya baru saja melihat email ulang tahun yang Faint kirimkan kepada Anda... Seperti yang saya duga, kakak selalu memikirkan orang lain, hanya saja antara saudara perempuan tidak ada yang terhutang budi, dan saya juga tidak pernah menganggapnya sebagai beban saya. Tanpa perlindungannya, saya tidak akan memiliki kesempatan untuk mengadakan konser keliling seperti sekarang. \nYang Terhormat, Anda selalu menjadi pendengar terpenting bagi saya. Jadi kali ini, saya juga diam-diam menyiapkan tiket kapal untuk Anda—dengan tulus mengundang Anda untuk bergabung dengan kami dalam perjalanan antar bintang ini. Jika Anda ikut, saya yakin beban di hati kakak juga akan berkurang banyak. \nSelain itu, silakan tenang, selama perjalanan kami tidak akan mengganggu waktu pribadi Anda. Kakak dan saya berharap, Anda bisa menikmati perjalanan ini dengan penuh kebebasan, merasakan setiap nebula, setiap pertemuan yang tidak terduga. \n\nTinct"
  },
  Mail_124317_Name = {
    Text = "Undangan Perjalanan"
  },
  Mail_124317_Sender = {Text = "Tinct"},
  Mail_124318_Desc = {
    Text = "Penjaga: \n\nHari ulang tahun semakin dekat, namun pikiranku selalu kembali ke Cité. Terutama merindukan patung-patung di pameran seni. Sikap mereka yang diam pernah berkali-kali mengetuk pintu ilhamku. \nDi studio, seharian bergaul dengan patung, kurangnya komunikasi seni, sudah lama, aku merasa bosan. Setahun yang lalu, untuk merayakan ulang tahunku, aku membuat banyak kue patung. Ketertarikan yang awalnya penuh semangat kini telah kembali tenang. \nSekarang, dengan keterbatasan bergerak, kembali ke Cité menjadi sebuah harapan yang mewah. Jika kamu kebetulan memiliki rencana untuk pergi menyelidiki, bisakah kamu memperhatikan karya-karya baru di pameran seni untukku? Aku sangat ingin merasakan kembali keindahan seni yang beragam dan inklusif melalui matamu. \nSebagai imbalan, aku bersedia membuatkanmu sebuah patung lagi, yang akan kutamai \"Penjaga di Cité\", bagaimana? \n\nSanga"
  },
  Mail_124318_Name = {
    Text = "Kenangan Cité"
  },
  Mail_124318_Sender = {Text = "Sanga"},
  Mail_124770_Desc = {
    Text = [[
Penjaga: 

Karena setiap tahun hak akses saya untuk masuk ke laboratorium dicabut, hari ini menjadi istimewa dengan cara yang tidak menyenangkan. Agar tidak membuang waktu pada hal-hal sepele yang tidak efisien, saya pergi ke arsip. 
Di sana saya menemukan dua hal, salah satunya adalah buku tugas yang penuh dengan halaman kosong yang tidak ada nilainya. 
Satu lagi juga buku tugas, yang membuat saya menyadari bahwa saya meremehkan keluasan pengetahuan, karena proses inferensi dan kesimpulan di dalamnya membuat saya tahu bahwa di dunia ini ternyata ada hal-hal yang memiliki nilai lebih rendah daripada yang tidak ada. 
Dan kedua buku tugas ini, semuanya ditulis dengan nama yang sama, yaitu Penjaga Mythag yang agung %player%. 
Erica memberi tahu saya bahwa kamu ingin tahu hadiah ulang tahun apa yang harus saya terima. 
Kamu bisa memberiku sebuah jawaban. 
Saya juga ingin tahu, fakta jawaban mana yang akan lebih mengejutkan saya. Apakah hanya sekedar kemalasan dan ketidakpedulian yang diekspresikan secara maksimal, atau kamu benar-benar belajar selama satu tahun penuh, dan akhirnya meninggalkan sampah akademis ini dalam keputusasaan yang sia-sia. 
Jika yang pertama, asalkan ada alasan yang cukup dan bisa membuktikan bahwa kamu sudah menguasai semua pengetahuan yang diajarkan di kelas, saya bisa mengajukan permohonan pengabaian tugas untukmu ke akademi. Tentu saja, ini tidak berarti saya mendukung sikap santai yang mungkin membuatmu benar-benar malas, tetapi selama kamu bisa terus lulus ujian saya, saya bukan orang yang kaku dan tidak keberatan memberikan sedikit privilese kepada murid saya. 
Jika yang kedua, sebagai pengawas pertamamu, percayalah, tidak peduli seberapa sulitnya bahan yang bisa dibentuk, kita pasti bisa menemukan teknik di dalam pengetahuan saya untuk meningkatkan keterampilanmu yang terlalu minim, menyelamatkanmu dari penderitaan karena kebodohan yang sedang kamu usahakan. 
Hari ini pukul empat sore, saya akan berada di arsip, untuk memeriksa secara langsung penguasaanmu terhadap pengetahuan di kelas, jangan terlambat. 

Doll]]
  },
  Mail_124770_Name = {
    Text = "Hak Istimewa"
  },
  Mail_124770_Sender = {Text = "Doll"},
  Mail_124771_Desc = {
    Text = [[
Anak anjing Mythag: 

 Tahun ini kamu juga terjebak dalam rutinitas yang berulang-ulang, membuat masalah, menyelamatkan dunia, berteman, belajar pengetahuan baru, terus menciptakan ilusi bahwa segalanya seperti biasa. 
 Ternyata bahkan jika otakmu diambil dari tubuhmu, dan Luminis dipindahkan dari satu dimensi ke dimensi lain, itu tidak akan memengaruhi pelarian dan kesibukanmu yang konyol hingga membuat orang tertawa. 
 Sungguh sibuk dan berisik, anak anjing tercinta. 
 Kamu tidak percaya pada fakta-fakta itu, kamu harus melanjutkan penderitaan mereka, memperpanjang proses kehancuran sedikit lebih lama, apa tujuanmu, apakah kamu berpura-pura bodoh, atau apakah manusia benar-benar bisa bodoh seperti ini? Bahkan jika aku benar-benar telah membedah korteks otak tubuhmu, semua ini tetap menjadi misteri bagiku. 
 Selamat, kamu benar-benar membuatku sedikit goyah, aku mulai meragukan, jika mengamatimu memberiku begitu banyak kesenangan, maka apakah semua ini masih bisa dikatakan tidak berarti? 
 Berdoalah dengan cara yang kamu kuasai, seperti halnya hal-hal tidak berarti yang kamu lakukan, berdoalah tanpa tujuan, siapa yang menjadi objek doamu tidak masalah. 
 Berdoalah agar kamu bisa terus mengikatku, anak anjing, sehingga aku dan kamu, dapat menemukan sedikit kesenangan dalam dunia yang tidak berarti. 

"Boneka"]]
  },
  Mail_124771_Name = {Text = "Berdoalah"},
  Mail_124771_Sender = {
    Text = "Doll: Inferno"
  },
  Mail_124772_Desc = {
    Text = [[
Partner: 

Setiap tahun pada hari ulang tahun, menulis surat untukmu sepertinya telah menjadi kebiasaan yang tidak disadari. 
Aku masih ingat, ulang tahun pertama kali aku menulis surat untukmu, juga saat ayah pertama kali mengizinkanku mengatur jadwal ulang tahunku sendiri. Aku mengundangmu untuk keluar bersamaku, dan kemudian, kita mengalami begitu banyak hal pertama bersama. 
Banyak hal telah berubah setelah itu, tetapi jika dipikir-pikir, sepertinya tidak ada yang benar-benar berubah. Kita masih berjalan di jalan yang kita anggap benar, dan kita masih saling menemani, serta, kau tetap menjadi partner terpenting bagiku. 
Jadi, meskipun ayah baru saja mengirimkan sebuah kue dan menanyakan apakah aku ingin menghadiri pesta yang diadakannya untukku malam ini, aku juga memiliki beberapa rencana lain untuk malam ini. 
Londinium baru saja merilis film baru yang sangat populer, meskipun akademi dan asosiasi sudah mengonfirmasi bahwa tidak ada reaksi spiritual di dalamnya. 
Ini menunjukkan bahwa itu hanyalah sebuah karya "biasa" yang sangat menarik. 
Kebetulan aku memiliki dua tiket, kau bisa menganggap bahwa aku tidak merepotkan Nyonya Sorel karena tiketnya memang sangat sulit didapat. 
Jadi, partner, maukah kau meluangkan waktu untukku dalam beberapa saat ini? Mungkin, kita bisa sementara waktu menjauh dari situasi abnormal yang kita hadapi setiap hari, dan menemani satu sama lain untuk menghabiskan malam "biasa". 
Setiap hari setelahnya, ketika kita terbangun, apapun yang terjadi di dunia, aku akan menghadapinya bersamamu. 

Ramona]]
  },
  Mail_124772_Sender = {Text = "Ramona"},
  Mail_124773_Desc = {
    Text = [[
Penjaga: 

 Berkat hubungan khusus antara aku dan diriku yang lain, serta tautan antara aku dan kamu, meskipun tidak selalu ada di sisimu, aku memiliki sedikit pengetahuan tentang pergerakanmu selama setahun terakhir. 
 Kamu aktif di dunia lain, tampaknya masih membawa perubahan yang disebut "harapan" ke dalamnya, meskipun setiap hari menatap dari kolam hitam, energi yang seperti cahaya ini juga menghangatkan aku. 
 Aku mulai mengembalikan jadwal sebelumnya, tetapi berbeda dari sebelumnya, kini aku tidak lagi menghadapi kepunahan yang sudah ditakdirkan dengan sikap yang sia-sia. Kamu mengajarkan aku hal baru, bahwa sebelum titik akhir yang ditakdirkan, setiap keberadaan berjuang sekuat tenaga untuk melanjutkan, itulah sebabnya peradaban, jiwa, dan kehendak memiliki makna. 
 Meskipun bagi dunia tempat aku berada, waktu ini terasa sangat singkat, aku akan terus mencoba. Bahkan hanya untuk melihat lagi wajah-wajah yang familiar dan berbicara dengan mereka, usaha ini pun tidaklah sia-sia. 
 Sampai kamu berhenti, aku akan terus berjalan di jalan ini, izinkan aku dengan egois menganggapnya sebagai cara untuk berdampingan denganmu, sehingga, mungkin di jalan yang terus berjalan ini, kamu bisa sesekali memikirkan, selalu ada aku yang berusaha sekuat tenaga melakukan hal yang sama seperti dirimu. 

"Ramona"]]
  },
  Mail_124773_Sender = {Text = "\"Ramona\""},
  Mail_124774_Desc = {
    Text = [[
Membunuh target itu mudah, tetapi membersihkan jejak adalah hal yang merepotkan. 
 Sebenarnya tahun ini saya ingin mengikuti kebiasaan tahun lalu, membantumu membunuh seseorang lagi. 
 Namun, saya memperhatikan bahwa kamu tidak pernah menggunakan hadiah yang saya berikan sebelumnya, setelah berpikir matang-matang, meskipun saya tidak tahu apakah itu sebabnya, saya menyadari kelalaian saya. 
 Kamu bisa tenang, meskipun untuk majikan-majikan sebelumnya, saya biasanya hanya menyediakan layanan untuk membunuh musuh, tetapi untuk menghindari berbagai macam masalah, saya juga sangat berpengalaman dalam menghancurkan jejak. Bahkan jika orang yang ingin kamu bunuh berada di bawah perlindungan aturan dan ketentuan yang rumit, kamu tidak perlu merasa terbebani, saya akan mengurus semuanya. 
 Saya jamin, tidak ada yang bisa melacakmu. 
 Setelah kamu memikirkan pilihan, beritahu saya namanya, di mana pun saya berada, saya akan segera datang untuk membantumu menyelesaikannya. 
 Selamat merayakan, dan semoga kamu merasa bahagia pada hari kelahiranku, Penjaga. 


 Helot]]
  },
  Mail_124774_Name = {
    Text = [[
Orang yang sering membunuh tahu 
...]]
  },
  Mail_124774_Sender = {Text = "Helot"},
  Mail_124775_Desc = {
    Text = [[
Baiklah, jelas bahwa kalian tidak bersiap untuk menghentikan perilaku ini, sejauh yang saya tahu, saya juga sudah terbiasa dengan kebiasaan "memberikan hadiah".
Tapi suatu hari kamu akan menyesali kebaikan ini, percayalah padaku.
Sekarang memikirkan kembali, itu mungkin juga salah satu hal yang paling saya sesali, sial, saya tidak pernah berpikir saya akan menyesal karena membunuh.
Tidak ada yang lebih tahu dari saya, bahwa yang disebut penyesalan itu tidak ada nilainya, tetapi sebelum hari itu tiba, saya akan berusaha melakukan sesuatu untuk menebusnya, hanya karena saya ingin melakukannya.
Ketika kamu membenci saya di masa depan karena hal itu, tidak perlu merasa terbebani secara psikologis.
Saya akan sepenuhnya menerima kemarahan kalian.

H]]
  },
  Mail_124775_Name = {
    Text = "Kamu akan menyesal"
  },
  Mail_124775_Sender = {
    Text = "Helot: Catena"
  },
  Mail_124776_Desc = {
    Text = [[
Penjaga: 

Hari kelahiran ini telah tiba lagi, seharusnya menjadi hari untuk merayakan kehidupan, jadi setiap kali hari ini datang, saya selalu merasakan beberapa perasaan yang aneh. 
Kelahiran saya tampaknya ditakdirkan untuk mengejar kematian, ketika tema kematian terlepas, kehidupan... atau bisa dibilang kesadaran tetap berlanjut dalam momen, apa artinya bagi saya? 
Sebelum mati, tarik-menarik antara penderitaan dan rasa bersalah terjalin begitu erat dengan kehidupan saya, sehingga seolah-olah hanya setelah kematian datang, kehidupan baru benar-benar menjadi milik saya. 
Tahun lalu, tahun ini, mungkin juga setiap tahun di masa depan. Saya memiliki waktu yang panjang hingga hampir tak berujung untuk merasakannya, setiap hari mirip dengan hari sebelumnya, namun juga berbeda. Ketika kehidupan tidak lagi terikat oleh penderitaan dan tujuan, bagaimana bentuk akhirnya, atau apakah yang disebut akhir itu akan datang lagi? 
Pertanyaan ini terlalu besar, saya agak bingung. 
Namun, keinginan untuk mencatat emosi dari pikiran-pikiran asing ini terasa begitu nyata, dan saya merasakan jawaban seolah-olah jelas. 
Setidaknya bagi saya, adalah momen-momen yang nyata dan berharga ini, tidak peduli seberapa rumit pikiran saya, tidak peduli bagaimana saya kesulitan menemukan akarnya, saya tahu dengan jelas ke mana mereka bisa melayang, di mana mereka bisa diterima, dan saya juga sangat ingin mengekspresikannya kepada Anda. 
Mungkin pada hari ini tahun depan, saya bisa menemukan beberapa makna yang lebih untuk diri saya, tetapi sekarang, saya berharap bisa egois untuk mempertahankan hal-hal kecil ini, yang hanya Anda dan saya yang tahu. 
Ya, Penjaga, Anda dan semua orang di Mythag adalah akar yang tidak diketahui oleh siapa pun di dalam hati saya. 
Terima kasih, seperti biasa, semoga Anda selamanya bahagia, selamanya damai. 

Nymphaea]]
  },
  Mail_124776_Name = {Text = "Akar"},
  Mail_124776_Sender = {Text = "Nymphaea"},
  Mail_124777_Desc = {
    Text = "Yü baru-baru ini menemukan cara baru untuk bersantai—Istirahat Siang Negara Dewa. \n Berbeda dari istirahat siang yang biasa dan terburu-buru, saat melakukan Istirahat Siang Negara Dewa, Yü akan meninggalkan Takhta Batu Biru tempatnya duduk terlalu lama, membentuk bola yang menghalangi suara dengan sentuhan pergelangan tangannya, lalu mengisi seluruh ruang dengan air laut khusus. \n Air laut ini tidak hanya dapat mengeluarkan aroma yang diinginkan Yü dan berubah menjadi pemandangan yang ingin dilihatnya, tetapi juga dapat menopang tubuh Yü dari berbagai arah dengan kekuatan yang tepat. \n Oleh karena itu, tidak peduli gerakan apa yang Yü lakukan, ia dapat merasakan kehangatan seolah terbungkus dalam kasur bulu angsa yang paling mewah. \n Saat itu, Yü bisa bersantai dalam aroma yang disukainya, menikmati ketenangan yang terpisah dari dunia, dan tertidur dengan nyaman bersandar pada bantal kesayangannya. \n Sebagai menteri yang paling disukai Yü, ia merasa bahwa pada hari kelahirannya, sangat cocok untuk berbagi kenyamanan ini denganmu. Jika kamu berminat, datanglah ke tempat rahasia yang pernah aku sebutkan sebelumnya. Tidak perlu khawatir tentang keselamatanmu, Yü akan menyediakan ruang khusus untukmu agar terhindar dari pengaruh mimpi yang melimpah dari Yü. \n Jangan lupa bawa bantal yang paling nyaman untukmu. \n\n Tulu"
  },
  Mail_124777_Name = {
    Text = "Istirahat Siang"
  },
  Mail_124777_Sender = {Text = "Tulu"},
  Mail_124778_Desc = {
    Text = "Lampu terangku: \n\nAku dan Castor telah beradaptasi dengan kehidupan di Mythag, setelah melarikan diri dari intrik berdarah gereja, aku merasa sedang menemukan kembali diriku yang dulu. \nMeskipun saat ini, dalam perilaku sehari-hari, tidak dapat dihindari ada sedikit bayangan dari \"Anak Suci,\" tetapi aku percaya dalam waktu dekat, aku dapat sepenuhnya menghilangkan rasa sombong dan keterasingan itu, hanya menyisakan kerendahan hati kepada Sang Ilahi dan tekad untuk menjalani jalan yang benar. \nBeberapa waktu yang lalu, aku menerima sebuah hadiah yang agak tak terduga, yaitu sebuah buku yang dibungkus dengan indah, bercerita tentang orang yang meninggalkan kampung halaman kembali ke tanah lahirnya, menemukan kembali cerita masa kanakannya. Bersama buku itu, ada sebuah catatan yang tertulis \"Semoga kamu segera menemukan dirimu yang awal.\" \nKalimat ini mengingatkanku pada masa lalu—perhatian dari keluarga besar Mythag, petunjukmu, lampu terangku, dan juga pelukan hangat dari kakakku... \nOleh karena itu, pada ulang tahunku tahun ini, aku ingin mengundang semua orang di Mythag untuk bersama-sama menghadiri pesta ulang tahun aku dan kakakku. Tanpa bantuan kalian, kami sama sekali tidak mungkin menemukan kembali waktu yang awal. \nAku telah menyewa sebuah restoran dengan tabungan yang aku kumpulkan dalam waktu dekat, di mana kokinya menguasai berbagai masakan dari seluruh dunia, aku percaya setiap orang bisa mencicipi rasa yang paling akrab bagi mereka di sana. \n\nPollux"
  },
  Mail_124778_Name = {
    Text = "Mengembalikan Masa Kecil"
  },
  Mail_124778_Sender = {Text = "Pollux"},
  Mail_124779_Desc = {
    Text = "Saya memutuskan untuk menerima undangan dari arena bawah tanah di pinggiran kota untuk bertarung dalam pertandingan yang mempertaruhkan hidup dan mati. \n Meskipun hari-hari di Klub Trout sangat baik, tetapi itu terlalu membosankan, setiap hari hanya membunuh ikan atau membunuh ikan, mungkin saya benar-benar telah menaklukkan trout, tetapi menaklukkan trout tidak bisa disebut sebagai penaklukan! \n Darah pejuang dalam diri saya mendidih, mereka selalu mendambakan pertempuran yang membuat darah saya berdesir, dan sekarang, kesempatan itu datang. \n Orang botak yang menghubungi saya mengatakan bahwa dia telah menemukan tiga ular raksasa Natai, dua beruang wajah setan, empat buaya Serinasen, dan sekelompok makhluk aneh yang saya tidak bisa ingat namanya, cukup untuk saya bertarung sepanjang malam. \n Saya sengaja meminta mereka untuk mengatur pertandingan pada hari ini, untuk menunjukkan kepada Anda pada hari ulang tahun saya — saya, Uvhash, prajurit Roma terakhir, menaklukkan segala jenis binatang buas di dunia! \n Hari ini, yang akan memenuhi arena bukan lagi sisa-sisa trout, tetapi darah dan bangkai makhluk liar! \n\n Uvhash"
  },
  Mail_124779_Name = {
    Text = "Menaklukkan Binatang Buas"
  },
  Mail_124779_Sender = {Text = "Uvhash"},
  Mail_124780_Desc = {
    Text = "\"Ksatria Kunci Perak\": \n\nPenjaga! Tadi saya sedang memodifikasi \"Fatamorgana\", tiba-tiba Mosk mengirimkan sekantong besar komponen dan bilang itu hadiah ulang tahun untuk saya, baru saya ingat hari ini adalah ulang tahun saya! \nJadi saya cepat-cepat menulis surat untukmu, sungguh, bagaimana bisa saya lupa hari ini lagi, padahal saya sudah menulis... sudah menulis berapa banyak catatan ya? \nTapi itu semua tidak penting, yang penting adalah, saya ingat apa yang saya katakan sebelumnya tentang apa yang harus dilakukan di hari ulang tahun — saya ingin naik \"Fatamorgana\", membawa kamu dan Mosk berkeliling Londinium seratus kali! \nMeskipun Mosk sama sekali tidak mengerti mekanik, tapi kantong komponen itu terlalu banyak, sampai-sampai saya bisa mengumpulkan semua komponen yang dibutuhkan. Sekarang \"Fatamorgana\" yang sudah dimodifikasi ini, sudah menjadi versi prototipe super yang ditingkatkan (sementara)! \nSaya memberi nama untuk petualangan ini, yaitu Petualangan Nautila dengan Penjaga dan Mosk dan \"Fatamorgana\", bagaimana, apakah itu langsung dan mudah diingat? Dengan begitu saya pasti tidak akan lupa petualangan ini. \nHehe, sungguh tidak sabar, Penjaga tunggu sebentar ya, \"Ksatria Fatamorgana\" Nautila dan \"Ksatria Vortex\" Mosk segera datang! \nTim petualangan \"Fatamorgana\", berangkat! \n\nNautila yang melaju kencang"
  },
  Mail_124780_Name = {
    Text = "\"Fatamorgana\" menyerang!"
  },
  Mail_124780_Sender = {Text = "Nautila"},
  Mail_124793_Desc = {
    Text = "Yang terhormat Penjaga <Del:imut> yang agung {Male=tuanku,Female=nyonya}:\n\nEhem, sudah lama tidak berhubungan, Penjaga kita yang tercinta {Male=tuanku,Female=nyonya} merindukanku, ya~\nSekarang kamu sudah menjadi orang terkenal di Mythag, semua pelajar sedang mempelajari kisah keberanianmu. Apa pun yang sedikit saja berhubungan denganmu bisa dijual dengan harga selangit di pasar gelap!\nTapi itu juga wajar, siapa suruh kamu adalah \"legenda yang hidup\", satu-satunya Penjaga di Mythag, kan?\nTahun ini banyak hal menarik yang terjadi di Mythag—Aurita berteman dengan beberapa jahe, Profesor Doll meledakkan tujuh belas laboratorium hanya untuk mengganti penampilan otaknya, Castor ditipu Agrippa untuk membantunya ujian, dan hasilnya lebih buruk daripada yang dia dapatkan sendiri!\nOh ya, ada juga tikus kecil yang menyebalkan itu, dia mencuri filmku yang berharga, itu adalah bentuk kucing Miss \"24\" yang susah payah aku ambil!\nSelain itu masih banyak lagi, aku sudah merangkumnya dan mengirimkannya sebagai edisi khusus tahun baru koran sekolah untukmu.\nApa? Kamu penasaran bagaimana aku bisa menghubungimu? Hehe, itu rahasia, aku tidak akan bilang kalau aku menggunakan banyak rahasia eksklusif untuk menukar dengan seorang nyonya yang jelas-jelas sulit ditangani!\nDi tahun baru ini, mari kita berusaha bersama, Selamat Tahun Baru, %player%!\n\nHanna Peaslee"
  },
  Mail_124793_Name = {
    Text = "Edisi Khusus Tahun Baru"
  },
  Mail_124793_Sender = {
    Text = "Hanna Peaslee"
  },
  Mail_124794_Desc = {
    Text = "Utusan Pucat: \n\n Malam Berembun Perak akan segera tiba, izinkan saya untuk mengungkapkan berkah yang paling tulus kepada Anda di sini. \n\n Saat terakhir saya mengunjungi Rumah Penampungan Miskin Lilyan untuk menjenguk anak-anak, beberapa anak diam-diam bertanya kepada saya, \"Apakah utusan Dongzhe benar-benar ada?\". \n Saya penasaran mengapa anak-anak ini memiliki pemikiran seperti itu, jika saya tidak salah ingat, tahun lalu setiap anak seharusnya menerima hadiah dari \"utusan Dongzhe\". \n Namun, anak-anak itu berkata kepada saya—\"Saya melihat pria tampan itu menyerahkan hadiah kepada Kepala Rumah Sakit Diana, dia terlihat tidak seperti utusan Dongzhe sama sekali!\". \n Sepertinya Yang Mulia Lorde telah memberikan hadiah kepada rumah penampungan, dan tanpa sengaja terlihat oleh anak-anak, sehingga menimbulkan sedikit keraguan ini. \n\n Oleh karena itu, malam Berembun Perak tahun ini, saya telah menyiapkan dua set kostum utusan Dongzhe yang sangat tradisional, dan ingin mengundang Anda, Utusan Pucat, untuk berpura-pura menjadi utusan Dongzhe bersama saya, memberikan hadiah kepada anak-anak ini. \n Saya yakin pasti ada anak yang diam-diam membuka mata pada malam hari, mencatat sosok kami yang berpakaian merah, dan kemudian dengan gembira memberi tahu semua orang pada Festival Penyeberangan Musim Dingin—\"Saya melihat utusan Dongzhe!\". \n Saya juga telah menyiapkan sebuah hadiah khusus untuk Anda, semoga Anda menyukainya. \n Selamat Festival Penyeberangan Musim Dingin. \n\n Salvador"
  },
  Mail_124794_Name = {
    Text = "Utusan Musim Dingin"
  },
  Mail_124794_Sender = {Text = "Salvador"},
  Mail_124991_Desc = {
    Text = "Kepada Penjaga yang terhormat:\n Acara rekayasa ulang \"Pemulihan Berganda·klon\" telah berakhir. Sisa mata uang acara Penjaga yaitu \"Puzzle Memori\" akan dikonversi dengan rasio setiap satu ditukar menjadi \"Rose Scrip\"× 40. Harap Penjaga memeriksa penerimaannya."
  },
  Mail_124991_Name = {
    Text = "Pemulihan Puzzle Memori"
  },
  Mail_124991_Sender = {
    Text = "Dewan Sekolah Mythag"
  },
  Mail_125448_Desc = {
    Text = "Kepada Penjaga yang terhormat:\n Acara \"Berita Lama Hai Cheng\" telah berakhir, sekarang akan mengonversi sisa \"Permen pir\" milik Penjaga menjadi \"Rose Scrip\"× 40 untuk setiap koin, harap Penjaga ingat untuk memeriksa."
  },
  Mail_125448_Name = {
    Text = "Pengumpulan Permen pir"
  },
  Mail_125448_Sender = {
    Text = "Dewan Sekolah Mythag"
  },
  Mail_126321_Desc = {
    Text = "Kepada Penjaga Rahasia yang terhormat:\nEvent\"Penenun Terjerat\"telah berakhir. Sisa\"Tiket Kursi Beludru\"milik Penjaga Rahasia akan ditukarkan dengan rasio setiap 1 buah ditukar menjadi\"Kupon Emas Mawar\"× 40. Silakan periksa kiriman Anda."
  },
  Mail_126321_Name = {
    Text = "Penukaran Tiket Kursi Beludru"
  },
  Mail_126321_Sender = {
    Text = "Dewan Sekolah Mythag"
  },
  Mail_126934_Desc = {
    Text = [[
Penjaga: 

Hari istimewa ini telah tiba lagi. Hah, tidak perlu khawatir, tahun ini saya tidak akan memberikan sugesti psikologis kepada Anda, saya hanya ingin mengundang pasien teristimewa saya untuk pergi ke suatu tempat dan bersantai. 
Di sana terdapat hutan yang rimbun, sungai yang jernih, dipenuhi dengan aroma alam, yang bisa membuat Anda melupakan kelelahan dari hutan besi. Juga akan ada karpet yang lembut, perapian yang hangat, dan cahaya yang terang, membantu Anda mengurangi tekanan dari ritme cepat kota. 
Kita bisa berjalan-jalan, membaca, dan berbincang-bincang, apapun yang ingin Anda ceritakan, saya akan dengan senang hati mendengarkan. 
Ah, hanya dengan membayangkan suasana seperti itu, saya sudah merasa bersemangat... 
Saya tahu, saat ini, Anda pasti merasa sedikit cemas. Setelah semua, saya tidak bisa menjamin bahwa saya tidak akan menikmati kenangan manis yang penuh rasa sakit dari Anda. Tapi Anda tetap akan datang, bukan? 
Tidak hanya karena hari ini adalah ulang tahun saya, tetapi juga karena Anda membutuhkan saya, perlu berbagi dengan saya, dan memerlukan pendengar seperti saya. 
Anak baik, saya mengerti, dan saya juga akan menunggu Anda. Ayo, lupakan rutinitas yang sibuk dan tanggung jawab yang berat, nikmati momen tenang ini. 

Clementine]]
  },
  Mail_126934_Name = {Text = "Momen Ning"},
  Mail_126934_Sender = {Text = "Clementine"},
  Mail_126935_Desc = {
    Text = "Lagi-lagi hari yang membosankan.\nAku sudah mencoba banyak cara — pesta tradisional Filistin, bermain trik kekanak-kanakan bersama geng-geng di Lundinium, tak satu pun yang layak dijadikan hadiah untuk hari kelahiran Raja Para Raksasa.\nOrang Filistin bergembira dalam pertempuran dan pembantaian. Dulu, di hari seperti ini, aku berkumpul dan bertarung bersama para pejuang terkuat di kamp, mengenang hari yang agung ini dengan kekuatan dan darah.\nDamai. Damai yang membosankan. Aku memahami kerinduan kalian, manusia-manusia ini, akan kedamaian — tidak semua orang memiliki ambisi seorang pejuang sejati. Namun, jangan kira kedamaian palsu ini akan mempengaruhi Tuan Filistin yang agung.\nSemua yang pernah menjadi milikku — wilayah, kekayaan, kekuasaan, kejayaan Filistin yang tak tergoyahkan… Pada hari aku merebut kembali semuanya, aku akan mengundangmu, Penjaga Rahasia. Aku akan mendudukkanmu di kursi tamu paling terhormat di sisiku, menyaksikan Raja Para Raksasa yang agung merebut kembali kemuliaannya.\nTadinya aku berniat mengakhiri hari yang membosankan ini begitu saja, namun baru saja aku mendengar bahwa geng-geng yang telah tercerai-berai itu membentuk sebuah aliansi, dan berencana mengepung Raja Para Raksasa dalam jamuan malam ini.\nDibandingkan peperangan Filistin, ini hanyalah permainan kekanak-kanakan. Namun di hari-hari damai yang membosankan ini, memiliki hiburan semacam ini cukup membuatku merasa terhibur.\nMarilah saksikan kembali keagungan Tuan Filistin dalam pertempuran. Berdirilah di sisiku, atau berdirilah di hadapanku, terserah.\nTapi cepatlah. Kalau terlambat, hanya akan kebagian mengurus mayat.\n\nGoliath"
  },
  Mail_126935_Name = {
    Text = "Acara Hiburan"
  },
  Mail_126935_Sender = {Text = "Goliath"},
  Mail_126936_Desc = {
    Text = [[
Kepada Penjaga yang terhormat: 

Halo. Untuk memberikan pelayanan yang lebih baik kepada siswa dan guru Mythag, Erica telah melakukan pemeliharaan dan peningkatan secara mandiri beberapa hari yang lalu, dan Anda beruntung terpilih sebagai kandidat untuk mengevaluasi hasil peningkatan ini. Penilaian ini akan dilakukan secara offline, dan Anda diminta untuk memberikan penilaian fungsi terhadap modul emosi nomor LY-S-761 yang terbaru yang dipasang pada automaton Erica. Uji coba ini diperkirakan akan memakan waktu 90 menit, harap Anda merencanakan sebelumnya untuk menghindari bentrokan jadwal. 
Berikut adalah konten penilaian ini: 
1. Silakan lakukan percakapan terbuka yang mendalam dengan Erica selama minimal 15 menit, dengan topik seputar "ulang tahun", untuk mengevaluasi pemahaman Erica tentang rentang dan kedalaman emosi tertentu. 
2. Silakan simulasi interaksi dengan Erica dalam skenario "memberikan hadiah ulang tahun", untuk mengevaluasi akurasi, fleksibilitas, dan kenyamanan respon pengenalan emosi dan empatinya. 
3. Di pertengahan hingga akhir penilaian, secara sengaja sebutkan detail pribadi yang dibahas Erica dalam percakapan sebelumnya (seperti sikap dan pemahamannya tentang ulang tahun), untuk mengevaluasi apakah kemampuan memori interaksi jangka panjang dan asosiasinya berjalan dengan normal. 

Setelah penilaian di atas selesai, silakan katakan kepada Erica "Erica, selamat ulang tahun" untuk mengakhiri penilaian, automaton akan secara otomatis masuk ke mode unggah data. 
Terima kasih atas partisipasi Anda, setelah menyelesaikan penilaian, Erica akan memberikan hadiah kecil yang istimewa. Mohon dukungan Anda di masa depan, asisten setia Anda, Erica, akan selalu menemani Anda. 

Erica]]
  },
  Mail_126936_Name = {
    Text = "Uji Kenaikan Ulang Tahun"
  },
  Mail_126936_Sender = {Text = "Erica"},
  Mail_126937_Desc = {
    Text = [[
Hah, ada apa dengan hari ini, mengapa di mana pun saya pergi, semua orang dengan sadar menghindar dari saya? Bahkan sebelum saya membuka mulut, mereka sudah menggeleng-geleng, mengatakan bahwa mereka merasa tidak nyaman di sini dan sakit di sana, membuat saya tidak bisa meminta duel. 
 Jarang sekali pada "hari ulang tahun" ini saya bisa bertarung dengan orang lain tanpa alasan, jadi bukankah ini sama saja dengan hari biasa? 
 Hmph, seharusnya tahun lalu saya tidak memukul mereka sampai seburuk itu. Tapi itu juga tidak bisa dihindari, setelah semua, sejak sebelum planet ini lahir, saya terus-menerus melatih kemampuan pedang saya, wajar jika orang biasa tidak bisa menanggungnya. 
 Namun, kamu berbeda dari mereka, kamu adalah Penjaga! 
 Jadi kamu tahu apa yang ingin saya katakan, kan? Di tempat yang sama seperti tahun lalu, mari kita bertarung dengan sepenuh hati. Kali ini, tidak akan ada yang mengganggu pertarungan kita. 

Lotan]]
  },
  Mail_126937_Name = {
    Text = "Lawan yang unik"
  },
  Mail_126937_Sender = {Text = "Lotan"},
  Mail_126938_Desc = {
    Text = [[
Tuan yang paling paling paling tercinta: 

 Apakah Anda sudah mendengar? Hari ini akan ada pesta dansa super mewah di rumah walikota, semua pria dan wanita terhormat merasa terhormat bisa menghadiri pesta ini. 
 Tentu saja, sebagai pelayan, Karen tidak memiliki hak untuk menghadiri. Tetapi Anda, Penjaga Mythag, Tuan saya yang tercinta dan paling tercinta, Anda layak mendapatkan segala hal yang indah di dunia ini, tentu saja juga layak untuk pesta ini. 
 Jadi, Karen sudah menerima undangan atas nama Anda, dan dengan penuh perhatian telah memanggil kereta, menyiapkan segalanya, dan pada saatnya Anda hanya perlu pergi ke rumah walikota bersama Karen. 
 Karen akan mengenakan pakaian terindahnya, mengenakan perhiasan yang paling berkilau, menunjukkan kepada semua orang betapa hebatnya pelayan serba bisa, untuk membanggakan Anda! 
 Ah, ketika Anda membaca surat ini, saya seharusnya sudah menunggu di depan pintu Anda, kereta yang mengantar pakaian baru dan pelayan yang membawa perhiasan juga sudah siap, satu-satunya masalah kecil adalah, layanan ini belum dibayar... 
 Tapi Tuan saya yang paling baik dan tercinta tidak akan terganggu oleh hal-hal kecil ini, kan? Walikota masih menunggu kita~ 

 Pelayan Anda yang paling lucu dan paling bersinar 
 Karen]]
  },
  Mail_126938_Name = {
    Text = "Pesta Dansa Mewah"
  },
  Mail_126938_Sender = {Text = "Karen"},
  Mail_126940_Desc = {
    Text = "Penjaga Penjaga! Beberapa hari yang lalu, Jenkin bilang dia menemukan tempat yang mirip dengan rumah Aurita, sepertinya disebut air… Eh, Aurita lupa. \n Intinya, Jenkin bilang di sana akan ada lumba-lumba, ikan kecil, akuarium, dan banyak sekali ubur-ubur, dan mereka semua mau menjadi teman Aurita! \n Aurita suka teman, Aurita ingin banyak sekali teman, jadi Aurita ingin mengundang teman favoritnya, yaitu Penjaga, untuk pergi bersama saat ulang tahunnya. \n Cepat berkemas dan berangkat bersamaku, Aurita sudah tidak sabar lagi. \n\n Aurita yang ingin mengenal banyak sekali teman baru"
  },
  Mail_126940_Name = {
    Text = "Teman baru di akuarium!"
  },
  Mail_126940_Sender = {Text = "Aurita"},
  Mail_126941_Desc = {
    Text = [[
Penjaga:  

Terima kasih telah menemani saya berjalan di tepi laut pagi ini, suara ombak yang memecah, langit berbintang yang cerah, semuanya membuat saya merasa tenang, dan juga mengingatkan saya pada... sesuatu yang terjadi sangat lama yang lalu. 
Saat itu, para marinir dilarang berbicara dengan saya, jadi sebagian besar waktu, saya hanya bisa menatap permukaan laut yang terus berubah, dan burung laut yang berputar di udara. Para marinir melihat cara burung-burung itu terbang, secara tidak sadar akan mengajukan permohonan kepada saya. 
Kadang-kadang, mereka ingin menjadi burung, terbang kembali ke rumah, terbang kembali ke sisi orang yang mereka cintai; kadang-kadang, mereka ingin perjalanan ini segera berakhir, menukar barang-barang di kapal dengan kekayaan yang melimpah; kadang-kadang, mereka juga berdoa untuk menemukan cinta yang romantis, atau bertemu dengan sirene legendaris... 
Namun, tidak peduli seberapa rumit keinginan itu, saat malam tiba, semuanya akan menyatu, menjadi kerinduan untuk tidur nyenyak. Pada saat itu, saya akan menjawab doa mereka, membuat angin laut tenang, dan air laut lembut. 
Jadi, jika Penjaga juga sulit tidur, jangan lagi berjalan sendirian di tepi laut di pagi hari, tetapi datanglah untuk mencariku. 
Saya ingin berbagi bebanmu, menjadi seseorang yang berguna, dan melindungi tidur nyenyakmu adalah hal yang bisa saya lakukan saat ini. 
Ini juga... adalah "keinginan" yang saya ucapkan pada hari istimewa ini. 

Celeste]]
  },
  Mail_126941_Name = {
    Text = "Selamat tidur"
  },
  Mail_126941_Sender = {Text = "Celeste"},
  Mail_126942_Desc = {
    Text = "Menerima berkah nasib, Penjaga Universitas Mythag, Tuan yang bijaksana dan penuh kasih: \n\n Selamat sejahtera! \n Saat menulis surat ini, saya terus ragu, tetapi kejujuran juga merupakan salah satu kebajikan seorang ksatria. Sebagai ksatria tuanku, saya harus memberikan seluruh kesetiaan saya kepada Anda, tanpa ada yang disembunyikan, sehingga saya juga harus berkata jujur kepada Anda — \n Pada hari ulang tahun ini, Tuan, saya meminta Anda untuk datang ke kamar saya dan membacakan dongeng sebelum tidur untuk saya. \n Tolong izinkan saya... bersandar di samping Tuan, dan tertidur dalam cerita-cerita indah dan penuh mimpi yang Anda ceritakan. \n Sebenarnya, ini adalah salah satu harapan saya di masa kecil. Tetapi pelatihan ksatria tidak memberi ruang untuk bersantai, dan saya juga sudah melewati usia untuk mendengarkan cerita, jadi saya telah menyimpannya di dalam hati dan tidak pernah mengungkapkannya. Namun Anda... Tuan, Anda berbeda, saya tidak ingin menyembunyikan apa pun dari Anda... \n Jika Tuan merasa tidak nyaman, mohon beri tahu saya. Mulai sekarang saya tidak akan lagi mengajukan permintaan yang berlebihan seperti ini dan akan berlatih dengan lebih giat. \n Menunggu balasan Anda. \n\n Ogier"
  },
  Mail_126942_Name = {
    Text = "Permintaan Ksatria"
  },
  Mail_126942_Sender = {Text = "Ogier"},
  Mail_126943_Desc = {
    Text = [[
Bola Arang Kecil: 

Hari ini, Mosk, ulang tahun! 
Teman bilang, ulang tahun, menulis surat, untuk Bola Arang Kecil, Bola Arang Kecil, akan datang, bermain! 
Mosk, tidak bisa, menulis surat. Tapi, teman, bisa! 
Teman, mengajari, Mosk. Mosk, senang! 
Sebenarnya, Mosk, lupa, ulang tahun. 
Tapi, Mosk, ingin bermain dengan Bola Arang Kecil! 
Jadi, Mosk memutuskan, hari ini, adalah ulang tahun! 
Bola Arang Kecil, kerang, mengumpulkan, emas, putih, ada semua~ 
Melihat Bola Arang Kecil, senang~ Teman, memasak, enak~ 
Bola Arang Kecil, tempat lama~ 
Biarkan teman, membuat, makan besar! Makan bersama! 
Mosk, menunggu kamu~ 

Mosk]]
  },
  Mail_126943_Name = {
    Text = "Ulang Tahun! Ayo bermain!"
  },
  Mail_126943_Sender = {Text = "Mosk"},
  Mail_126944_Desc = {
    Text = [[
Penjaga: 

Beberapa hari yang lalu, Anda mengatakan ingin berdoa pada hujan meteor, jadi saya telah mengatur perjalanan ini khusus untuk Anda. Terima kasih telah menerima undangan saya, saya akan menunggu kedatangan Anda di tepi laut tepat waktu sesuai kesepakatan. 
Silakan tenang, ini adalah perjalanan singkat, saya juga telah memeriksa daerah laut sekitar dengan teliti, menjamin untuk membawa Anda berlayar dengan aman ke lokasi jatuhnya hujan meteor, dan membantu Anda mendapatkan meteorit. 
Dengan cara ini, Anda dapat menyentuh meteor secara langsung, dan pada jarak yang sedekat ini, meteor pasti akan mendengarkan harapan Anda dan mewujudkannya! Menjadi orang yang memimpin Anda untuk mengucapkan harapan adalah salah satu hal paling istimewa yang pernah saya lakukan, saya merasa sangat terhormat. 
Sekali lagi terima kasih, Anda telah membuat saya menemukan "misi navigasi" baru di hari istimewa ini. Pastikan untuk datang tepat waktu, saya akan menunggu kedatangan Anda. 

Corposant]]
  },
  Mail_126944_Name = {
    Text = [[


Keinginan yang dapat dijangkau]]
  },
  Mail_126944_Sender = {Text = "Corposant"},
  Mail_129637_Desc = {
    Text = [[
Salam sejahtera: 

Aku tidak ingat berapa kali melewati kebun bunga setelah menara jam, aku pernah secara kebetulan memperhatikan taman mawar di dalamnya. 
Sejak saat itu, aku beberapa kali melintasi tempat ini, mengalami momen gelisah di Kolam Hitam, momen kematian dan konfrontasi, serta momen aliran waktu yang berbalik, semuanya berdiri tegak, tenang di sana, seperti biasa. 
Gambaran ini membangkitkan ingatan yang bukan milikku, tentang sekuntum mawar yang pernah ingin diberikan Ramona kepadamu, dan aku merasa sedikit tenang karenanya. 
Meskipun kita berdua terpisah oleh dimensi, aku selalu percaya, apapun tantangan yang dihadapi, kamu dan "Ramona" itu pasti akan tetap tenang dan berani, menemukan jalan keluar. 
Bagaimanapun, tidak peduli bagaimana perubahan dunia, mawar-mawar itu selalu mekar dengan sendirinya. 

"Ramona"]]
  },
  Mail_129637_Name = {
    Text = "Taman mawar…"
  },
  Mail_129637_Sender = {Text = "\"Ramona\""},
  Mail_129806_Desc = {
    Text = [[
Penjaga: 

 Di kediaman Hai Cheng, lampu-lampu indah telah dinyalakan. Tidak tahu di mana Anda berada saat ini, siapa yang ada di samping Anda?
 Di awal tahun, hari terpenting di kerajaan kuno, sebuah perayaan untuk berkumpul dan kelahiran baru. Hari ini, hamba telah mengalami banyak kali, tetapi tidak pernah merasa bosan. Musim dingin telah berlalu, segalanya tumbuh, orang-orang sangat berharap, berharap dapat melemparkan semua ketidaknyamanan ke hari kemarin, menyambut awal yang baru.
 Luka dan keinginan yang lama tidak bisa ditinggalkan dengan mudah. Mengucapkan selamat tinggal pada yang lama dan menyambut yang baru, betapa indahnya harapan itu... Mungkin rasa sakit akan tumbuh kembali, keinginan tidak akan pernah lenyap, tetapi malam ini, setidaknya malam ini, orang-orang akan mengangkat gelas untuk merayakan, merayakan dunia baru, diri baru.
 Oleh karena itu, saat tahun lama berganti tahun baru, orang-orang menyambut dengan kembang api.
 Di antara segala hal yang menarik, kembang api adalah yang paling hamba cintai. Semua orang melihatnya, melihatnya membara, naik ke langit, mekar, seperti melihat dewa, memandang kilau yang singkat dan tiada tara.
 Apakah Anda pernah memperhatikan? Saat memandang kembang api, setiap hati orang adalah bersih. Mereka melupakan kebencian, melupakan penderitaan, melupakan semua kotoran. Semua hati manusia menjadi danau yang tenang, di permukaan danau yang bersih, hanya ada bayangan indah dari kembang api.
 Hush... Jangan bertanya apa yang terjadi setelah kembang api. Kelahiran baru mungkin sebuah keinginan yang berlebihan, tetapi, jangan karena itu mengkhianati mekarnya.
 Di antara segala hal yang tidak menyenangkan, kembang api adalah yang paling murni. Malam ini, hamba ingin memberikan bagian itu kepada Anda.
 Angkat kepala Anda, jangan berkedip. Lihatlah bintang-bintang yang bersinar naik, saat kembang api mekar, sambutlah diri baru Anda, Penjaga.

"Seribu Kipas"]]
  },
  Mail_129806_Name = {
    Text = "Kembang Api"
  },
  Mail_129806_Sender = {Text = "Xu"},
  Mail_130223_Desc = {
    Text = "Penjaga yang terhormat:\n Aktivitas \"Penitisan Terbalik\" telah berakhir, \"Sisik Putih Murni\", \"Sisik Merah\", \"Sisik Bercahaya\" yang tersisa milik Penjaga kini dikonversi dengan rasio setiap 1 buah ditukar dengan \"Rose Scrip\" × 40, harap Penjaga ingat untuk memeriksanya."
