  },
  Mail_131005_Desc = {
    Text = "Yth. Penjaga: \n Acara \"Panggilan Meruskus\" telah berakhir. Saat ini, sisa \"Kerang Laut Nomor Satu\", \"Kerang Laut Nomor Dua\", dan \"Kerang Laut Tiga\" milik Penjaga akan dikonversi dengan rasio setiap item menjadi \"Rose Scrip\"× 40. Harap Penjaga ingat untuk memeriksa."
