  Mail_131005_Name = {
    Text = "Pemulihan Kerang Laut"
  },
  Mail_131005_Sender = {
    Text = "Dewan Sekolah Mythag"
  },
  Mail_131093_Desc = {
    Text = "Kepada Penjaga yang terhormat: \n Acara \"Pesta Api·Replikasi\" telah berakhir. Saat ini, sisa \"Os Tibia asli\", \"Amónito Daun Bundar\", dan \"Reruntuhan Spiral\" milik Penjaga akan dikonversi dengan rasio setiap item menjadi \"Rose Scrip\"× 40. Harap Penjaga memeriksa penerimaannya."
  },
  Mail_131093_Name = {
    Text = "Pemulihan Mata Uang Pesta Api yang Berkobar"
  },
  Mail_131093_Sender = {
    Text = "Dewan Sekolah Mythag"
  },
  Mail_131767_Desc = {
    Text = "Aku @2! @3 adalah @2 yang Maha Tinggi @3, campuran @4 dan kehancuran @2! Teriaklah @4...!\n\n Aduh! Lihatlah apa yang telah kau lakukan!!! Kau telah menyentuh larangan Tuhan Yang Maha Tinggi! Sekarang, suaranya telah menggema di dunia tempatmu berada, bencana hitam akan mulai menyebar dari komunikasimu, menelan segalanya di sekitarmu...\n Kasihan sekali, kecerobohanmu benar-benar membuatku kesulitan. Tapi jangan terlalu putus asa, ada sedikit keberuntungan di tengah kesulitan, kau telah bertemu denganku—Peri Agung dari sekte, Orang yang Dipilih oleh Tuhan, Eksekutor Tuhan Yang Maha Tinggi, ahli waris sah dari sekte yang megah, Penyelamat dari penderitaan, dan Teman dekat Sang Raja! Aku adalah kehendak dari Tuhan yang penuh kasih dan kepedulian, tidak tahan melihat penderitaan di dunia ini, aku akan menggunakan kekuatanku yang Maha Tinggi untuk menyelamatkan setiap anak nakal yang bodoh.\n Oh, peri ini melihat tatapan ejekanmu. Tidak apa-apa, Tuhan yang baik mencintai umat manusia, tidak pernah peduli pada kebodohan mereka. Ketidakpercayaan terhadap Sang Penyelamat adalah jalan yang harus dilalui setiap percaya. Hadiah pertemuan ini adalah anugerah dari Eksekutor Tuhan untukmu.\n Sekarang, jalan terang telah ditunjukkan untukmu: Bawalah ketulusanmu, pergi ke katedral @2 yang terletak di kota @3, dan persembahkan kesetiaanmu kepada Tuhan yang baik, maka kau akan mendapatkan kekuatan yang kau impikan, terbebas dari kutukan mimpi buruk ini. Tentu saja, yang perlu diserahkan juga adalah kekayaanmu. Jangan salah paham, Tuhan yang baik tidak peduli pada imbalan duniawi, tetapi para pengikut-Nya juga perlu mengeluarkan uang untuk menjalankan tugas. Jangan pelit dengan barang-barang duniawi ini, percayaku, setiap sen ada harganya.\n Serukan nama Tuhan yang baik, dan tunggulah saat keajaiban Fajar datang!\n\n Peri Agung dari sekte, Orang yang Dipilih oleh Tuhan"
  },
  Mail_131767_Name = {
    Text = "Tolong jangan sentuh @2 ini"
  },
  Mail_131767_Sender = {Text = "Caraboo"},
  Mail_132339_Desc = {
    Text = "Kepada Penjaga yang terhormat: \n Aktivitas \"Pemulihan Raja Dewa·Replikasi\" telah berakhir. Sekarang, sisa \"Pikiran Lelah\", \"Pikiran sedih\", dan \"Pikiran Bahagia\" akan dikonversi dengan rasio setiap satu ditukar dengan \"Rose Scrip\" × 40. Harap Penjaga ingat untuk memeriksa."
