  },
  Mail_132339_Sender = {
    Text = "Dewan Sekolah Mythag"
  },
  Mail_132458_Desc = {
    Text = "Kepada Penjaga yang terhormat: \n        Terima kasih atas dukungan dan pengakuan Anda terhadap \"Lupakan Malam Sebelumnya\". Untuk memberikan pengalaman bermain yang lebih baik di Universitas Mythag, kami dengan hormat mengundang Anda untuk mengisi kuesioner pengalaman berikut. Sebagai ucapan terima kasih atas kerjasama Anda, kami telah menyiapkan \"Perak\" × 200 sebagai hadiah, yang dapat Anda ambil setelah menyelesaikan kuesioner. Batas waktu pengisian kuesioner adalah 17 Agustus pukul 09:00, harap diperhatikan untuk mengisi tepat waktu. \n        <SurveyLink:\"Klik di sini untuk mengisi\"> \n        Kami akan mendengarkan setiap saran dari Penjaga, dan umpan balik Anda pasti akan membuat Universitas Mythag semakin baik! \n        —Semoga Kunci Perak menuntun jalanmu."
