  Mail_132605_Desc = {
    Text = "Ciiit Ciiit Ciiit, Ciiit Ciiit Ciiit Ciiit Ciiit!\n(Penjaga, Selamat Hari April Mop!)\nCiiit Ciiit Ciiit, Ciiit!\n(Foto identitas, kenangan!)\n\"Jejak cakar musang laut yang berantakan dan lembap\"\n\"Sebagian besar cetakan cangkang buram yang ditinggalkan oleh kegagalan meneteskan lilin segel\"\n                                                         —sebuah jejak cakar musang laut yang sangat rapi"
