    Text = "Kepada Penjaga Rahasia yang terhormat:\nEvent\"Penaklukan Agung·Rerun\"telah berakhir. Sisa\"Daging Panggang Leo Lezat\"milik Penjaga Rahasia akan ditukarkan dengan rasio setiap 1 buah ditukar menjadi\"Kupon Emas Mawar\"× 40. Silakan periksa kiriman Anda."
