  },
  Mail_133703_Desc = {
    Text = "Keeper yang terhormat:\nVersi {s1} telah berakhir. Sisa \"Phantom Core\" milik Keeper telah otomatis dikonversi dengan rasio 1 \"Phantom Core\" ditukar menjadi \"Pristine Core\" × 1. Total konversi kali ini adalah \"Pristine Core\" × {s2}. Harap Keeper periksa dan terima."
