  },
  Mail_133704_Desc = {
    Text = "Keeper yang terhormat:\nVersi {s1} akan segera berakhir. Harap segera gunakan sisa \"Phantom Core\" yang dimiliki. Setelah Tugas Semester periode ini berakhir, sisa \"Phantom Core\" milik Keeper akan dikonversi dengan rasio 1 \"Phantom Core\" ditukar menjadi \"Pristine Core\" × 1."
