  },
  Mail_134024_Desc = {
    Text = "Kepada Penjaga Rahasia yang terhormat:\n\"Uji Coba Harian\"telah dihapus. Sisa\"Voucher Agen\"milik Penjaga Rahasia akan ditukarkan dengan rasio setiap 1 buah ditukar menjadi\"Kupon Emas Mawar\"× 10000. Silakan periksa kiriman Anda."
  },
  Mail_134024_Name = {
    Text = "Penukaran Voucher Agen"
  },
  Mail_134024_Sender = {
    Text = "Dewan Sekolah Mythag"
  },
  Mail_134067_Desc = {
    Text = "Penjaga Rahasia:\n\nHari ini ada hal spesial yang ingin kubicarakan denganmu.\nAku ingin jalan-jalan santai di jalanan, melihat berbagai hal menarik begitu saja, berkeliling sesuka hati, dan menjalani hari yang biasa.\n\nLalu, aku bertanya ke bagian administrasi. Ternyata mereka bilang, demi keamanan, aku hanya boleh keluar kampus jika ditemani olehmu.\nMereka juga bilang jangan menakuti orang lain, dan jangan memasukkan sembarang hal ke mulut saat di luar. Sungguh tidak sopan.\nYah, begitulah ceritanya. Jadi, bisa tidak kita pergi jalan-jalan? Bersama-sama ya.\n\n……Entah kenapa aku jadi teringat, benih dandelion itu,\nsuatu hari nanti akan terbang bersama angin, memulai perjalanan menuju tempat takdirnya,\nmungkin besok, mungkin jauh di masa depan.\nSemakin kupikir, semakin kurasa melakukan banyak hal bersama semua orang selagi masih bisa, sepertinya tidak buruk juga.\n\nPokoknya, aku menunggumu di depan asrama. Tolong ya!\n\nSaya"
  },
  Mail_134067_Name = {
    Text = "Jalan-jalan…"
  },
  Mail_134067_Sender = {Text = "Saya"},
  Mail_134068_Desc = {
    Text = "Penjaga Rahasia:\n\nKurasa, hari ini adalah hari yang istimewa. Tapi kontur ingatan itu, masih tetap begitu kabur.\nHanya nama\"Saya\"ini, yang dengan susah payah mengikatku di tempat ini.\n\nPerasaan itu bukan kesepian, bukan pula kesedihan, bukan emosi yang sejelas itu.\nJika harus memberi nama untuk perasaan ini… mungkin, itu adalah\"Kekosongan\".\nTidak ada apa-apa, kejernihan tanpa akhir, waktu yang sunyi.\n\nJika suatu hari, benih dandelion yang terbang tertiup angin,\ndi setiap sudut dunia ini, hanya jatuh dengan putih bersih, dengan tenang…\nSaat itulah, mungkin aku akhirnya bisa merasa, bahwa dunia ini adalah \"sesuatu yang istimewa\".\n\nSaat itu, kabut kelabu yang menyelimuti Londinium, awan senja merah membara saat matahari terbenam, dan langit yang selalu kamu tatap dari alun-alun sekolah, semuanya akan tertutupi dandelion, berubah menjadi warna putih murni. Menjadi warna milikku.\n\nJadi… jika, kamu bersedia memberiku sesuatu.\nItu tidak perlu hadiah, cukup sepenggal \"kenangan\" saja.\n\nAku, di dunia putih murni tempat dandelion bermekaran,\nhanya diam menunggu, menanti datangnya saat itu.\n\nKetika suatu hari kamu kembali mendongak menatap langit di alun-alun Mysterium,\ntolong tumpang-tindihkan sehelai bulu putih yang melintas di tepi pandanganmu,\ndengan bayangan diriku yang pernah berbicara denganmu, walau hanya sedikit.\n\nSaya"
  },
  Mail_134068_Name = {
    Text = "Janji Dandelion…"
  },
  Mail_134068_Sender = {Text = "Saya"},
  Mail_139809_Desc = {
    Text = "Penjaga Rahasia yang terhormat:\n        Terima kasih atas dukungan dan pengakuan Anda terhadap《Malam Sebelum Terlupakan》. Demi memberikan pengalaman bermain yang lebih baik bagi para Penjaga Rahasia di Universitas Misage, kami mengundang Anda untuk mengisi kuesioner survei pengalaman berikut. Sebagai ungkapan terima kasih atas kerja sama Anda, kami telah menyiapkan「Silver Core」× 200 sebagai hadiah, yang dapat diklaim setelah menyelesaikan kuesioner. Batas waktu pengisian kuesioner adalah 16 Mei pukul 09:00, harap segera mengisinya.\n        <SurveyLink:【Klik untuk Mengisi】>\n        Kami akan dengan serius mempertimbangkan setiap saran dari para Penjaga Rahasia, dan masukan Anda pasti akan membuat Universitas Misage semakin baik!\n        ——Semoga Kunci Perak menunjukkan jalan ke depan."
  },
