    Text = "Penjaga yang terhormat:\n\"Tahanan Cermin·klon\" Telah berakhir, kini Buku Kebijaksanaan Umum, Buku Matematika, dan Buku Sastra yang Tersisa milik Penjaga akan dikonversi dengan rasio setiap 1 buah ditukar Rose Scrip × 40, harap Penjaga ingat untuk memeriksanya."
