  },
  Mail_141507_Desc = {
    Text = [[
Penjaga Rahasia: 

Hari kelahiran, mungkin ini adalah hari yang penting bagimu? 
Bagi saya, setiap hari di Jaring Takdir memiliki berat yang sama. Cerita-cerita lain yang memberi makna khusus pada hari ini. 
Saya lahir pada hari ini, memahami ramalan pada hari ini, mendapatkan Roda Takdir yang Menyusun pada hari ini, melihat benang-benang takdir yang rumit, serta mimpi buruk di ujung benang tersebut. 
Bagi penjahit takdir, hari ini biasa-biasa saja. Bagi aktor di atas panggung, hari ini layak dirayakan. Namun di antara semua identitas, yang paling membuat saya bahagia adalah diri saya sebagai seorang aktor. 
Penjaga Rahasia, hari ini, lampu Teater Nasib telah padam, hanya satu panggung yang bersinar terang. Kamu pernah menyebutkan, ingin lebih banyak melihat takdir yang telah saya alami. Dan sekarang, panggung ini akan menyajikan sebuah cerita tentang diri saya. 
Saya tidak tahu bagian mana yang akan dipentaskan. Saya akan mengingat dan membawanya ke panggung, dia akan memilih bagian yang paling kamu tunggu untuk disajikan di panggung malam ini. 
Cerita itu mungkin menyakitkan bagi saya, mungkin memalukan, tetapi itu tidak penting, bukan? Saya rasa, sesekali membiarkan roda itu menenun sendiri, menjadi penonton yang murni, adalah hal yang menyenangkan. 
Satu-satunya tiket masuk untuk pertunjukan ini, kini ada di tanganmu. Datanglah dengan surat ini, Penjaga Rahasia. Malam ini, sebuah cerita yang tidak diketahui orang lain, menunggu kedatanganmu. 

Arachne]]
  },
  Mail_141507_Name = {
    Text = "Cerita yang Tersembunyi"
  },
  Mail_141507_Sender = {Text = "Arachne"},
