  Mail_141962_Desc = {
    Text = "Penjaga yang terhormat:\n        Terima kasih atas dukungan dan pengakuan Anda terhadap \"Morimens\". Demi memberikan pengalaman bermain yang lebih baik bagi Penjaga di Universitas mythag, kami mengundang Anda untuk mengisi kuesioner survei pengalaman berikut. Sebagai ucapan terima kasih atas kerja sama Anda, kami telah menyiapkan \"Perak\" × 200 sebagai hadiah, yang dapat diambil setelah menyelesaikan kuesioner. Batas waktu pengisian kuesioner adalah 10 Mei pukul 9:00, harap segera mengisinya.\n        <SurveyLink:[Klik untuk mengisi]>\n        Kami akan dengan serius mendengarkan saran dari setiap Penjaga, dan masukan Anda pasti akan membuat Universitas mythag semakin baik!\n        —Semoga Kunci Perak menuntun jalanmu."
