  Mail_142101_Desc = {
    Text = "Lama tidak berjumpa, %player%:\n\nSaat kamu menerima surat ini, aku seharusnya sedang melintas di atas langit Yagro. Setiap tahun di bulan ini, perjalanan perburuanku selalu membawaku lebih jauh dari biasanya.\nTidak ada yang lebih cocok dijadikan musik latar ulang tahun selain jeritan dan raung kesakitan musuh. Lagipula aku sudah menyiapkan cukup banyak sangkar — asalkan masih ada orang bodoh yang berani menyembah dewa-dewa palsu yang tidak membawa apa pun selain penderitaan, tanpa Penebusan apa pun, ke mana pun mereka pergi, aku akan membuat mereka menyadari kesalahan mereka.\nSesekali, ketika sang Malam menembus awan dan Bulan bisa terlihat, memang ada beberapa pikiran absurd yang sekilas melintas di benakku.\nSeperti kapan masa-masa ini akan tiba-tiba, tanpa bisa dilawan, dipaksa berhenti, seperti kehidupan yang dulu runtuh tanpa peringatan.\nNamun kemudian aku malah tertawa sendiri. Sejak hari aku melangkah masuk ke dalamnya, aku sudah berada di sebuah perjalanan tanpa jalan kembali. Aku yakin kamu pasti mengerti maksudku, anak kecil. Di dunia ini, tidak ada orang yang nasibnya lebih mirip denganmu dan aku.\nKita berdua memilih beberapa pilihan yang sebenarnya bukan pilihan, kabar baiknya adalah, kita berdua sangat menikmati pilihan kita.\nTahun baru ini, Hanya dengan meniup peluit berburu yang kuberikan padamu, aku tetap akan muncul di sisimu kapan saja.\nTentu saja, jika tidak ada hal tak terduga, biarkan aku dulu menikmati perjalanan ini dengan tenang. Bulan depan, aku akan membawakan oleh-oleh dan beberapa kabar berita baru untukmu.\nSemoga segalanya berjalan lancar untukmu, semoga kamu bahagia.\n\n\"Paman\"mu yang tersayang"
  },
  Mail_142101_Name = {
    Text = "Kabar Berita"
  },
  Mail_142101_Sender = {
    Text = "\"Paman\"mu yang tersayang"
  },
  Mail_143935_Desc = {
    Text = "Kepada Penjaga yang terhormat:\nAcara \"Teks Sementara\" telah berakhir. Saat ini, sisa \"Teks Sementara\", \"Teks Sementara\", dan \"Teks Sementara\" milik Penjaga akan dikonversi dengan rasio setiap item menjadi \"Rose Scrip\"× 40. Harap Penjaga ingat untuk memeriksa."
