  Mail_145468_Desc = {
    Text = "Penjaga yang terhormat:\n Aktivitas \"Jika segalanya berjalan seperti biasa·klon\" telah berakhir. \"Cangkang oleh-oleh pantai\" yang tersisa milik Penjaga kini akan dikonversi dengan rasio setiap 1 buah ditukar \"Rose Scrip\" × 40. Harap Penjaga ingat untuk memeriksanya."
