  Mail_147081_Desc = {
    Text = "Kalender adalah penemuan yang membosankan. Semua hari tidak ada bedanya, termasuk hari ini.\nMenurut kalender kalian, hari ini adalah hari kelahiranku. Kata kelahiran tidak terlalu tepat bagiku. Aku adalah serpihan yang tercabik dari Chaos, bilah yang ditempa dalam tak terhitung pertempuran. Yang membentukku bukan rahim, melainkan setiap lawan yang pernah berhadapan denganku. Dan kamu, adalah satu orang yang paling penting di antara mereka.\nKalian sangat mementingkan hari seperti ini. Pesta, hadiah, ucapan selamat — aku tidak membutuhkan semua itu.\nAku hanya butuh satu pertempuran.\nSelama ini, kamu telah melakukan banyak hal yang luar biasa. Namun aku tahu, apa yang telah kamu tunjukkan masih jauh dari batas kemampuanmu.\nSore ini, di lapangan latihan. Bawa senjatamu, aku akan menunggumu di sana. Tidak perlu memikirkan menang atau kalah, tidak perlu khawatir soal luka. Saat bilah pedang saling berbenturan tanpa sisa, itulah satu-satunya hadiah ulang tahun yang aku nantikan. Biarkan aku melihat, apa yang mampu dilakukan oleh serpihan @4.\nAku rasa, kamu akan membuatku terkejut, \"lawan\"-ku."
