  },
  Mail_148514_Desc = {
    Text = [[
Penjaga yang terhormat:
        Dalam pembaruan versi V1.4.3.5, kami menambahkan tingkat "Raja Baru" pada "Lanskap mimpi: Profanasi". Karena sebagian Penjaga tidak mengetahui pembaruan ini tepat waktu, mereka keliru mengira bahwa "Lanskap mimpi: Profanasi" telah sepenuhnya diselesaikan.
        Untuk itu, dalam pembaruan versi V2.6.2 ini, kami telah melengkapi progres penyelesaian tingkat "Raja Baru" bagi Penjaga yang telah menyelesaikan tahap tingkat-tingkat setelah "Raja Baru" sebelum pembaruan, dan secara bersamaan mengirimkan hadiah penyelesaian pertama yang sesuai. Harap segera periksa.]]
  },
  Mail_148514_Name = {
    Text = "Pelengkapan Progres \"Profanasi\""
  },
  Mail_148514_Sender = {
    Text = "Dewan Sekolah Mythag"
  },
  Mail_148515_Desc = {
    Text = "Penjaga yang terhormat:\n\nTa-da~ Apakah ini di luar dugaan? Ini adalah ulang tahun pertama peri ini di Mythag, jadi——\nSungguh! Tidak ada email promosi, undangan kebaktian, bahkan ramalan kiamat pun tidak ada~\nNamun jangan kecewa, peri ini tentu saja telah menyiapkan beberapa keuntungan yang lebih berharga dan lebih baik untuk umat yang paling istimewa.\nSebagai peri wali yang Mengetahui segalanya dan berkuasa penuh, tentu saja bisa memperkirakan keraguan dan kewaspadaan yang wajar itu, meskipun hal itu membuat peri ini merasa sedikit sedih dan kecewa, namun, demi menyebarkan berkah aliran ini, pengorbanan kecil selalu tidak bisa dihindari.\nJadi, cobalah berpikir seribu langkah ke belakang, dan coba saja, toh tidak ada ruginya, bagaimana kalau ternyata benar? Betul tidak?\nIni adalah kesempatan yang hanya ada setahun sekali, yang bagaimanapun tidak boleh dilewatkan~\nTidak perlu persembahan apapun, tidak perlu janji atau pertukaran apapun, hanya perlu menikmati afternoon tea yang manis bersama peri wali, dan Anda akan mengetahui betapa banyak perasaan tulus yang tersimpan di bawah salju dan es untuk Anda.\nBukankah ini sebuah tawaran yang menggoda?\nCatatan: Harap pastikan membawa setidaknya 10, 100, 1000 Léofang yang cukup untuk membayar tagihan, semakin banyak semakin baik.\n\nMenunggu Anda di toko yang kita semua tahu\nCaraboo"
  },
  Mail_148515_Name = {
    Text = "☆☆☆Email Keuntungan Super☆☆☆"
  },
  Mail_148515_Sender = {Text = "Caraboo"},
  Mail_149949_Desc = {
    Text = "Surat ini telah beredar seribu kali di antara dunia hidup dan mati, jangan dihapus!\n\nPertengahan bulan ketujuh, gerbang arwah terbuka, angin suram berhembus, roh gentayangan kembali.\nAku adalah ■■■ dari Kota Hu di Kerajaan Kuno Panlong, inilah selembar surat hina!\nMembawa titah Zhongyuan, memegang surat jimat pemanggil arwah, malam ini kutitipkan kutukan di sini. Siapa yang membaca surat ini, jiwanya akan tercatat, namanya telah terdaftar. Jika sebelum tengah malam tidak meneruskan kepada lima puluh orang di dunia fana, maka akan——\nDokumen hancur sesaat sebelum tersimpan...\nBoba susu pasti kurang tiga butir mutiara...\nBaterai komunikator Perak selamanya macet di 1%, diisi pun tak penuh...\n\nTuruti saja, kutukan akan luruh sendiri, jimat akan terbakar sendiri, hantu jahat tak akan mengganggu, lampu pun akan terus menyala.\nTeruskan!! Sekarang juga!!!"
  },
  Mail_149949_Name = {
    Text = "[Peringatan Zhongyuan] Siapa Berani Hapus Surat Ini, Akan Terkena..."
  },
  Mail_149949_Sender = {Text = "Yizhi Ye"},
  Mail_149985_Desc = {
    Text = "Tuan:\n\nMaaf atas surat yang tiba-tiba ini, semoga tidak membuat Anda merasa canggung. Namun ada beberapa hal yang hanya bisa kuungkapkan kepada Anda.\nSemalam, setelah sekian lama, aku bermimpi. Dalam mimpi itu, aku kembali ke rumah lama. Segalanya terasa begitu akrab — telapak tangan ayah yang lembut dan hangat, nyanyian lagu pedesaan yang dinyanyikan pelayan saat Bersihkan rumah, dan kuda poni putih milikku itu... Kukira semuanya telah lama tenggelam dalam lumpur kenangan, namun melihatnya kembali dalam mimpi, rasanya tetap sehangat dulu.\nSetelah terbangun, aku melihat para guru dan murid Mythag sedang mengobrol santai melintas di luar jendela, begitu tenang dan indah, hingga sejenak aku merasa pemandangan itu tak berbeda dengan yang ada dalam mimpiku. Selain itu, aku juga menyadari bahwa sesuatu yang tak kasat mata yang selalu melekat padaku, sejak pagi ini terasa sangat tenang. Apakah benar bahwa di hari ulang tahun seseorang akan menemui sedikit keberuntungan?\nJika memang demikian, mungkin hari ini aku boleh sedikit serakah...\nAku tahu orang-orang biasanya suka membuat permohonan di hari ulang tahun mereka, sebagai harapan untuk setahun ke depan. Aku sudah lama tidak berani berharap mendapat ucapan selamat ulang tahun dari siapa pun, namun ada satu kesempatan yang sungguh ingin kudapatkan.\nSebagaimana Tuan mempercayakan kepercayaan kepada ku, aku pun tidak akan Retain apa pun dari Anda. Karena itu, izinkanlah aku menyampaikan permohonanku kepada Anda:\nJika lain kali Tuan memiliki tugas yang perlu diatur, tolong tunjuklah aku sebagai Penjaga dan biarkan aku menemani Anda.\nApa pun yang terjadi, aku berharap di saat Anda paling membutuhkan bantuan, aku selalu bisa menjadi yang pertama berdiri di hadapan Anda, menjadi Perisai Anda yang paling kokoh.\nItulah permohonan yang kupanjatkan untuk tahun ini.\n\nOgier"
  },
  Mail_149985_Name = {
    Text = "Harapan Ulang Tahun..."
  },
  Mail_149985_Sender = {
    Text = "Sumpah Palsu·Ogier"
  },
  Mail_18019_Desc = {
    Text = [[
