  Mail_20231_Sender = {
    Text = "Dewan Sekolah Mythag"
  },
  Mail_21453_Desc = {
    Text = [[
Kepada Penjaga yang terhormat:

Minta maaf mengganggu, bagaimana kabar Anda belakangan ini?
Maaf telah mengganggu waktu Anda yang sibuk, Jenkin dan yang lainnya telah menyiapkan sebuah pesta ulang tahun kecil untuk saya, saya sudah mempertimbangkan cukup lama, akhirnya memutuskan untuk mengirim undangan ini langsung kepada Anda.
Kebanyakan anak yatim piatu yang ditampung di bengkel tidak bisa mengingat tanggal lahir mereka, Nona Sarah menetapkan hari kami tiba di panti asuhan sebagai tanggal ulang tahun kami. Hanya saya yang berbeda, Nona Sarah mengatakan saya ditinggalkan di depan pintu panti jompo pada malam musim dingin yang sangat dingin, dia ingin hidup saya tidak lagi dingin dan pucat, jadi dia memilih hari yang hangat sebagai tanggal ulang tahun saya. Jadi, ini adalah hari saya, hari di mana saya merasa diperhatikan dan dicintai. Ini adalah hari yang penting bagi saya, saya berharap Penjaga juga bisa merayakannya bersama saya, ini adalah satu Harapan Kecil saya. Tentu saja, jika tidak bisa dipenuhi, tidak masalah, karena Penjaga memiliki banyak hal untuk diurus, seperti yang diketahui Aigis.
Jika undangan ini menambah masalah bagi Anda, harap beri tahu saya, dan terimalah permohonan maaf saya yang tulus. Tetapi jika, seandainya Anda benar-benar bisa meluangkan waktu, Anda sangat, sangat dipersilakan untuk bergabung dengan mereka dalam kekacauan, mungkin, mungkin saja akan sangat menyenangkan, karena ini adalah persiapan Jenkin.

Aigis]]
  },
  Mail_21453_Name = {
    Text = "Di tengah kesibukan..."
  },
  Mail_21453_Sender = {Text = "Aigis"},
  Mail_21454_Desc = {
    Text = [[
Hai: 
Aku selalu tidak mengerti, apa yang begitu istimewa dari hari kelahiran sehingga layak dirayakan? Sampai-sampai semua orang membuatnya jadi sesuatu yang besar?
Pada hari ini tahun lalu, seorang murid bertanya kepadaku tentang tanggal ulang tahunku. Aku tertawa terbahak-bahak. Ketika aku dilahirkan, konsep waktu belum ada di Planet ini, apalagi ulang tahun. Tapi dia terus memaksa sampai aku tak punya pilihan selain memberitahunya "saat pergantian siang dan malam berada dalam keseimbangan". Entah bagaimana dia akhirnya memahaminya.
Surat ini kutulis untuk mengingatkanmu, setelah tengah malam nanti jangan lupa untuk mengambil bunga-bunga di depan pintu kamarku. Bau mereka benar-benar tidak tertahankan!

Lotan]]
  },
  Mail_21454_Name = {
    Text = "Bunga-bunga itu…"
  },
  Mail_21454_Sender = {Text = "Lotan"},
  Mail_21455_Desc = {
    Text = [[
Erica hari ini mengirimkan sekantong besar kopi, katanya itu adalah hadiah ulang tahun saya, dan dia juga bilang di dalamnya adalah ransum untukmu selama setahun ini.<Del: Tetapi apakah kamu melakukannya secara sukarela? Jika tidak>
Jika ini adalah lelucon dari Tulu atau siapa pun, meskipun sangat sayang, saya masih bisa mengembalikannya... lagipula itu kopi! Jika saya tidak meminum dua cangkir, saya akan sangat mengantuk, tidak meminum sepanjang tahun? Kamu pasti akan tidur seperti Tulu. Bukan berarti dia buruk, cuma, yang hitam itu muncul di malam hari... Singkatnya, jika kamu membutuhkannya, kapan saja kamu bisa mengambil kopi kembali, tentu saja jika kamu meninggalkan kopi di sini, <Del: saya juga akan> saya pikir saya akan sangat senang. Dengan cara itu, saya akhirnya bisa melakukan eksperimen yang ingin saya lakukan: mengekstrak kafein dan mengonsentrasikannya menjadi obat yang bisa diserap melalui kulit, melekat padaku dan tetap terjaga selamanya...


Saya sangat ingin melakukan eksperimen ini, Kerang]]
  },
  Mail_21455_Name = {Text = "Kopi……"},
  Mail_21455_Sender = {Text = "Winkle"},
  Mail_21456_Desc = {
    Text = "Ulang tahun? \nJika harus berkata, ulang tahunku bukanlah hari yang baik. Ratusan, bahkan ribuan nyawa tak berdosa mati pada hari itu hanya untuk membuatku \"dilahirkan\", lalu membunuh lebih banyak orang. \nJadi, tidak ada yang perlu dirayakan pada hari itu. Tapi aku mengerti bahwa kalian manusia sangat memperhatikan \"ritual\". Kebetulan aku punya sejumlah uang — tenang, ini hasil kerja keras dari keringatku di Trout Club, bukan pendapatan ilegal. \nAmbil uang ini dan belikan dirimu hadiah, anggap saja sebagai perayaan ulang tahunku. \n\nUvhash"
  },
  Mail_21456_Name = {
    Text = "Ulang tahun..."
  },
  Mail_21456_Sender = {Text = "Uvhash"},
  Mail_21457_Desc = {
    Text = [[
Penjaga: 

Apakah ada kebiasaan merayakan ulang tahun di wilayah Mythag?
Negara asalku yang kuingat... setiap tahun selalu mengadakan upacara besar untuk merayakan kelahiran Raja.
Lambat laun, makna istimewa "ulang tahun" diberikan kepada semua orang.
Di masa lalu yang jauh, setiap hari ulang tahun, rekan-rekan dan teman-teman dekat akan datang dari jauh untuk berada di sisiku.
Perasaan dikelilingi oleh orang-orang tercinta... kehangatan seperti dipeluk matahari... mungkin itulah alasan aku tak bisa melepaskan masa lalu.
Ah... aku melantur terlalu jauh, apakah aku mengganggu pekerjaanmu?
Aku telah menyiapkan beberapa camilan dan teh yang biasa kugunakan di masa lalu, ingin berbagi denganmu.
Jika kamu bersedia, silakan datang menemuiku setelah makan malam.

Faros]]
  },
  Mail_21457_Name = {
    Text = "Cahaya yang tak pernah padam…"
  },
  Mail_21457_Sender = {Text = "Faros"},
  Mail_21458_Desc = {
    Text = "Hari ini jelas merupakan hari yang bersejarah: hari di mana Sang Raja Goliath, penguasa raksasa muncul ke dunia; hari di mana lautan bergetar, bintang-bintang memudar.\nKatakan saja bahwa di kampus tidak diizinkan boros, jadi adakan saja pesta ulang tahunku dengan sepuluh bagian dari standar biasa—sepuluh ekor babi panggang, seratus tusuk gurita panggang dan band yang bisa memainkan lagu rakyat Goliath, oh ya, sebaiknya juga sediakan satu dos penari…\nApa? Semua itu tidak diizinkan?\nJika demikian, cukup penari saja… tidak perlu satu dos, empat atau lima sudah cukup.\nApa? Ini juga tidak diizinkan?!\nSpesifikasi yang begitu sederhana tidak layak untuk posisiku. Sekarang aku umumkan, rencana pesta dibatalkan!\n\nGoliath"
  },
  Mail_21458_Name = {
    Text = "Rencana jamuan malam..."
  },
  Mail_21458_Sender = {Text = "Goliath"},
  Mail_21459_Desc = {
    Text = "Penjaga—\n\nHari ini saat melakukan pelatihan ingatan di tempat Nona Silvya, dia menanyakan tentang hari ulang tahunku. Kamu juga tahu, aku baru saja meletakkan kunci inggris dan bisa langsung melupakan itu, bagaimana mungkin aku bisa mengingat hari ulang tahun! Yang lebih parah, ini adalah sesuatu yang hanya aku tahu, aku! Jadi hari ulang tahunku sepertinya tidak ada. \n\nNamun, Pastor Salvatore bilang tanggal spesifik itu tidak penting, yang penting adalah apa yang aku rayakan setiap hari, jadi aku memutuskan, hari ini adalah hari ulang tahunku! Aku sudah berjanji dengan seseorang (aku lupa siapa, seharusnya bukan kamu kan, Penjaga?) untuk mengadakan pesta di depan kantin, kamu pasti harus datang ya! \n\n\n\nAku pasti akan mengingat tanggal ulang tahun ini, Notila \n\n\n\nSebuah catatan yang dikirim bersama surat: \n\nAnak itu selesai menulis surat dan pergi dengan cepat, meninggalkan surat dan beberapa hadiah yang katanya untukmu di atas meja. \nAku sudah melampirkan barang-barang itu di dalam amplop, berharap bisa bertemu denganmu di pesta malam ini. Tenang saja, aku akan mengingatkannya untuk hadir malam ini. \n\n—Silvya"
  },
  Mail_21459_Name = {
    Text = "Ulang tahun yang aku putuskan!"
  },
  Mail_21459_Sender = {Text = "Nautila"},
  Mail_21460_Desc = {
    Text = [[
Nak:

Di Lautan Originium tidak ada bintang, matahari, bulan, maupun pergantian empat musim. Oleh karena itu, tanggal lahirku seharusnya tercatat sebagai[Tidak Diketahui].
Tapi hari ini memang hari yang penting, bagaimanapun juga, wujud ini diwarisi dari seorang manusia yang memiliki[Harapan]. Dia suka keramaian, makanya dia membuka toko kecil ini, tapi karena sering bepergian untuk investigasi, ulang tahunnya sering kali hanya ditemani olehku seorang. Demi mewujudkan keinginannya semasa hidup, Toko Pereda Kekhawatiran hari ini akan mengadakan makan malam lilin, dengan hormat mengundang semua pelanggan setia untuk hadir.
Tentu saja, Toko Pereda Kekhawatiran juga akan memberikan diskon kecil untuk semua pengunjung. Jangan sampai terlewat ya, Nak.

Daphdail]]
  },
  Mail_21460_Name = {
    Text = "Keinginan manusia…"
  },
  Mail_21460_Sender = {Text = "Daffodil"},
  Mail_21461_Desc = {
    Text = "Ketika saya dibawa dari keluarga saya, ibu angkat saya… Istri sang konsul memecahkan kepingan tanah liat yang bertuliskan tanggal lahir saya menjadi serpihan, menghancurkan masa lalu saya sebagai seorang Delos. Ulang tahun yang sebenarnya, tentu saja, sudah tidak bisa diketahui lagi. \nSetelah berpisah dengan Rai, saya juga merenungkannya... Bagaimana jika malam saya melarikan diri dari penjara dan memulai balas dendam dianggap sebagai \"hari ulang tahunku\"? Apa pendapatmu? \nMeskipun sekarang tidak ada lagi kebutuhan untuk merayakan pertambahan usia, namun sebagai pengingat pergantian waktu, sepertinya ide ini tidak buruk."
  },
  Mail_21461_Name = {
    Text = "Hari kelahiran"
  },
  Mail_21461_Sender = {Text = "Helot"},
  Mail_21462_Desc = {
    Text = [[
Tes, tes. 
Yang Terhormat Penjaga, halo. Jika Anda menerima surat ini, itu berarti pendapat Anda sangat penting bagi Erica dan Anda telah dipilih untuk berpartisipasi dalam rencana evaluasi dan pemeliharaan tahunan modul bahasa dari boneka otomatis Erica. Evaluasi ini akan dilakukan dalam bentuk pertanyaan esai dan membutuhkan Anda untuk memberikan penilaian terhadap fungsi modul bahasa nomor EA-L-1033 yang baru saja dipasang pada boneka otomatis Erica. Ini tidak akan memakan banyak waktu Anda, jadi harap jangan merasa tegang atau panik. 
Pertanyaan Esai: 
Apakah Anda memahami maksud utama dari surat ini? 

Silakan tulis balasan langsung di bawah pertanyaan esai pada bagian kosong yang tersedia, dan masukkan kembali surat ini ke dalam amplop. 
Terima kasih atas partisipasi Anda. 

Erica]]
  },
  Mail_21462_Name = {
    Text = "Tes, tes…"
  },
  Mail_21462_Sender = {Text = "Erica"},
  Mail_21463_Desc = {
    Text = "Penjaga: \n\nKamu adalah salah satu dari sedikit orang yang tetap waras di sekolah ini. Pandanganmu mampu menembus tubuh yang cacat ini dan melihat diriku yang sebenarnya. \nSeseorang sepertimu pasti bisa menjelaskan kepada anak-anak itu: Aku bukan putri duyung. Tubuh ini akan melintasi lautan dan gunung-gunung untuk mencapai kesempurnaan. \n… Ah, sudahlah. Tidak ingin menyulitkanmu. Tapi setidaknya hari ini, jangan biarkan mereka bermain dengan ekorku. \nHari ini adalah hari yang istimewa. Jika kamu punya waktu, ada beberapa hal yang ingin kusampaikan langsung padamu. \n\nCaecus"
  },
  Mail_21463_Name = {
    Text = "Tubuh yang sempurna…"
  },
  Mail_21463_Sender = {Text = "Caecus"},
  Mail_21464_Desc = {
    Text = "Penjaga: \n\nHari ulang tahunku dalam arti duniawi adalah hari ketika ayahku mengadopsiku. \nDulu, dia selalu memberikan perhatian ekstra pada hari itu, setiap tahun mengadakan pesta dansa besar — menari dengan korset jauh lebih melelahkan daripada melambaikan pedang sebanyak tiga ribu kali. \nNamun, ini adalah bentuk kasih sayangnya sebagai seorang ayah, dan aku tidak ingin mengecewakan cinta yang begitu berharga. \nTapi tahun ini, dia akhirnya mengizinkanku untuk mengatur sendiri kegiatan ulang tahunku. Mungkin di mata ayah, aku sudah bukan anak kecil yang harus diawasi setiap saat. \nNgomong-ngomong, bisakah kamu menemaniku ke puncak menara lonceng? Mari ngobrol dan menikmati angin malam. \nAku mendengar bahwa malam ini akan ada bulan purnama. \n\nRamona"
  },
  Mail_21464_Name = {
    Text = "Bulan purnama…"
  },
  Mail_21464_Sender = {Text = "Ramona"},
  Mail_21465_Desc = {
    Text = "Tuan yang tercinta, tuan paling tercinta:\nYa, benar! Hari ini adalah ulang tahun Karen yang ke-1 (usia seorang wanita harus dirahasiakan)!\nKaren telah mempersiapkan pesta yang luar biasa meriah untuk ini dan mengundang semua teman kecil yang bisa diundang~ Meskipun pada akhirnya hanya Aurita, Ogier, dan Lily yang setuju untuk datang…\nTapi tidak apa-apa, di mana ada orang, di situ ada pesta, dan di mana ada pesta, di situ ada Karen! Karen bahkan sudah menyiapkan masakan \"versi diperbaiki\" sup kodok, siput lumpur bawang putih, dan sup kelelawar kari. Tuan harus mencobanya ya~\n\nNgomong-ngomong, tuan pasti sudah menyiapkan Hadiah untuk Karen kan? Pastikan itu berkilauan ya!\n\nPelayanmu yang selalu rendah hati,\nKaren"
  },
  Mail_21465_Name = {Text = "Hadiah…"},
  Mail_21465_Sender = {Text = "Karen"},
  Mail_21466_Desc = {
    Text = [[
Hai <Del:Penjaga Rahasia> si Warga Distrik Barat:
Ini adalah surat <Del:undagan und undangan und undangan> pokoknya ini surat untuk mengajakmu makan kue gratis, sekalian merayakan ulang tahunku! Sebenarnya juga untuk berterima kasih karena kamu sudah membantuku menemukan kakakku, dan membawaku ke sini, memberikan tempat yang aman untuk aku dan Brown.
(Yang di atas itu disuruh tulis oleh Aigis, gombal banget. Persahabatan kita nggak perlu hal-hal kayak gitu, kan, Penjaga Rahasia?)
Pokoknya, malam ini di halaman belakang asramamu, aku, Brown, dan Aigis sudah menyiapkan beberapa hal keren dengan tangan kami sendiri, menunggumu untuk berbagi bersama! Tentu saja sebenarnya yang masak kebanyakan Aigis, masakannya enak banget, ibu-ibu di dapur juga memuji bakatnya. Kalau kamu nggak datang, dijamin kamu bakal menyesal.

Teman lamamu, Jenkin dan Brown]]
  },
  Mail_21466_Name = {
    Text = "Yang Terhormat Penduduk Barat Liar..."
  },
  Mail_21466_Sender = {Text = "Jenkin"},
  Mail_21467_Desc = {
    Text = "Penjaga:\n\nKetika manusia masih tinggal di kerajaan para Dewa, kita sudah mulai mengekspresikan perasaan kita melalui tarian — putaran pesta, langkah berkabung...\nAda yang mengatakan sejarah tarian sama panjangnya dengan sejarah umat manusia, yang menyaksikan keagungan dan juga kemunduran kita.\n\nSaya pernah berkata saya tidak akan menari lagi, tetapi... saya dilahirkan untuk menari. Jadi, hanya hari ini, maukah Anda menari bersama saya? Tenggelam bersama saya dan rasakan ritme terdalam tubuh Anda.\n\nSaya akan menunggu Anda di studio tari.\n\n\n\nLiz"
  },
  Mail_21467_Name = {
    Text = "Undangan untuk berdansa bersama"
  },
  Mail_21467_Sender = {Text = "Liz"},
  Mail_21468_Desc = {
    Text = [[
Kepada Penjaga yang Terhormat:

Sebelum saya menjadi Pembangun, saya merayakan ulang tahun dengan rekan-rekan di barak, dengan membawa minuman dari luar dan merayakan diam-diam di tenda tempat persediaan barang, lalu melempar botol ke rerumputan luar sebelum ditemukan oleh perwira.

Tetapi Mythag bukanlah tempat militer, di sini, kita dapat sepenuhnya memanjakan diri. Entah Anda ingin berbagi sebotol anggur dengan saya, bersama merayakan ulang tahun saya?
Jika Anda bersedia, datanglah ke atap asrama malam ini ketika bulan melewati menara jam. Apakah Anda pernah memperhatikan, di sanalah pemandangan terbaik di seluruh Mythag.



Alva]]
  },
  Mail_21468_Name = {
    Text = "Berbagi minuman anggur yang baik..."
  },
  Mail_21468_Sender = {Text = "Alva"},
  Mail_21469_Desc = {
    Text = "Pantai pantai pantai pantai!\nEh? Surat harus dimulai dengan nama penerima — sangat merepotkan! Bukankah Penjaga tidak pernah menulis nama penerima di catatan di kulkas!\nHari ini adalah ulang tahun Aurita yang... eh... berapa tahun ya? Pokoknya ini ulang tahun Aurita!\nIni adalah harta karun Aurita! Semua untukmu! Bawa Aurita ke pantai, tolong tolong tolong ya!\nAnggap saja, anggap saja ini sebagai hadiah ulang tahun untuk Aurita, oke ya~\n\nAurita"
  },
  Mail_21469_Name = {Text = "Pantai!"},
  Mail_21469_Sender = {Text = "Aurita"},
  Mail_21470_Desc = {
    Text = "Orang Terhormat: \n\nDulu, ketika saya dan kakak berada di planet tandus, kami selalu berpelukan, menyerap energi dari tanaman yang sama sebagai peringatan kelahiran kami. \nMeskipun hari-hari itu pahit, sekarang saat mengingatnya, saya merasa senang dan hangat. \nHari ini adalah hari peringatan kelahiran kami lagi, jika memungkinkan, bisakah saya melakukan pertukaran sebuah lagu dengan sepotong cabang? \nSebuah cabang manis yang bisa mewakili masa lalu saya dan kakak, serta masa depan saya dan Anda… \n\nTinct"
  },
  Mail_21470_Name = {
    Text = "Lagu ulang tahun"
  },
  Mail_21470_Sender = {Text = "Tinct"},
  Mail_21471_Desc = {
    Text = [[
Atas anugerah takdir, Penjaga Universitas Mythag, Tuan yang bijaksana dan berbudi luhur: 
Selamat sejahtera! 
Beberapa hari lalu, saya melihat ada truk masuk ke kandang di sekolah, ternyata mereka membawa seekor kuda berdarah hangat. Saya teringat ketika terakhir kali melakukan tugas penyelidikan bersama Anda, Anda pernah mengatakan bahwa Anda belum pernah menunggang kuda sebelumnya. Kuda muda berdarah hangat sangatlah jinak, paling cocok untuk pemula beradaptasi dengan punggung kuda.
Menunggang kuda, mengejar fajar dan senja, itu adalah salah satu momen paling nyaman dalam memori saya. Jika Tuan berkenan, saya ingin mengajak Anda berkuda bersama, dan berbagi kenyamanan ini dengan Anda.

Ogier]]
  },
  Mail_21471_Name = {
    Text = "Kuda berdarah panas…"
  },
  Mail_21471_Sender = {Text = "Ogier"},
  Mail_21472_Desc = {
    Text = [[
Kalender negeri lama sangat berbeda dari yang digunakan di Londinium saat ini.
Aku lahir pada hari Bintang Penuh kelima di bulan Musim Panas kedua. Perayaan hari ini dipilih berdasarkan perhitungan kepala laboratorium.
Saat negeri lama masih berdiri, Pendeta Agung yang mengurus segalanya. Setelah upacara besar, seluruh negeri bersuka cita dan memasuki masa libur selama tujuh hari.
Meskipun bukan permintaanku, aku juga tidak punya alasan untuk menghalangi penyebaran kegembiraan.
Hari ini bukan hari libur Mysterium, dan tugas Penjaga Rahasia juga memastikan kamu tidak akan memiliki hari istirahat yang teratur.
Namun, jika mengajukan cuti dengan alasan merayakan ulang tahunku, kurasa bagian administrasi pun tak akan berani berkomentar.
Nikmatilah sore yang santai.

Tulu]]
  },
  Mail_21472_Name = {
    Text = "Ulang tahun…"
  },
  Mail_21472_Sender = {Text = "Tulu"},
  Mail_21473_Desc = {
    Text = "Penjaga: \n\nAurita berkata, setiap orang yang berulang tahun harus membuat permohonan. \nDan kebetulan saya adalah seseorang yang tak pernah membuat permohonan. \nKarena apa yang saya pikirkan selalu terwujud. Ini bukan keberuntungan, melainkan lebih seperti semacam... petunjuk takdir? \nSeperti bulan lalu saat saya pergi berlayar bersama Celeste, saya \"kebetulan\" menemukan fosil yang indah. \nPenduduk setempat menyebutnya \"lilia laut\". Tangkainya seperti kincir angin menghadap arus, sedang malas-malasan menikmati matahari di sore hari musim panas. \nRapuh, namun indah. Saat melihatnya, wajahmu secara alami muncul di benak saya. \nKali ini saya tetap tidak membuat permohonan— \nKamu pasti akan menyukainya, kan? \n\nSanga"
  },
  Mail_21473_Name = {
    Text = "Lili laut..."
  },
  Mail_21473_Sender = {Text = "Sanga"},
  Mail_21475_Desc = {
    Text = [[
Penjaga: 

Dulu, saat berlayar bersama Elton, dia akan menyiapkan satu meja penuh hidangan setiap tahun pada hari ini dan meminta saya untuk "membuat permohonan". 
Sebelum datang ke sini, saya tidak mengerti apa itu "permohonan". Sekarang, saya tidak tahu apa yang bisa saya "mohonkan"... 
Mungkin, menemukan "permohonan", juga bisa menjadi sebuah "permohonan"? 

Celeste]]
  },
  Mail_21475_Name = {
    Text = "Keinginan…"
  },
  Mail_21475_Sender = {Text = "Celeste"},
  Mail_21476_Desc = {
    Text = [[
Penjaga: 

Aurita memberitahuku bahwa kau akan mengabulkan semua keinginan yang diucapkan saat ulang tahun, benarkah?
Seharusnya tidak mungkin benar, kan? Mengabulkan keinginan semua orang terlalu merepotkan untukmu.
Tapi, jika aku bisa berharap... aku ingin Tinct memiliki panggung yang lebih luas.
Apakah itu terlalu sulit untuk diwujudkan? Hmm... kalau begitu, bagaimana dengan, "Selama setahun ke depan, meja makanku tidak akan ada seledri lagi," bisakah?

Pingsan]]
  },
  Mail_21476_Name = {
    Text = "Keinginan…"
  },
  Mail_21476_Sender = {Text = "Faint"},
  Mail_21477_Desc = {
    Text = [[
Dear Penjaga:

Izinkan aku berbagi sebuah rahasia: ulang tahun ini sebenarnya adalah palsu. Adapun tanggal lahirku yang sebenarnya... biarlah itu menghilang bersama angin.
Setelah sakit, Kakak selalu meminta pelayan diam-diam menyiapkan kue kecil untukku di hari ulang tahun.
Tidak ada lagu ulang tahun, tidak ada ucapan selamat, seolah-olah merayakan ulang tahun adalah sesuatu yang memalukan.
Sekarang, semuanya telah berubah. Aku bisa berjalan di bawah sinar matahari, bernyanyi dengan lantang, dan merayakan ulang tahun.
Ini hanyalah kebahagiaan kecil, namun membuatku merasa rindu.
Terima kasih, Penjaga.

(Tentu saja, jika Anda dan semua orang bisa sedikit lebih kasar padaku... akan lebih sempurna.)

Leigh]]
  },
  Mail_21477_Name = {
    Text = "Sebuah rahasia…"
  },
  Mail_21477_Sender = {Text = "Leigh"},
  Mail_21478_Desc = {
    Text = "Tahanan kecil·ku: \n\nSudah lama·lama·lama sekali aku tidak mengayunkan cambukku——\nTerjebak di sekolah yang membosankan ini, terjebak dalam seragam sekolah, hati Pandia merasa gatal, seperti ada anak kucing nakal yang mencakar-cakar. Bukan hanya tidak ada yang memahamiku, para staf bahkan berusaha keras untuk menghentikanku dari \"bersenang-senang\"——ini benar-benar keterlaluan! \nAh, hari ini adalah hari yang spesial, sangat cocok untuk membuat cambukku menyentuh kulit yang lembut lagi, dan mendengar nyanyian rasa sakit…… Jika kau punya waktu hari ini, bagaimana kalau datang untuk mengobrol denganku~? \n\nPandia"
  },
  Mail_21478_Name = {
    Text = "Suara cemeti…"
  },
  Mail_21478_Sender = {Text = "Pandia"},
  Mail_21479_Desc = {
    Text = "<Big:Pertunjukan Peringatan Tahunan Sang Master Sihir Casiah, Hanya Hari Ini!>\n\nSebagai ungkapan terima kasih kepada para penonton atas dukungan dan dorongan selama bertahun-tahun, untuk membalas semua kebahagiaan yang diberikan oleh kalian di masa lalu, Sang Master Sihir Casiah memutuskan untuk mengadakan pertunjukan peringatan tahunan spesial pada pukul 8 malam hari ini, di halaman tengah Universitas Mythag (di samping Patung Phillips)! Malam ini, kamu akan menyaksikan panggung yang lebih megah daripada sebelumnya, pertunjukan yang lebih mendebarkan, dan — yang paling penting — sihir yang begitu menakjubkan hingga kamu tak akan percaya pada mata sendiri! Bahkan otak dari Mythag yang hadir pun akan terpesona oleh sihir yang melampaui imajinasi, ini adalah jaminan dari Master Casiah!\n\nKesempatan langka ini hanya tersedia malam ini, dan sepenuhnya gratis! Master Casiah menantikan kehadiranmu tanpa absen!\n\n<Small:PS: Jika muncul gejala seperti kelelahan rohani atau suasana hati rendah selama atau setelah pertunjukan, Master Casiah tidak bertanggung jawab.>\n<Small:PPS: Semua promosi terkait otak Mythag tunduk pada situasi aktual saat acara berlangsung, Master Casiah berhak atas interpretasi penuh atas program dan efek program tersebut.>"
  },
  Mail_21479_Name = {
    Text = "Pertunjukan peringatan tahunan Master Sihir Casiah!"
  },
  Mail_21479_Sender = {Text = "Casiah"},
  Mail_21480_Desc = {
    Text = "Hei, hari ini adalah ulang tahunku, di mana hadiahnya?\nApa, kau lupa untuk menyiapkannya...? Hmph, aku sudah menduganya. \nNih, ambil kalender ini, di sana dengan jelas tertulis ulang tahunku, hari kematiaku, hari pertama aku datang ke Mythag, dan juga tanggal-tanggal festival seperti Festival Hiburan, Festival Dewa Pertanian… kita harus merayakan semua itu bersama-sama, jadi lain kali jangan lupa!\n\nJika kau lupa lagi... sepertinya aku juga tidak bisa berbuat apa-apa padamu, hmph. \nPokoknya jangan sampai lupa.\n\nAgrippa"
  },
  Mail_21480_Name = {Text = "Hei……"},
  Mail_21480_Sender = {Text = "Agrippa"},
  Mail_21481_Desc = {
    Text = [[
Penjaga: 

Aku sebenarnya tidak ingin menulis surat ini, tetapi sepertinya ada masalah dengan operasi Erica. Alarmnya terus berbunyi sebelum aku selesai menulis surat ini. 
Bagiku, ulang tahun hanyalah tanggal yang tidak bermakna. Tingkat keberhasilan eksperimen tidak akan lebih tinggi pada hari ini dibandingkan hari lainnya, dan Indeks gnostik-ku juga tidak akan berubah karena tanggal ini. Namun, Ramona bersikeras untuk menjadikan hari ini sebagai hari "istirahat"-ku dan membatasi akses masukku ke laboratorium hari ini. 
Aku tidak punya tempat untuk pergi, jadi hari ini aku akan melakukan tinjauan menyeluruh terhadap laporan-laporan lamamu. 
Datanglah ke ruang arsip setelah makan malam. Perhatikan, jangan coba-coba membawa kue apa pun ke dalam ruang arsip, karena arsip kertas sangat rapuh. 

Boneka]]
  },
  Mail_21481_Name = {
    Text = "Setelah makan malam…"
  },
  Mail_21481_Sender = {Text = "Doll"},
  Mail_22435_Desc = {
    Text = [[
Kepada Penjaga yang tercinta: 
Awalnya, saya memilih untuk membaca puisi di kampus saat fajar karena menurut saya pada jam ini lebih sedikit orang yang lewat, sehingga lebih mudah untuk tenggelam dalam dunia puisi. Kemudian, saya juga perlahan jatuh cinta pada langit yang mulai terang di pagi hari, embun yang bening, dan kicauan burung yang renyah dan merdu. 
Yang tidak saya duga adalah ternyata banyak guru dan siswa diam-diam memperhatikan saya, dan secara pribadi membentuk kelompok pecinta puisi. Hari ini adalah ulang tahun saya, dan kebetulan bunga narcissus di kelompok itu sedang mekar. Menggunakan kesempatan ini, mereka berencana mengadakan sesi apresiasi puisi, untuk bersama-sama menikmati pemandangan kampus sambil membaca puisi. 
Dalam suasana seperti ini, saya berharap Anda dapat datang untuk ikut menikmatinya. 

Nymphaea]]
  },
  Mail_22435_Name = {
    Text = "Undangan Membaca Puisi"
  },
  Mail_22435_Sender = {Text = "Nymphaea"},
  Mail_23897_Desc = {
    Text = [[
Yth. Penjaga: 
        Dalam pembaruan V1.0.21, kami telah menyesuaikan hadiah pertama kali menyelesaikan setiap level dari "Operasi"tingkat Keras, level pertempuran "Yang berkelana"tingkat Normal dan Keras, serta Retakan I-IV di setiap Alam di "Alam gelap". Detail penyesuaian dapat dilihat di "Pengumuman Pemeliharaan Online V1.0.21". 
        Berdasarkan catatan Penyelidikan dan tantangan sebelumnya Anda, kami akan memberikan secara sekaligus hadiah yang belum Anda terima sesuai dengan penyesuaian baru. Silakan lihat lampiran untuk detailnya.]]
