  Mail_24280_Desc = {
    Text = [[
Halo, Penjaga: 
Dalam peringkat Penyelidikan Terjunan gaib kemarin, kamu telah mendapatkan peringkat ke-{s2} di "{s1}", dengan gelar Penyelidikan "{s3}". Berikut adalah hadiah peringkat, harap Penjaga segera memeriksanya.]]
  },
  Mail_24280_Name = {
    Text = "Hadiah Peringkat Harian Terjunan Gaib"
  },
  Mail_24280_Sender = {
    Text = "Dewan Sekolah Mythag"
  },
  Mail_24877_Desc = {
    Text = "Penjaga: \n\nSetiap ulang tahunku selalu menjadi salon terbesar, penuh dengan tamu terhormat yang bersenang-senang.\nNamun kali ini, aku memiliki pemikiran lain — \nSudah terlalu lama aku duduk di kursi tuan rumah, sesekali aku ingin merasakan bagaimana menjadi seorang tamu.\nApakah akan ada salon yang elegan lagi, atau mungkin sekadar makan malam sederhana, semuanya terserah padamu. Bagaimana?\nNamun, jika kamu memilih untuk mengadakan salon lagi, jangan undang para bangsawan dan orang-orang terkenal itu.\nIni hari yang istimewa, aku tidak ingin tersenyum palsu.\n\n<Del:Nyonya Merah> Sorel"
  },
  Mail_24877_Name = {
    Text = "Terserah kamu…"
  },
  Mail_24877_Sender = {Text = "Sorel"},
  Mail_24878_Desc = {
    Text = [[
Tuan:

Hari ini ulang tahun Lily. Agrippa bilang harus"berpesta besar".
Dulu Mama dan Lily merayakan ulang tahun tidak seperti itu. Mama memakaikan topi kerucut padaku, lalu kita bertepuk tangan dan meniup lilin bersama.
Lily tidak tahu, bagaimana yang benar. Tolong Tuan beri perintah.

Lily]]
  },
  Mail_24878_Name = {
    Text = "Gangguan…"
  },
  Mail_24878_Sender = {Text = "Lily"},
  Mail_25147_Desc = {
    Text = [[
Kepada Penjaga yang terhormat: 
        Dalam pembaruan V1.1.0, hadiah poin mingguan dari "Terjunan gaib" telah ditiadakan dan digantikan dengan "Ujian Mingguan" baru. Berdasarkan prinsip keadilan, kami memberikan kompensasi berupa hadiah poin mingguan yang belum diambil kepada Penjaga yang sebelumnya telah membuka "Terjunan gaib" tetapi belum mengklaim semua hadiah poin mingguan ini dan telah masuk ke dalam permainan sebelum 15 Januari pukul 5:00. Silakan periksa.]]
  },
  Mail_25147_Name = {
    Text = "V1.1.0 Kompensasi Hadiah Poin Minggu Ini untuk Terjunan Gaib"
  },
  Mail_25147_Sender = {
    Text = "Mythag Bureau of School Affairs"
  },
  Mail_25148_Desc = {
    Text = "Kepada Penjaga yang terhormat: \n        Dalam pembaruan V1.1.0, \"Hadiah Mingguan\" dari Traphase (beta) telah dihapus dan digantikan dengan \"Uji Coba Mingguan\", yang memiliki kemajuan dan hadiah yang sama dengan \"Uji Coba Mingguan\" dari Terjunan gaib. Berdasarkan prinsip keadilan, kami akan memberikan kompensasi D-permata ×1000 kepada penjaga yang sebelumnya telah membuka \"Traphase (beta)\", tetapi belum menyelesaikan atau menerima \"Hadiah Mingguan\" minggu ini, dan yang masuk ke dalam permainan sebelum 15 Januari pukul 5:00 (UTC+8). Harap periksa."
  },
  Mail_25148_Name = {
    Text = "Kompensasi Hadiah Mingguan Versi 1.1.0 Traphase"
  },
  Mail_25148_Sender = {
    Text = "Mythag Bureau of School Affairs"
  },
  Mail_25414_Desc = {
    Text = [[
Yang Terhormat Penjaga: 

Beratnya hari kelahiran, bagi setiap orang tidaklah sama. Namun, ulang tahun Penjaga sangatlah penting bagi seluruh Mythag. 
Nyonya Sylvia telah menyiapkan pesta makan malam ulang tahun untukmu di area asrama, Dekan Czort dan Mulia Dexter akan hadir. Mengetahui bahwa kelelahan rohmu belum pulih, aku sudah menyiapkan pakaian formal untukmu, tergantung di lemari dekat pintu, bisa langsung kamu pakai sebelum acara dimulai. 
Merupakan kehormatan bagiku tahun ini bisa menjadi pasanganmu dalam merayakannya, semoga tahun depan kita masih bisa seperti ini. 
Semoga kunci perak membimbing jalan kita. 

P.S. Kue kecil pesanan khusus sudah dikirim oleh Erica ke asramamu. 

Selalu ingin menjadi pasanganmu, Ramona]]
  },
  Mail_25414_Name = {
    Text = "Hari kelahiran…"
  },
  Mail_25414_Sender = {Text = "Ramona"},
  Mail_34667_Desc = {
    Text = [[
Yang terhormat @1@2:

Dunia telah melupakan namamu.
Maka aku membangunkanmu, sebagaimana kamu membangunkanku. Sebelum Kedatangan akhir tiba, kamu dan aku berjalan di dunia, Menyaksikan, lalu mengingat dan melupakan.
Hari ini adalah hari kelahiranmu, sebuah halaman yang kebetulan ditemukan di antara Pecahan Memori yang terserak. Untuk itu, layaklah dipersembahkan keluh kesah dan Blessing.
Ketika dunia mengingat kembali wujudmu yang utuh, apa yang akan kamu rasakan? Atau mungkin masih tidak tahu apa-apa, tidak merasakan apa-apa?
Aku menunggumu di Negri Tak Berada untuk Jawabanmu.

@2]]
  },
