  Mail_39548_Desc = {
    Text = "Kepada Penjaga yang tercinta: \n\nBagi kehidupan abadi, memperingati hari kelahiran tampaknya tidak diperlukan. Dibandingkan dengan aliran waktu yang tak terbatas, apa yang kalian manusia sebut sebagai kenangan tak terlupakan atau luar biasa terlihat agak... remeh. \nNamun, kalian menciptakan begitu banyak hari raya dan perayaan untuk mengenang hal-hal \"remeh\" ini — tentu saja, ini adalah salah satu alasan mengapa kalian menarik minatku. Kalian memang cukup menarik. \nNamun, pertemuan denganmu jelas tidak dapat dihitung dalam momen-momen \"remeh\" ini, karena kau berbeda dari yang lain... dan aku sangat penasaran, badai seperti apa yang akan ditimbulkan oleh perbedaan ini di masa depan. \nBaiklah, maafkan omonganku yang berlebihan... Karena hari ini adalah hari ulang tahunku, aku ingin menggunakan hak istimewa sebagai \"orang yang berulang tahun\". \nAdapun apa yang harus kau lakukan, shh... jangan terburu-buru, jawabannya ada di kamarku, datang sendiri pada tengah malam nanti. \n\nWanda"
  },
  Mail_39548_Name = {
    Text = "Hak si ulang tahun..."
  },
  Mail_39548_Sender = {Text = "Wanda"},
  Mail_39549_Desc = {
    Text = "Hari ini adalah ulang tahun Tuan Murphy — hari ulang tahun harus dirayakan dengan pesta dan perayaan! \nOrang-orang dari Departemen Logistik sudah melakukan pekerjaan yang cukup baik, tetapi mereka tidak terlalu pandai berakting dan masih berusaha menyembunyikan sesuatu — aku sudah melihat mereka membawa hiasan kue ke gudang sistem Bangun. Hmm... kau seharusnya tidak menghukum para pegawai itu, kan? Mereka sebenarnya sudah bekerja dengan sangat baik, hanya saja mereka tidak bisa menyembunyikan kejutan dengan baik... \nSampai di sini dulu tulisanku, sepertinya ada orang yang mencariku untuk keluar — semoga mereka tidak menempelkan kertas warna-warni bodoh ke tubuhku. \nNgomong-ngomong, kau akan hadir saat memotong kue, kan? \n\nMurphy"
  },
  Mail_39549_Name = {
    Text = "Pesta ulang tahun…"
  },
  Mail_39549_Sender = {Text = "Murphy"},
