  Mail_44836_Desc = {
    Text = "Kepada Penjaga yang terhormat:\n        Dalam pembaruan V1.3.0, kami telah menambah hadiah untuk 1 kemenangan dan 3 kemenangan dalam \"Terjunan gaib\" setiap minggu: \"Kredensial Agen\"×1. Untuk Penjaga yang telah menerima hadiah di atas sebelum pembaruan, kami akan mengirimkan kembali jumlah \"Kredensial Agen\" yang sesuai. Silakan periksa."
