  },
  Mail_44837_Desc = {
    Text = "Utusan Pucat yang terhormat: \n\nHari ini beberapa anak membawa buket bunga dan kue, membuatku baru ingat bahwa lebih dari seratus tahun sebelum Kalender Hongji, pada hari ini aku diberkati oleh ayah surgawi untuk menerima hidup dan datang ke dunia. Betapa lama waktu telah berlalu, memori masa kecil sudah kabur, namun aroma dupa di dalam Gereja Hondosa masih mengendap di pikiranku, tak bisa hilang. Meskipun gereja itu masih ada hingga sekarang, resep dupa pasti sudah berbeda dari dulu.\n\nMaafkan aku, melankolis bukanlah tujuan suratku ini. Aku telah menyiapkan teh dan camilan dengan kue yang dibawa anak-anak, dan aku harap kamu bisa datang untuk berbagi denganku — bukan untuk merayakan ulang tahunku, melainkan untuk merayakan setiap hari keberadaan hidup, setiap hari keberadaan harapan.\n\nKapan hari ulang tahunmu? Pastikan untuk memberitahuku setelah secangkir teh.\n\n\n\nSalvador"
  },
  Mail_44837_Name = {
    Text = "Utusan Pucat…"
  },
  Mail_44837_Sender = {Text = "Salvador"},
  Mail_44843_Desc = {
    Text = "Keeper yang terhormat:\n        Dalam pembaruan V1.3.0, kami telah menghapus hak istimewa \"Tugas Inti\": EXP Keeper berlipat ganda di \"Deep Dive\" dan \"Phase Chess (beta)\". Sebagai permohonan maaf, kami akan memberikan kompensasi berupa \"EXP Keeper\" × 240 per hari kepada Keeper yang telah membeli \"Tugas Inti\" periode ini, berlaku hingga Tugas Semester periode ini berakhir. Silakan periksa dan terima."
  },
