  Mail_48005_Desc = {
    Text = [[
Kepada Penjaga yang tercinta: 

Maaf mengganggu, semoga tulisan tangan saya yang buruk tidak merusak suasana hati Anda. Saya memang tidak terlalu pandai menulis... 
Saya menulis surat ini untuk memberi tahu Anda bahwa sepertinya ulang tahun saya sudah tiba. Untuk itu, saya telah membuat beberapa kue kecil, dan saya harap Anda juga mau mencobanya. 
Sejujurnya, saya tidak yakin apakah tanggal ini benar. Setelah terinfeksi oleh Pelarutan, jejak-jejak keberadaan saya perlahan mulai menghilang. Nona Boneka pernah bertanya kepada saya, bagaimana rasanya menyaksikan diri sendiri dilupakan oleh semua orang dalam keadaan sadar? 
Ini sulit dijelaskan... seperti berdiri dalam kegelapan total, di tepi sungai yang bercahaya, sementara semua orang di sisi lain sungai saling berbicara dan sibuk dengan urusan masing-masing, berlalu begitu saja di depan saya. Saya hanya bisa melihat mereka tanpa bisa mengeluarkan suara sedikit pun. 
Ini adalah perasaan yang sangat kesepian. Untungnya, Anda tidak termasuk dalam kelompok itu. 
Setidaknya Anda masih mengingat cerita saya, bukan? 

P.S., dua belas kue kecil telah dikirimkan bersama surat ini. 

Mason]]
  },
  Mail_48005_Name = {
    Text = "Maaf mengganggu..."
  },
  Mail_48005_Sender = {Text = "\"24\""},
