  Mail_48914_Desc = {
    Text = "Kepada Penjaga yang terhormat: \n        Terima kasih atas dukungan dan pengakuan Anda terhadap 《LupakanMalam Sebelumnya》. Untuk memberikan pengalaman bermain yang lebih baik di Universitas Mythag, kami mengundang Anda untuk mengisi kuesioner pengalaman berikut. Sebagai ucapan terima kasih atas kerjasama Anda, kami telah menyiapkan \"Perak\"× 200 sebagai hadiah, yang dapat Anda ambil setelah menyelesaikan kuesioner. Batas waktu pengisian kuesioner adalah 28 Oktober pukul 9:00, harap perhatikan untuk mengisi tepat waktu. \n        <SurveyLink:[Klik di sini untuk mengisi]>\n        Kami akan mendengarkan dengan serius setiap saran dari Penjaga, dan umpan balik Anda tentu akan membuat Universitas Mythag semakin baik! \n        ——Semoga Kunci Perak menuntun jalanmu."
  },
  Mail_48914_Name = {
    Text = "Kuesioner Pengalaman Versi V1.6.3"
  },
  Mail_48914_Sender = {
    Text = "Mythag Bureau of School Affairs"
  },
  Mail_48915_Desc = {
    Text = "Kepada Penjaga yang terhormat: \n        Terima kasih atas dukungan dan pengakuan Anda terhadap 《LupakanMalam Sebelumnya》. Untuk memberikan pengalaman bermain yang lebih baik bagi Penjaga di Universitas Mythag, kami dengan hormat mengundang Anda untuk mengisi kuesioner pengalaman berikut. Sebagai ucapan terima kasih atas kerjasama Anda, kami telah menyiapkan \"Perak\"× 200 sebagai hadiah, yang dapat Anda ambil setelah menyelesaikan kuesioner. Batas waktu pengisian kuesioner adalah 30 September pukul 09:00, harap perhatikan untuk mengisi tepat waktu. \n        <SurveyLink:[Klik di sini untuk mengisi]>\n        Kami akan dengan serius mendengarkan saran dari setiap Penjaga, umpan balik Anda pasti akan membuat Universitas Mythag semakin baik! \n        ——Semoga Kunci Perak menuntun jalanmu."
  },
