  Mail_49931_Desc = {
    Text = "Kepada Penjaga yang terhormat: \n Acara \"Gelombang Laut Nafsu\" telah berakhir, sekarang sisa \"Benih ibu\" milik Penjaga akan dikonversi dengan rasio setiap biji menjadi \"Rose Scrip\"× 20. Harap Penjaga ingat untuk memeriksa."
