    Text = "Dewan Sekolah Mythag"
  },
  Mail_50344_Desc = {
    Text = "Tunas kecilku:\n\nAngin membawa aroma dirimu, tercium lebih manis dari saat pertama kali kita bertemu.\nKamu tumbuh besar dalam cintaku, dipelihara dan dimatangkan oleh kasih sayangku… seperti lebah dan madunya.\nHari ini adalah hari yang istimewa, bisakah kamu datang menemuiku?\nAku sudah menurut seperti yang kamu minta, menunggu dengan manis untuk waktu yang lama… sudah saatnya memberiku hadiah, kan?\n\nTaiyis"
  },
  Mail_50344_Name = {
    Text = "Manis seperti madu…"
  },
  Mail_50344_Sender = {Text = "Thais"},
  Mail_51376_Desc = {
    Text = "Kepada Penjaga yang terhormat:\n Acara \"Magis cerita\" telah berakhir, dan sekarang sisa \"Inspirasi yang Melayang\" milik Penjaga akan dikonversi dengan rasio setiap keping menjadi \"Rose Scrip\" × 60. Harap Penjaga ingat untuk memeriksanya."
