  },
  Mail_53149_Desc = {
    Text = [[
Sudah sejak lama aku memutuskan untuk mengabdikan sisa hariku setiap hari kepada satu orang itu... sebagai penebusan atas perbuatan bodohku. 
"Ulang tahun"dari tubuh yang dangkal ini tidak berarti apa-apa, tak layak disebut. 
Hari ini sama seperti hari lainnya di masa lalu atau masa depan, aku akan tetap pergi ke kapel seperti biasa. 
Namun, jika Anda ingin aku meninggalkan kapel hari ini sebagai tamu Mythag, tentu saja aku tidak akan menentang kehendak tuan rumah. 
Jika Anda ingin menyaksikan doaku, Anda selalu disambut untuk datang... dengan hormat dan rendah hati, aku sangat menyambut Anda. 

Miryam]]
  },
  Mail_53149_Name = {
    Text = "Berlatih sehari..."
  },
  Mail_53149_Sender = {Text = "Miryam"},
