  Mail_54803_Desc = {
    Text = "Kepada Penjaga yang terhormat:\n        Dalam pembaruan V1.5.1, kami telah meningkatkan hadiah \"Perak\" untuk tingkat Penjaga 21-80 dari \"Catatan Pertumbuhan\", dan menambahkan hadiah \"Lencana penyelidikan\" × 1000 untuk menyelesaikan tugas pada tahap \"Realm Mastery\" I~V. Untuk Penjaga yang telah menerima hadiah di atas sebelum pembaruan, kami akan mengirimkan kembali hadiah \"Perak\" atau \"Lencana penyelidikan\" yang sesuai. Silakan periksa."
