  Mail_55168_Desc = {
    Text = "Kepada Penjaga yang terhormat: \n Acara \"Sebelum Layu di Musim Semi\" telah berakhir. Saat ini, sisa \"Puisi Bahagia\", \"Puisi penuh kecemasan\", dan \"Puisi Penyesalan\" milik Penjaga akan dikonversi dengan rasio setiap 200 menjadi \"Rose Scrip\" × 5000. Harap Penjaga memeriksa."
