    Text = "Dewan Sekolah Mythag"
  },
  Mail_56101_Desc = {
    Text = "Penjaga{Male=tuan,Female=nyonya}:\n\nPada dini hari ini, sebuah mawar mekar di antara kicauan burung di awal musim semi.\nSeharusnya ia masih berupa tunas di cabang musim semi, namun pada Hari Valentine, di hari kelahiranku, ia mekar di musim yang bukan miliknya.\nAku teringat Cité. Setiap hari ulang tahunku, jalan-jalan di Cité selalu ramai. Aku mendengar suara bunga mekar, mendengar kata-kata cinta yang membuat wajah memerah. Namun sudah lama aku tak menyentuhnya... sampai hari ini.\nApakah Anda percaya pada kebetulan, Penjaga? Kebetulan adalah bahasa, dan mawar adalah gaya bahasanya. Hari ini, di taman Mythag yang penuh warna, mawar ini mekar, kelopaknya terbuka dengan anggun, seperti puisi yang memabukkan.\nJadi, hari ini, Penjaga... apakah Anda bersedia melihat mekarnya mawar ini bersamaku?\nAku dan bunga ini menantikan kedatangan Anda.\n\nHorla"
  },
  Mail_56101_Name = {
    Text = "Sebuah mawar bermekaran di musim semi..."
  },
  Mail_56101_Sender = {Text = "Horla"},
