  Mail_61154_Desc = {
    Text = "Kepada Penjaga yang terhormat: \n Acara \"Pesta Api·Replikasi\" telah berakhir. Saat ini, sisa \"Os Tibia asli\", \"Amónito Daun Bundar\", dan \"Reruntuhan Spiral\" milik Penjaga akan dikonversi dengan rasio setiap item menjadi \"Rose Scrip\"× 40. Harap Penjaga memeriksa penerimaannya."
