  },
  Mail_61155_Desc = {
    Text = "Kepada Penjaga yang terhormat:\n Acara rekayasa ulang \"Pemulihan Berganda·klon\" telah berakhir. Sisa mata uang acara Penjaga yaitu \"Puzzle Memori\" akan dikonversi dengan rasio setiap satu ditukar menjadi \"Rose Scrip\"× 40. Harap Penjaga memeriksa penerimaannya."
  },
  Mail_61155_Name = {
    Text = "Pemulihan Puzzle Memori"
  },
  Mail_61155_Sender = {
    Text = "Dewan Sekolah Mythag"
  },
  Mail_62392_Desc = {
    Text = "Penjaga: \n\nPertunjukanku pernah mengabdi di hadapan takhta kerajaan, dan juga pernah diidam-idamkan oleh ribuan orang. Namun, pujian berlebihan itu tidak berarti apa-apa bagiku; aku hanya mengejar kesempurnaan dalam musik. \nDibandingkan dengan tampil di tempat yang megah dan meriah untuk dinikmati orang lain, bermain sendirian di hutan yang sunyi jauh lebih membuatku rileks. \nAwalnya, aku tidak suka latihanku didengar orang lain, karena itu hanya draf menuju kesempurnaan, beberapa sampah tanpa makna. \nNamun, sejak aku mengetahui tentangmu dan menemukanmu, semua nada-nadaku memiliki arti. \nKamu memberikan nada teragung dan termulia dalam hidupku, menyelamatkanku dari kebingungan, meskipun kamu sendiri tidak menyadarinya… \nHari ini adalah ulang tahunku, yang tadinya sudah kulupakan, tapi sekarang aku ingin memperingati kelahiran baru diriku, dan orang yang memberiku kelahiran baru tersebut. \nKebetulan akhir-akhir ini ada partitur karya baru, dan aku ingin mengundangmu untuk sedikit mengapresiasinya. Maafkan keterlambatanku, identitasku masih belum cocok untuk muncul di hadapan rekan-rekan Mythag, sehingga aku hanya bisa menyerahkan undangan ini setelah cakrawala menelan sisa-sisa cahaya matahari. \nMalam ini di hutan belakang sekolah, aku akan mengadakan konser spesial, dengan satu kursi penonton saja. \nAku menantikan kedatanganmu. \n\nHameln"
  },
  Mail_62392_Name = {
    Text = "Konser rahasia…"
  },
  Mail_62392_Sender = {Text = "Hameln"},
  Mail_65350_Desc = {
    Text = "Kepada Penjaga yang terhormat: \n Acara \"Ketika gunung salju mencair\" telah berakhir. Saat ini, sisa mata uang acara Penjaga \"Bunga Beku\", \"Bunga Muda Berembun Perak\", dan \"Bunga Matahari Kecil\" akan dikonversi dengan rasio setiap item menjadi \"Rose Scrip\" × 40. Harap Penjaga ingat untuk memeriksa."
  },
  Mail_65350_Name = {
    Text = "Pengumpulan Kuncup Bunga"
  },
  Mail_65350_Sender = {
    Text = "Dewan Sekolah Mythag"
  },
  Mail_65441_Desc = {
    Text = "Kepada Penjaga yang terhormat:\n Acara \"Pengorbanan jurang·Replikasi\" telah berakhir. Saat ini, sisa \"Air mata pengorbanan\", \"Darah pengorbanan\", dan \"Sum-sum pengorbanan\" milik Penjaga akan dikonversi dengan rasio setiap item menjadi \"Rose Scrip\"× 40. Harap Penjaga memeriksa penerimaannya."
