  Mail_65441_Sender = {
    Text = "Dewan Sekolah Mythag"
  },
  Mail_65442_Desc = {
    Text = "Kepada Penjaga yang terhormat: \n Kegiatan \"Pintu Seribu Fenomena\" telah berakhir, kini kami akan mengembalikan mata uang kegiatan yang tersisa untuk Penjaga yaitu \"Poin Akhir\" dengan rasio penukaran \"Rose Scrip\" × 40 untuk setiap satu. Mohon Penjaga ingat untuk memeriksa."
  },
  Mail_65442_Name = {
    Text = "Pemulihan Jarum Akhir"
  },
  Mail_65442_Sender = {
    Text = "Dewan Sekolah Mythag"
  },
  Mail_67147_Desc = {
    Text = [[
Penjaga: 

    Dimensi alam semesta tidaklah tunggal bagiku, di dalam Pintu Kekosongan dapat terlihat ribuan dunia dan keberadaan tanpa batas. Di sana melampaui semua imajinasi dan logika matematika, sehingga tidak mungkin menentukan tanggal "hari kelahiran". 
    Jadi, anggaplah pertemuan pertama kita sebagai momen itu. Dalam kontinuitas waktu tempatmu berada, seharusnya hari ini akan diadakan upacara khusus untuk diriku, mewujudkan harapan yang kubuat. 
    Maka, lintasilah Gerbang Kunci Perak dan datanglah ke sisiku. Aku akan mengajarkanmu... beberapa pengetahuan tentang Genesis tertinggi, pengetahuan milik alam semesta. Malam ini, jutaan cahaya akan bersinar untuk kita berdua. 
    Aku menunggumu di Pintu Kekosongan.

Tawil]]
  },
  Mail_67147_Name = {
    Text = "Melintasi Gerbang Perak…"
  },
  Mail_67147_Sender = {Text = "Tawil"},
  Mail_67933_Desc = {
    Text = "Saya merasakan kebingungan singkatmu — Relik Agung itu, bahkan untuk menatap langsung hampir mustahil, bagaimana mungkin bisa terluka sedikit pun? Tapi kau berhasil melakukannya. \nSekali lagi pandangan runtuh, baju besi yang kokoh, di bawah Fragmen-Fragmen yang terus berjatuhan, meninggalkan goresan dan celah. \n%player%, satu-satunya yang tak terkalahkan adalah kehendak teguhmu."
  },
  Mail_67933_Name = {
    Text = "Menemukan jalan dari kebingungan"
  },
  Mail_67933_Sender = {Text = "Alistair"},
  Mail_67934_Desc = {
    Text = [[
Anggota tubuhmu gemetar, %player%. Kamu hampir tidak mampu berdiri. Rasa takut mencengkeram dirimu, membuat pikiranmu kosong dan sulit mengontrol napas... namun kamu tetap mengangkat Kunci perak ke depan.
Dari semua sifat mulia yang dimiliki manusia, keberanian adalah yang paling luhur. Menghadapi bencana alam dan binatang buas, kita pernah mengangkat palu batu dan tombak. Sekarang, menghadapi Dewa, kamu tetap melakukan hal serupa.
Peradaban manusia dibangun di atas dasar keberanian, dan akan terus hidup abadi karena keberanian.]]
  },
  Mail_67934_Name = {
    Text = "Lagu keberanian, bergema di tengah getaran"
  },
  Mail_67934_Sender = {Text = "Alistair"},
  Mail_67935_Desc = {
    Text = [[
Kami pernah berbicara tentang dunia ini. Kau berkata bahwa kau tidak menyukainya. Dunia ini dipenuhi dengan kepentingan, konspirasi, penipuan, dan pembunuhan. Bahkan tanpa Pelarutan dan campur tangan Dewa, dunia ini sudah penuh dengan luka dan goyah. Setelah Akut terbangun, dalam memori singkatmu, kau telah melihat ketidakteraturan dan kekejaman hati manusia yang lebih buruk daripada Pelarutan. 
Namun, ketika Pencipta mengangkat pedang-Nya, kau tetap berdiri di depan dunia ini. Kehancuran adalah kehendak Dewa, dan kau menolak-Nya. 
Aku mengerti, %player%. Tidak ada Penjaga yang tidak membenci dunia ini, dan tidak ada Penjaga yang tidak benar-benar mencintainya. Karena di tengah semua kekotoran itu, kita pernah melihat cahaya gemerlap seperti inti Perak. 
Tugas Penjaga adalah menjaga cahaya lemah itu agar tetap ada selamanya.]]
  },
  Mail_67935_Name = {
    Text = "Roh manusia abadi"
  },
  Mail_67935_Sender = {Text = "Alistair"},
  Mail_67936_Desc = {
    Text = "Pertama kali melihat pelarutan, pertama kali menghadapi kebenaran pelarutan, pertama kali merasakan suara Dewa… Dalam hidupku yang panjang, aku telah melewati banyak momen kemerosotan. Aku tidak tahu apa yang bisa kulakukan, tidak tahu apa arti dari semua usaha dan pengorbanan ini — tapi itu semua tidak seberapa dibandingkan dengan apa yang kau hadapi saat ini. \n Beginilah manusia: bangkit kembali dari kemerosotan berkali-kali, melangkah maju ke depan. \n Di ujung jalan mungkin ada jurang yang curam, tapi selalu ada orang yang ingin melihatnya."
  },
  Mail_67936_Name = {
    Text = "Runtuh, lalu dilahirkan kembali"
  },
  Mail_67936_Sender = {Text = "Alistair"},
  Mail_67937_Desc = {
    Text = [[
Batas Dimensi terbuka, akhirnya aku bisa menghubungimu lagi. 
Dibandingkan dengan apa yang kau lihat, pandangan di Dimensi ini sangat lemah, mungkin karena keberadaanmu tidak ada di sini. Setelah mengorbankan hampir segalanya, aku telah menyelesaikan masalah-Nya untukmu. 
Sulit membayangkan apa yang sedang kau hadapi. Tapi apa pun itu, kehendak kehancuran, aku akan melawan bersamamu. Ini adalah sumpah setiap orang Mythag. 
Senang sekali bisa berdiri di sisimu lagi. 
Semoga Kunci perak memandu jalan kita.]]
  },
  Mail_67937_Name = {
    Text = "Bahu-membahu bertarung, sekali lagi"
  },
  Mail_67937_Sender = {
    Text = "Pengirim Tidak Dikenal"
  },
  Mail_67938_Desc = {
    Text = "Kegilaan, sebuah kata yang ringan, bahkan indah.\nSebuah alam semesta Kekacauan melahirkan peradaban Kekacauan. Kekacauan adalah kebenaran dunia ini. Mengikuti Kekacauan, menikmati Kegilaan, betapa mudahnya hal itu. Dibandingkan dengan itu, kesadaran dan perlawanan begitu sulit. Kamu akan mengorbankan semua kebahagiaan dan Hidupmu hanya untuk mengejar jawaban yang tak terjangkau.\nNamun, kamu tetap memilih kesadaran, %player%. Karena kita dilahirkan bukan untuk menjadi budak.\nKamu membuat-Nya melihat, %player% — Relik-Nya, Fragmen-Nya, tidak pernah rela menjadi budak buta dan bodoh. Kamu melawan-Nya, mengalahkan pandangan-pandangan-Nya satu demi satu, dan memilih untuk melindungi dunia ini yang tidak sempurna dan tidak mudah.\nDalam pilihan itu, kamu telah memiliki kebebasan abadi."
  },
  Mail_67938_Name = {
    Text = "Kamu tak pernah rela menjadi budak yang buta dan bodoh"
  },
  Mail_67938_Sender = {Text = "Alistair"},
  Mail_67939_Desc = {
    Text = [[
Aku merasakan runtuhnya sebuah tatapan. Aku merasakan rasa sakit yang menyayat kulitmu. 
Ini adalah tanggung jawab yang terukir pada gelar Penjaga. Jalan yang kau pilih untuk dilalui jauh lebih sulit daripada yang pernah kuhadapi. Tidak semua orang memiliki keberanian untuk menghadapi Dewa yang luhur, dan keberanianmu membuatku merasa lega dan kagum. 
Aku tidak bisa membayangkan seberapa besar penderitaan yang akan kau alami dari Kekuatan Pencipta. Apa yang aku rasakan hanyalah sebagian kecil dari apa yang kau tanggung. Aku hanyalah seorang pecundang yang terperangkap di Kolam Hitam, %player%, aku sudah tidak mampu lagi berpartisipasi dalam pertarungan antara dirimu dan Pencipta, hanya bisa tetap terhubung denganmu melalui persepsiku. Ini akan menjadi misi terakhir dan paling penting dalam karierku. 
Dalam perjalanan yang kesepian ini, baik kau melihatnya atau tidak, Mythag akan selalu berada di sisimu.]]
  },
  Mail_67939_Name = {
    Text = "Kesedihan tidak akan membuatmu tunduk"
  },
  Mail_67939_Sender = {Text = "Alistair"},
  Mail_67940_Desc = {
    Text = "Saya mendengar bisikan dari Kehendak Tertinggi — peradaban yang megah, suka duka manusia, orang-orang tak terhitung yang mengelilingi dan menjauhi dirimu, semuanya tak pernah ada. \nSelama berhari-hari dan bertahun-tahun di Kolam Hitam, pemandangan ini membuat saya ketakutan. Pohon-pohon menancapkan akarnya di tanah, lalu tumbuh ke atas menuju matahari — memori, memori adalah tanah kita, tempat kita tumbuh, berdiri, dan pada akhirnya akan kembali. Saya takut kehilangan tanah itu, melayang di dalam ilusi, tanpa asal, tanpa akhir. \nTerima kasih, %player%. Saya pikir, saya menyaksikan pertempuran besar. Ini adalah pertempuran antara manusia dan Dewa. Ini adalah pertempuran antara perlindungan dan Kehancuran. \nIni adalah pertempuran antara mengingat dan melupakan. \nKamu berhasil, %player%. Kamu menyelesaikan hal yang tak seorang pun berani bayangkan. Kamu memperoleh Kekuatan tak tertandingi dari ingatan. Dengan kekuatan ini, kamu berjuang demi ingatan. \nKamu telah menemukan mataharimu sendiri di tanah abadi ini."
  },
  Mail_67940_Name = {
    Text = "Berjuang untuk mengingat"
  },
  Mail_67940_Sender = {Text = "Alistair"},
  Mail_68825_Desc = {
    Text = "Kepada Penjaga yang terhormat: \n Acara \"Pemulihan Raja Dewa\" telah berakhir. Sisa mata uang acara Penjaga, yaitu \"Pikiran Lelah\", \"Pikiran sedih\", dan \"Pikiran Bahagia\", akan dikonversi dengan rasio setiap satu menjadi \"Rose Scrip\"× 40. Harap Penjaga memeriksa penerimaannya."
  },
  Mail_68825_Name = {
    Text = "Pemulihan Mata Uang Kebangkitan Sang Dewa"
  },
  Mail_68825_Sender = {
    Text = "Dewan Sekolah Mythag"
  },
  Mail_68826_Desc = {
    Text = "Yth. Penjaga: \n Kegiatan \"Gelombang Laut Nafsu·klon\" telah berakhir. Sisa \"Benih ibu\" milik Penjaga akan dikonversi dengan rasio setiap biji menjadi \"Rose Scrip\"× 40. Harap Penjaga memeriksa penerimaannya."
  },
  Mail_68826_Name = {
    Text = "Pengumpulan Kembali Benih Ibu"
  },
  Mail_68826_Sender = {
    Text = "Dewan Sekolah Mythag"
  },
  Mail_68898_Desc = {
    Text = [[
Yang tercinta, Tuan yang paling berharga: 

Sebagai pelayan serba bisa, Karen dapat mengingat banyak hari penting para orang dewasa, mulai dari hari pesta, ulang tahun, hari peringatan, hingga hari pertama membeli hewan peliharaan. Tidak akan ada kesalahan sedikit pun. Namun bagi Karen sendiri, hanya ada satu hari istimewa yang bisa dirayakan, yaitu hari ini. 
Sangat lama sekali yang lalu, saat Karen masih menjadi pelayan di istana dan pertama kali meminta sepotong sisa kue penutup kepada koki untuk dijadikan kue ulang tahun, dia dimarahi habis-habisan. Koki itu melemparkan kue ke wajahku. Saat itu aku berpikir, ternyata kue itu sangat enak. Aku harus menemukan seorang tuan yang baik hati agar setiap tahun aku bisa makan kue di hari ulang tahunku. 
Sekarang aku memiliki Nyonya Sorel yang sangat anggun dan murah hati, serta Tuan yang sangat baik seperti Anda. Keinginanku dulu sudah terwujud! Namun, manusia selalu semakin tamak... eh, maksudku, selalu berkembang. Sekarang keinginanku adalah bisa berada di sisi Tuan setiap tahun di hari ulang tahunku. Dan kalau ada Hadiah yang berkilauan setiap tahun, tentu lebih baik lagi. 
Setelah mendengar semua ini, Anda pasti akan mempersiapkannya untukku kan, bukan begitu? 

Pelayanmu yang selalu rendah hati, 
Karen]]
  },
  Mail_68898_Name = {
    Text = "Tahun demi tahun sama..."
  },
  Mail_68898_Sender = {Text = "Karen"},
  Mail_68899_Desc = {
    Text = [[
Bibit Pohon: 

Melihat pertumbuhanmu selama ini, aku semakin yakin bahwa memilihmu dan membantumu adalah keputusan paling tepat yang pernah kulakukan. 
Aku merasakan sukacita panen; semua kepercayaan dan cinta yang kuberikan telah memberiku balasan yang manis. Kamulah yang memberiku harapan dan masa depan. 
Sekarang aku bisa melepaskan obsesi akan perkembangbiakan dan sepenuhnya menikmati buah cinta di luar itu. 
Dunia ini mungkin tak lagi membutuhkan Ratu Aran, tapi mungkin masih ada tempat untuk seorang wanita biasa yang memiliki keinginan sederhana untuk ditemani oleh pasangan di hari ulang tahunnya. 
Seperti pasangan pada umumnya, pergi bersama membeli bahan makanan, memasak hidangan lezat bersama, mungkin masih banyak hal yang belum pernah kualami. Jadi, sayangku, bisakah kau membimbingku untuk melewati ulang tahun yang hangat dan sederhana? 

Thais]]
  },
  Mail_68899_Name = {
    Text = "Kehidupan yang biasa…"
  },
  Mail_68899_Sender = {Text = "Thais"},
  Mail_68900_Desc = {
    Text = [[
Penjaga: 

Master Casiah adalah pemain panggung terhebat di dunia, mampu meniru semua ekspresi dengan sempurna, tetapi emosi manusia adalah teka-teki dunia yang tak bisa dipahami bagaimana pun caranya. 
Saya sudah bertanya kepada banyak orang, mereka semua tidak bisa menjelaskan prinsip di balik emosi, sampai saya bertanya kepada Boneka. Dia memberi tahu saya bahwa ada disiplin ilmu bernama psikologi. Meskipun tidak bisa merasakan secara langsung, jika mempelajarinya dengan baik, kita bisa menguasai semua teori tentang emosi. 
Ini benar-benar sangat menarik! Apakah keraguan yang mengganggu Casiah selama ini akan segera terpecahkan? 
Ngomong-ngomong, saya datang untuk memberitahumu bahwa minggu ini saya akan bergabung dalam kelas psikologi bersamamu. Casiah memutuskan untuk menjadi teman sebangkumu. Kamu harus membantu saya mengejar materi yang ketinggalan, ya, teman sebangku~ 
Ah iya, sekalian, hari ini adalah ulang tahunku. Di sini saya harus senang, dan kamu juga harus senang, kan? 
Jika ada hal yang sangat menyenangkan, mari buat suasana meriah di sekolah. Saya akan membuat kampus terlihat seperti mimpi yang indah! 

Casiah]]
  },
  Mail_68900_Name = {
    Text = "Psikologi…"
  },
  Mail_68900_Sender = {Text = "Casiah"},
  Mail_68901_Desc = {
    Text = "Utusan Pucat yang terhormat: \n\nTerima kasih atas bantuan dan perhatianmu selama setahun ini. Ketulusan hatimu terhadap orang lain begitu mulia, seperti yang diajarkan oleh Sang Pencipta. Meskipun kesempatan bertemu denganmu tidak sering, setiap kali aku bertemu denganmu, rasanya seperti bertemu teman lama yang sudah dikenal lama, membuatku merasa nyaman seperti angin musim semi. \nHari ulang tahun ini mungkin tidak istimewa, tetapi sebagai alasan untuk bertemu teman, itu tetap menimbulkan rasa antisipasi. Selain kamu, aku tidak bisa memikirkan orang lain yang lebih cocok untuk menghabiskan hari ini bersama. \nJika kamu tertarik, aku ingin mengajakmu mencoba hobi baruku — memancing. Tentu saja, bukan untuk memasak atau dimakan, hanya sekadar menikmati proses menunggu hadiah ajaib dari takdir dengan tenang. Aku ingin berbagi perasaan damai ini denganmu, pergi ke alam, dan duduk dengan tenang di tepi danau. \nSeorang teman lama, dua batang pancing, sepertinya akan menjadi hari yang sangat sempurna. \n\nSalvador"
  },
  Mail_68901_Name = {
    Text = "Hobi baru memancing…"
  },
  Mail_68901_Sender = {Text = "Salvador"},
  Mail_68902_Desc = {
    Text = [[
Tuan: 

Untuk ulang tahunku tahun ini, Aigis dan Jenkin memberiku sebuah lonceng angin kaca yang sangat mirip dengan Aurita.
Aku menggantungnya di jendela kamarku, dan saat angin bertiup, lonceng itu mengeluarkan suara yang indah, membuatku teringat pada ibuku yang dulu sering memelukku di dekat jendela sambil menceritakan cerita.
Jangan khawatir, Tuan. Meskipun aku selalu merindukan ibuku setiap hari, dengan Tuan dan semua orang di sisiku, Lily tidak akan merasa kesepian.
Sekarang Lily sudah belajar membaca buku cerita sendiri. Setiap sore, cahaya oranye matahari masuk ke dalam rumah, menyinari lonceng angin, menciptakan pola riak bergerak di atas buku cerita, membuat ruangan terasa hangat.
Lily sangat suka melamun pada saat-saat seperti ini, memandangi awan dan lonceng angin di bawah sinar senja, rasanya begitu indah.
Kalau Tuan punya waktu hari ini, ayo coba bersama-sama melamun dengan Lily.

Lily]]
  },
  Mail_68902_Name = {
    Text = "Lonceng angin kaca…"
  },
  Mail_68902_Sender = {Text = "Lily"},
  Mail_68903_Desc = {
    Text = [[
Bocah: 

Meskipun hari istimewa ini ditetapkan untuk memperingati manusia itu, aku harus mengakui bahwa hari diskon adalah skema penjualan yang sangat menarik bagi pelanggan dan pedagang. 
Pada ulang tahun terakhirku, jumlah pesanan di toko kecil Penenang hampir menyamai penjualan setengah tahun biasanya, terutama barang-barang spesial yang kujadikan sebagai bagian dari perayaan semuanya terjual habis. Haruskah aku mengatakan bahwa para tamu di Mythag sangat mendukung bisnisku, atau bahkan penyelidik yang cermat dan hati-hati tidak bisa menolak godaan diskon? 
Pokoknya, demi melanjutkan kebahagiaan yang saling menguntungkan, acara diskon dalam pesta ulang tahunku tahun ini akan tetap diadakan, hanya sekali setahun, dengan diskon besar-besaran, buruan beli sebelum kehabisan. Ingatlah untuk membantuku mempromosikannya dengan baik di Mythag, dan agar mudah diingat, mari kita sebut hari ini sebagai Hari Ganda Sepuluh. 
Selain itu, aku sudah diam-diam menyisihkan beberapa barang kecil yang menarik untukmu, pastikan datang menemuiku lebih awal ya. 

Narsis]]
  },
  Mail_68903_Name = {
    Text = "Hari diskon…"
  },
  Mail_68903_Sender = {Text = "Daffodil"},
  Mail_68904_Desc = {
    Text = [[
Mendapatkan wahyu dari takdir, Penjaga Universitas Mythag, Penguasa bijaksana dan berbelas kasih:
Selamat datang!
Jika dikatakan bahwa setiap kehendak hidup seorang ksatria adalah mengikuti seorang penguasa besar, maka karir ksatria saya pastilah tanpa penyesalan.
Selain keberuntungan dalam hidup saya, banyak tragedi dan darah yang tidak beruntung, saya tahu banyak orang di Mythag telah bersimpati kepada saya karena itu.
Belum lagi hanya membandingkan penderitaan, sudah terlalu banyak orang yang tidak beruntung di Mythag, di dunia yang dipenuhi penderitaan seperti ini, membela dan mengorbankan darah bukanlah hal yang perlu disayangkan. Sebaliknya, baik di masa lalu maupun sekarang, saya merasa terhormat untuk itu dan selalu siap mengorbankan tubuh ini.
Tetapi Yang Mulia Lotan berkata bahwa saya tampak terlalu lelah dengan wajah cemberut setiap hari, membiarkan saya bersenang-senang pada hari ulang tahun saya, dan memanggil Jenkin untuk mengajari saya bermain, katanya agar saya bisa menemukan kembali masa kecil saya.
Rasanya memalukan, saya terlalu sibuk berlatih di masa kecil, sebenarnya tidak banyak pengalaman bermain, tidak menyangka permainan yang katanya bisa dikuasai oleh anak lima tahun ternyata begitu sulit, tampaknya masih banyak yang harus saya pelajari di luar jalan ksatria.
Jika Penguasa berkesempatan hari ini, tidak tahukah apakah Anda bisa datang bermain bersama kami, saya melihat Jenkin sudah mulai bosan setelah memenangkan sepuluh pertandingan berturut-turut, jika Penguasa ada di sini, pasti akan membawa permainan yang menarik.

Ogier]]
  },
  Mail_68904_Name = {
    Text = "Permainan yang keras…"
  },
  Mail_68904_Sender = {Text = "Ogier"},
  Mail_68905_Desc = {
    Text = [[
Hai: 

Dengan kalender itu, aku yakin kamu pasti tidak lupa dengan ulang tahun Yang Terhormat Penguasa Labirin tahun ini. 
Aku mengizinkanmu datang ke kamarku untuk memberikan Hadiah, sekalian melayani aku di hari ini. 
Misalnya seperti menyikat gigi, mencuci muka, berganti pakaian, makan, juga membersihkan kamar, mengganti seprai. Kalian punya istilah untuk itu, apa namanya? Pembersihan besar-besaran! 
Ya, semua pekerjaan pembersihan besar-besaran itu aku serahkan padamu. Aku sudah muak dengan semua pekerjaan rumah tangga ini. Apapun yang terjadi hari ini, aku ingin merasakan kembali kehidupan seperti dulu di Roma, hidup bermalas-malasan tanpa harus melakukan apa-apa. 
Hari ini, tidak peduli siapa, jangan harap bisa membuatku melakukan sedikit pekerjaan. Siapapun juga tidak akan bisa! 

Agrippa]]
  },
  Mail_68905_Name = {
    Text = "Kembali ke masa lalu…"
  },
  Mail_68905_Sender = {Text = "Agrippa"},
  Mail_68906_Desc = {
    Text = "Penjaga: \n\nWaktu berlalu begitu cepat, tak disangka kehidupan yang dulu kupikir akan berlangsung hingga mati, sekarang hampir tidak bisa kuingat lagi. \nSekarang, nona ini sudah sangat memahami semua kue kecil di kantin, tak peduli bagaimana aku mendorong para koki yang tak berguna itu, mereka tetap tidak bisa membuat sesuatu yang baru. \nJadi, di tahun yang baru ini, peta kulinerku harus menjadi lebih besar, lebih jauh. Mari kita tetapkan target kecil: mencicipi semua toko kue di Londinium. \nAdapun pekerjaan mulia seperti antri dan berlari, itu tetap akan kuserahkan padamu! Tak perlu terlalu senang mendapatkan kepercayaan dari nona ini, cukup bersyukur dan puji nama wanita bangsawan ini. \nNamun, ngomong-ngomong, para koki bodoh itu masih memiliki sedikit ketulusan. Dari percakapan diam-diam mereka yang tertutup-tutup, aku sudah mendengar bahwa mereka sepertinya menyiapkan kue raksasa dengan sepuluh lapis — ha, mereka masih saja buruk dalam menyembunyikan kejutan. \nMeskipun idenya agak klise, mungkin kali ini aku bisa mengundang lebih banyak orang untuk pesta ulang tahunku, seperti teman-teman baru yang kujalin setahun ini. \nSebagai teman pertama nona ini di Mythag, aku mengizinkanmu memotong kue pertama atas namaku. \n\nMurphy"
  },
  Mail_68906_Name = {
    Text = "Kue lapis sepuluh tingkat…"
  },
  Mail_68906_Sender = {Text = "Murphy"},
  Mail_68907_Desc = {
    Text = "Kepada Penjaga yang tercinta: \n\nSeperti kebijaksanaanmu, pasti kamu sudah mengetahui informasi ini dari arsip ajaib Mythag — hari ini adalah hari bersejarah dalam hidup \"Detektif Keberuntungan\". \nKelahiran, memenangkan permainan blackjack pertama, memenangkan balapan kuda ke-100, memecahkan kasus pembunuhan ruang tertutup pertama, kekalahan yang membawa kematian — semuanya terjadi pada tanggal 6 Juni yang ajaib ini. \nJadi, bagaimana kalau kita bermain kartu jembatan untuk dua orang? Hari ini, mari kita buat hari ini lebih berkesan, apa pendapatmu? \n\nRyker"
  },
  Mail_68907_Name = {
    Text = "Mau main satu ronde?"
  },
  Mail_68907_Sender = {Text = "Ryker"},
  Mail_68908_Desc = {
    Text = "Surat ini bukanlah sebuah sapaan, melainkan sebuah peringatan — jangan coba-coba mengendalikanku, jangan coba-coba membelengguku.\nAku hanya milik diriku sendiri.\nAku tidak seperti orang yang mirip denganku, yang masih memiliki harapan kekanak-kanakan terhadap manusia dan dunia.\n\nAku akan membunuh siapa pun yang berani menjadi \"tuan\"-ku. Aku bicara serius.\n\nH"
  },
  Mail_68908_Name = {
    Text = "Saya termasuk…"
  },
  Mail_68908_Sender = {
    Text = "Helot: Catena"
  },
  Mail_68909_Desc = {
    Text = [[
Penjaga:

Mungkin saya pernah menceritakan kepada Anda tentang cinta saya pada air, dibandingkan dengan dunia yang bising, dunia di dalam air begitu tenang dan damai.
Saya pernah melayang di antara rumput laut dan terumbu karang, dan juga berbicara dengan sekolah ikan. Semakin jauh saya dari permukaan air, warna di dalam air menjadi semakin gelap, saat dibawa lembut oleh gelombang air melihat ke langit dari dasar air, cahaya yang berserak memperlihatkan warna yang memabukkan, adalah pemandangan terindah dalam hati saya.
Apakah Anda tahu? Beberapa makhluk laut dapat mengingat penampilan manusia, ketika Anda kembali berkunjung,"teman-teman" ini akan menyambut Anda dengan hangat, misalnya saya mengenal seekor cumi-cumi yang pintar, dan seekor ikan laut kuning muda.
Di hari ulang tahun ini, saya teringat kembali pada dunia bawah air, tidak tahu apakah Anda bersedia untuk sekali menyelam, saya sungguh berharap dapat membagikan keindahan dunia yang tenang ini, serta teman-teman ajaib saya kepada Anda.

Nymphaea]]
  },
  Mail_68909_Name = {
    Text = "Dunia dalam air…"
  },
  Mail_68909_Sender = {Text = "Nymphaea"},
  Mail_68910_Desc = {
    Text = "Penjaga: \n\nSejak kamu datang ke Mythag, aku sudah terbiasa menangani segala sesuatu yang berhubungan denganmu dengan cara seperti merawat bayi. Dari reaksimu sehari-hari, kelemahanmu jauh melampaui harapanku.\nNamun sebagai pembimbing dan wali pertamamu, aku senang melihat bahwa selama setahun ini, jumlah masalah dan keruwetan yang harus kuselesaikan untukmu semakin berkurang. Meskipun saat kamu baru masuk, kondisi otakmu yang kosong benar-benar membuat putus asa, tetapi kecepatan perkembanganmu memang bisa disebut sebagai gabungan dari bakat dan usaha.\nSelamat, kamu sekarang telah menjadi Penjaga yang memenuhi syarat, tidak mengecewakan harapanku.\nDi hari ulang tahunku yang biasa saja tanpa ada yang istimewa, aku sudah menyiapkan hadiah untukmu — program pelatihan khusus yang pernah digunakan oleh Alistair. Bagaimana, apakah kamu sangat menantikannya?\nJangan tanya kenapa aku yang memberikanmu hadiah. Hari-hari ketika aku tidak bisa masuk ke laboratorium, aku harus mencari sesuatu untuk dilakukan, bukan?\nKetika kamu sudah siap, datanglah menemuiku di ruang latihan.\n\nBoneka"
  },
  Mail_68910_Name = {Text = "Hadiah…"},
  Mail_68910_Sender = {Text = "Doll"},
  Mail_68911_Desc = {
    Text = [[
Penjaga:

Satu tahun waktu bagi seorang penari hanyalah ribuan kali berputar, ribuan kali melompat, kecuali sepasang sepatu tari yang menemani saya lama diganti, semuanya tampak tidak berubah, namun semuanya juga tampak berbeda.
Dibandingkan dengan kesendirian yang biasa saya rasakan dulu, tahun ini saya selalu memiliki satu penonton setia, satu mitra tari yang agak canggung.
Setiap kali Anda duduk di studio tari, saya merasa tubuh saya lebih ringan, seperti ketika saya baru belajar menari pada masa kecil saya, dipenuhi semangat dan dorongan yang tak terjelaskan.
Mungkin saya tidak seberbakti dan mulia seperti yang saya pikirkan, saat saya mengabdikan hidup saya untuk menari, saya juga berharap dapat memiliki perhatian Anda, mendengar tepukan tangan Anda.
Hari ulang tahun ini cuacanya sangat baik, saya bisa merasakan malam ini langit akan sangat cerah. Penonton paling antusias saya dan pasangan tarian eksklusif saya, apakah Anda bersedia berjalan bersama saya ke hutan yang indah dengan danau menawan, untuk menari satu tarian milik bulan dan bintang?

Liz]]
  },
  Mail_68911_Name = {
    Text = "Pasangan dansa pribadi…"
  },
  Mail_68911_Sender = {Text = "Liz"},
  Mail_68912_Desc = {
    Text = [[
Penjaga: 

Sejak hari kebangkitan saya, orang-orang di Mythag telah banyak membantu saya, mungkin saya masih belum terbiasa dengan perasaan kerja sama, tetapi setidaknya ketika berjalan bersamamu, saya sudah bisa mempercayakan punggung saya dengan tenang, perasaan ini... juga tidak buruk.
Kebanyakan waktu dalam hidup saya dipenuhi dengan luka dan pengkhianatan, saya selalu menganggap melawan ini sebagai makna pertempuran saya, sampai tidak ada lagi yang tersisa dalam hidup saya, pandangan saya sudah tidak bisa berpaling dari balas dendam.
Sekarang mengikuti langkahmu, saya baru menyadari bahwa selain kerusakan dan pembalasan, pertempuran juga bisa memiliki banyak makna, bahkan seperti yang dikatakan Lotan, pertempuran juga bisa hanya pertempuran.
Saya belajar menikmati kesenangan bertarung, menikmati perasaan yang dahsyat, menikmati menjadi seorang prajurit yang berani.
Jika pertempuran saya dapat membawa lebih banyak, maka saya akan menikmati kehormatan itu.
Dan kamu, baik sekarang maupun di masa depan, saya berjanji bahwa mata pedang saya tidak akan pernah mengarah kepadamu.

Helot]]
  },
  Mail_68912_Name = {
    Text = "Makna pertempuran…"
  },
  Mail_68912_Sender = {Text = "Helot"},
  Mail_68913_Desc = {
    Text = [[
Yang Terhormat Penjaga Rahasia:

Jujur saja, aku tidak terlalu memikirkan soal harapan ulang tahun. Dulu, ketika aku masih "normal", makan kenyang, pakaian cukup, membayar sewa tepat waktu, dan merawat Jenkin sudah menjadi keinginan terbesarku setiap hari. Sekarang, bisa melewati satu tahun dengan tenang dan melihat Jenkin berbuat onar selama setahun sudah cukup membuatku puas.
Agak memalukan mengakui ini, di depan Jenkin aku selalu bertindak seperti seorang kakak yang mendisiplinkannya, tapi bagimu, aku sering kali menyusahkanmu. Bahkan aku sendiri sering lupa mana diriku yang telah menyebabkan masalah itu.
Kesabaran dan kelembutanmu yang tak pernah berubah membuatku merasa hangat sekaligus malu. Mungkin inilah pertama kalinya dalam hidupku seseorang merawatku dengan sikap begitu penuh pengertian. Aku merasa sangat terhormat dan bersyukur dari lubuk hati.
Tahun ini aku membuat kue besar untuk semua orang, resepnya diajarkan oleh bibi dari pabrik tekstil dulu. Meskipun tidak sebaik hasil para koki, rasa spesial itu sangat disukai olehku dan Jenkin. Kali ini tidak perlu khawatir tentang bahan-bahannya, semua orang bisa menikmatinya sampai puas. Tolong datang dan cicipi ya.
Aku sudah berhasil membujuk diriku yang lain untuk benar-benar merayakan ulang tahun dengan tenang. Mereka hari ini pasti, pasti tidak akan merepotkanmu lagi!
Jika memungkinkan, jangan ragu memanggilku kapan pun kamu butuhkan. Baik mencuci, membersihkan, atau merapikan, aku sangat mahir. Aku juga ingin memiliki kesempatan untuk membalas kelembutanmu.

Mason]]
  },
  Mail_68913_Name = {
    Text = "Membalas budi..."
  },
  Mail_68913_Sender = {Text = "\"24\""},
  Mail_68914_Desc = {
    Text = "Penjaga:  \n\nSebagai seseorang yang bertanggung jawab menerima harapan semua orang, sepertinya tidak peduli seberapa keras aku berusaha, aku tidak pernah terbiasa dengan kenyataan bahwa pada hari ulang tahunku sendiri aku harus membuat keinginan. Bagiku, sepertinya aku tidak memiliki apa pun yang benar-benar kuinginkan.\nBoneka memberitahuku bahwa aku perlu menemukan hal yang benar-benar kuharapkan di dalam hatiku yang terdalam, dan bertanya pada diriku sendiri untuk apa semua yang kulakukan.\nAku sudah memikirkannya sangat lama. Sebenarnya, aku berharap semua keinginan dari orang-orang yang datang padaku bisa terwujud. Jika dipikir lebih jauh lagi, aku rasa aku suka senyuman yang mereka tunjukkan ketika keinginan mereka tercapai, dan cara mereka dengan tulus mengelilingiku, berterima kasih padaku, serta memujiku karena telah menjalankan tugas sebagai Dewi.\nBoneka berkata bahwa itu berarti aku ingin nilai diriku diakui dan menjadi seseorang yang berguna. Aku merasa dia benar.\nNamun, dia juga mengatakan bahwa nilai seseorang tidak perlu ditentukan oleh orang lain. Tidak ada yang disebut berguna atau tidak berguna. Yang penting adalah apakah kita mengikuti kata hati kita sendiri, bahkan jika kita dianggap tidak berguna oleh orang lain.\nMemang tipikal Boneka, selalu mengatakan hal-hal yang begitu mendalam. Namun, apakah aku harus menjadi orang yang berguna atau tidak berguna? Sepertinya aku mulai bingung lagi…\nTapi jika aku harus mengikuti kata hatiku, mungkin aku tetap ingin menjadi orang yang berguna. Jika pada hari ulang tahunku aku bisa melihat senyuman semua orang, itu mungkin hadiah yang paling kuinginkan.\n\nCeleste"
  },
  Mail_68914_Name = {
    Text = "Orang yang berguna..."
  },
  Mail_68914_Sender = {Text = "Celeste"},
  Mail_68915_Desc = {
    Text = [[
Yang Terhormat Penjaga: 

Saya sudah terbiasa dengan cara hidup seperti ulat di selokan, mungkin itulah takdir saya sejak lahir, dan saya sepenuhnya menerimanya, bahkan dengan sukacita memeluknya. 
Meskipun saya selalu bersyukur karena kalian telah membiarkan saya merasakan kembali nikmatnya kebebasan, tidak banyak orang yang bisa menerima hobi-hobi khusus saya, dan itu wajar saja. Kebanyakan orang di sini adalah orang-orang baik yang lembut, mereka tidak dapat memahami bahwa lumut yang tumbuh di sudut-sudut lembap tidak membutuhkan sinar matahari yang cerah, melainkan udara yang gelap. 
Kecuali Anda, Yang Terhormat dan Baik Hati, hanya Anda yang benar-benar memahami dan membantu saya, memberi saya kebahagiaan yang datang dari hati. Rasa sakit yang Anda berikan begitu memuaskan dan menenangkan, membuat saya bisa merasakan keberadaan saya sendiri. 
Jika dulu saya tidak memiliki keinginan apa pun untuk diucapkan saat ulang tahun, sekarang saya berharap bisa mengikuti di belakang Anda, memberikan Dedikasi tubuh dan jiwa saya kepada Anda. 
Tentu saja, jangan bersikap lembut kepada saya! Silakan hina saya, marahi saya, cambuk saya sepuasnya! 

Leigh]]
  },
  Mail_68915_Name = {
    Text = "Hati lumut..."
  },
  Mail_68915_Sender = {Text = "Leigh"},
  Mail_68916_Desc = {
    Text = "Anak anjing yang tercinta: \n\nAku hampir jatuh cinta pada hari-hari bermain seperti ini denganmu, seperti novel pahlawan kuno, di mana pembela keadilan selalu berhasil menghentikan rencana jahat penjahat tepat pada saat terakhir, begitu menyentuh dan begitu hebat. \nNamun, melihatmu terus berjuang dengan sia-sia benar-benar membuatku tak bisa menahan tawa. \nDunia ini sudah lama hancur, tidak ada cara untuk diselamatkan, planet ini akan seperti ribuan planet mati lainnya, menjadi ▼&#x5B▼87;&4;▼. \nAh, sudahlah, aku akan tetap menemanimu bermain. Sampai sekarang aku mulai sedikit memahami kesenangan N, sebelum akhir yang sudah ditakdirkan tiba, apa pun yang dilakukan sebenarnya tidak ada bedanya. \nDi hari ulang tahun guru tercintamu ini, aku masih menyiapkan kejutan besar untukmu. Sebelum hitungan mundur ulang tahun berakhir, semoga kamu bisa menemukan \"bom\" tersembunyi itu ya. \nSebelum kita semua benar-benar lenyap, berapa banyak lagi kesenangan yang bisa kamu berikan padaku? \n\n\n\"Boneka\""
  },
  Mail_68916_Name = {
    Text = "Bom kejutan…"
  },
  Mail_68916_Sender = {
    Text = "Doll: Inferno"
  },
  Mail_68917_Desc = {
    Text = [[
Penjaga: 

Akhir-akhir ini, di kalangan elit Londinium sedang populer tren membuat desain sendiri dan memesan perhiasan khusus. 
Para wanita bangsawan yang mengklaim diri mereka sangat memahami seni sekarang berlomba-lomba membandingkan kecanggihan desain mereka, bukan lagi ukuran permata. Tanpa mereka sadari, tindakan diam-diam mereka merekrut pelukis terkenal begitu jelas seperti menutup mata sendiri untuk menipu diri. 
Berkat tren ini, daftar hadiah ulang tahunku juga bertambah dengan beberapa permata dan perhiasan yang hanya ikut-ikutan gaya. Salah satunya adalah merah darah merpati yang bagus, tapi masih membutuhkan cincin yang cocok. 
Daripada mencari pria tua yang membosankan, aku lebih suka ksatriaku melukiskan sebuah desain penuh makna sebagai hadiah untukku. Bagaimana menurutmu? 
Aku akan sangat menantikan hasil karyamu. Aku percaya selera mu pasti bagus. 

Sorel]]
  },
  Mail_68917_Name = {
    Text = "Mendesain perhiasan…"
  },
  Mail_68917_Sender = {Text = "Sorel"},
  Mail_68918_Desc = {
    Text = [[
Penjaga: 

Sebelum pertemuan pertama kita, di balik ribuan pintu, aku telah melihat banyak versi dirimu yang sama namun berbeda. 
Aku ingat suka duka mu, setiap pilihan yang kau buat, dan sosokmu yang terus maju di dunia-dunia yang berbeda. 
Bagiku, di antara banyaknya versi dirimu, kau adalah yang paling istimewa. Aku pernah memberi nama dan nomor pada dunia-dunia yang kuamati dalam hati, dan dunia tempat kau berada kusebut Harapan, nama itu kuberikan pada hari aku bertemu denganmu. 
Di hari yang kusebut Harapan ini, mungkin kau akan tertarik untuk melihat dunia-dunia lain, seperti mata yang menjelajahi alam semesta. Aku akan membawamu melihat segala sesuatu yang kuamati saat berdiri di depan pintu-pintu itu. 
Dan lihatlah dirimu di mataku. 

Tawil]]
  },
  Mail_68918_Name = {
    Text = "Dirimu yang berbeda…"
  },
  Mail_68918_Sender = {Text = "Tawil"},
  Mail_68919_Desc = {
    Text = [[
Gaya singkat Mythag sebenarnya sangat sesuai dengan hatiku, namun sejak kedatangan wanita itu, Miryam, kehidupanku mulai tidak tenang.
Aku tidak menolak mereka yang mencari ketenangan dan perlindungan. Di dunia yang kotor ini, mencari kenyamanan adalah hal yang wajar dan bisa dimengerti.
Namun, aku selalu tidak suka menganggap diri sebagai Dewa yang serba bisa, apalagi setelah tenggelamnya Lemuria. Tempat ini tidak membutuhkan Dewa lain yang berada di atas awan.
Miryam mungkin masih sulit melupakan Bayangan masa lalu, sehingga ia membawa gaya kepercayaan buta itu ke masa sekarang, membuatku menjadi sorotan di mana pun aku pergi di kampus, bahkan terusik tanpa henti, sangat menjengkelkan.
Hari ulang tahunku kali ini, pasti wanita itu sudah menyiapkan upacara besar-besaran jauh-jauh hari. Mendengarnya saja sudah membuat telingaku bising, melihatnya membuat kepalaku pusing, jadi aku tidak akan hadir untuk menghindari masalah.
Jika kamu tertarik, kamu bisa datang ke alamat yang terlampir di surat ini untuk berjalan-jalan dan menenangkan pikiran.
Ingatlah, jangan sampai wanita itu mengetahuinya.

Tulu]]
  },
  Mail_68919_Name = {
    Text = "Menghindari ketenangan..."
  },
  Mail_68919_Sender = {Text = "Tulu"},
  Mail_68920_Desc = {
    Text = [[
Setiap hari aku merasa sangat lapar, jika sebentar saja tidak minum darah, aku sudah tidak tahan. Tapi sejak mencicipi darahmu, darah biasa terasa seperti lilin di mulutku, sulit untuk ditelan. Rasa indah dari darahmu selalu menggoda tenggorokanku setiap hari.
Aku tahu berapa banyak darah yang bisa kuminum saat menghisap seseorang sampai kering, kelezatan itu bisa dibilang hanya sesaat. Agar kamu tidak mati terlalu cepat, aku akan belajar bertahan dari rasa lapar, belajar menantikan kelezatan berikutnya, sampai hari aku bisa mencicipi darahmu lagi.
Ha, astaga, aku tidak percaya aku benar-benar berhasil melakukannya. Aku bahkan curiga apakah aku sudah berevolusi. Melihat betapa sabarnya aku, setidaknya di hari ulang tahun ini, biarkan aku mencicipi sedikit darahmu yang manis dan lezat, bagaimana? Hanya sedikit saja.
Aku membeli suplemen nutrisi untukmu dengan uang yang kudapat dari klub trout. Kali ini kamu pasti tidak akan anemia lagi.

Uvhash yang sudah kelaparan lama]]
