  Mail_68921_Desc = {
    Text = [[
Kepada Penjaga yang terhormat: 

Saya sangat senang melihat kemajuanmu yang berkelanjutan di kelas pelatihan selama setahun ini. Segera, kamu akan bisa melampaui diriku saat masih muda dan menjadi seorang tentara yang tangguh. Merupakan suatu kehormatan bagi saya untuk menjadi instruktur pelatihanmu. 
Untuk ulang tahunku tahun ini, saya menerima sepasang sepatu bot panjang yang sangat cocok untuk mendaki. Apakah kamu tertarik untuk pergi hiking bersamaku dan menguji peningkatan stamina fisikmu, sekalian melihat matahari terbit dari puncak gunung? Pemandangan di antara pegunungan yang jauh dari kota pasti akan sangat indah. 
Tentu saja, jika ada piknik berkemah di alam liar dengan sebotol minuman keras untuk menghangatkan tubuh, itu akan lebih sempurna. 

Alva]]
  },
  Mail_68921_Name = {
    Text = "Pendakian gunung..."
  },
  Mail_68921_Sender = {Text = "Alva"},
  Mail_68922_Desc = {
    Text = "Pasangan: \n\nBanyak sekali hal yang terjadi selama setahun ini, mungkin bagi kamu, ini bukanlah kehidupan sekolah yang menyenangkan. \nAku mengakui bahwa selama setahun terakhir, dorongan dariku sering kali terasa memaksa, sementara perhatianku kurang lembut. Semua pelatihan terasa seperti memaksakan pertumbuhan terlalu cepat, membuatmu menanggung beban berat sekaligus. \nNamun, aku ingin kamu tahu bahwa kamu selalu menjadi orang yang paling penting bagiku. Di luar Penjaga Mythag, kamu adalah satu-satunya pasanganku. \nMungkin hari ini, maksudku hanya di hari ulang tahun ini, aku bisa mencoba bersikap egois sekali saja, dan kamu juga bisa melupakan semua tanggung jawab. Kita tidak perlu memikirkan tugas atau latihan apapun, dan bersantai sepenuhnya. \nKe taman hiburan di pusat kota? Teater? Pusat perbelanjaan, atau pasar jalanan… apa pun itu, aku harap bisa mengimbangi apa yang kurang untukmu. \nBegitu juga dengan hari ini, di mana kita tidak perlu mempertimbangkan apa pun, aku berharap kamu bisa menemaniku. Semua rencana terserah padamu. \n\nRamona"
  },
  Mail_68922_Name = {
    Text = "Hari yang rileks…"
  },
  Mail_68922_Sender = {Text = "Ramona"},
  Mail_68923_Desc = {
    Text = [[
Yang Terhormat Penjaga:

Selama bertahun-tahun aku hidup di antara manusia, para pelayan yang menggemaskan itu biasanya mengadakan pesta besar untukku setiap tahun pada hari ini, berusaha keras dengan berbagai cara untuk menyenangkanku.
Meskipun sebenarnya ini adalah hari yang biasa tanpa kejadian apa pun, senyuman aneh dari mereka benar-benar membuatnya terasa menyenangkan. Dalam hal menciptakan kebahagiaan dalam kesulitan atau sesuatu dari ketiadaan, manusia memang ahli dalam hal ini.
Bahkan di sekolah yang membangun kuburan di dalam kampus ini, kalian masih bisa begitu gigih menciptakan kebahagiaan, sungguh mengejutkan bagiku.
Namun, hadiah dari orang-orang biasa itu sangat membosankan, dan pesta ulang tahun yang disebut-sebut itu juga tak terbayangkan betapa membosankannya, mayoritas tetaplah orang-orang yang medioker.
Hanya kamu, hanya saat memikirkanmu aku merasakan sedikit ketertarikan, membuatku merasakan kembali kesenangan seperti di masa lalu.
Aku memerintahkanmu datang ke kamarku sekarang juga, bermain denganku sampai pagi. Jika kau melayani dengan baik, aku bisa saja mengizinkanmu mencium punggung tanganku.

Wanda]]
  },
  Mail_68923_Name = {
    Text = "Perintah…"
