  Mail_68923_Sender = {Text = "Wanda"},
  Mail_68924_Desc = {
    Text = [[
<Del:Orang Barat>Penjaga Mimpi: 
Awalnya aku tidak berniat menulis hal-hal cengeng seperti ini lagi, tapi Aigis terus mengomel di sebelahku tentang peringatan dan makna, memaksaku untuk menulis surat ini untukmu. 
Karena Aigis, aku akan berkata sedikit. Jadi, setelah tinggal di sini selama satu tahun, secara keseluruhan aku cukup puas dengan akomodasi dan makanan di sekolah, kecuali seprai di asrama yang terlalu licin sehingga aku tidak bisa tidur nyenyak. Apakah kalian tidak merasa bahwa hanya kain katun kasar yang nyaman untuk tidur? 
Kalau ada yang bisa dikritik lagi, makanan di kantin terlalu sehat. Meskipun perut kenyang setelah makan, rasanya mulut tetap hambar, sama sekali tidak sebanding dengan rasa makanan jalanan! 
Jadi, untuk pesta ulang tahunku tahun ini, aku tidak akan merepotkan para koki itu. Biar sang master kuliner membawa kalian semua ke gang misterius di Distrik Timur untuk mencicipi kedai yang sangat direkomendasikan olehku dan Cokelat. Dijamin kalian akan langsung jatuh cinta dengan kelezatan makanan jalanan! 
Tentu saja, semua biaya hari ini ditanggung oleh Orang Barat, kamu tidak keberatan kan? 

Teman lamamu Jenkin dan Cokelat]]
  },
