  Mail_68924_Sender = {Text = "Jenkin"},
  Mail_68925_Desc = {
    Text = [[
Tuan Terhormat: 

Selain kakak, kau adalah orang pertama yang begitu tulus mendukungku. Berkat saranmu sebelumnya, aku sekarang sudah merilis serangkaian album dengan perusahaan rekaman, dan sebentar lagi akan mengadakan konser solo pertamaku. 
Aku ingin menetapkan konser pertamaku di Planet ini pada hari ulang tahunku, untuk memperingati kelahiran baru di sini. 
Aku harap kau bisa datang ke konser untuk mendengarkan penampilanku yang penuh usaha. Aku ingin mengundangmu dan kakak sebagai tamu spesial di bagian akhir acara untuk naik ke panggung bersamaku dan menyanyikan lagu baruku bersama-sama. Bagaimana menurutmu? 
Ngomong-ngomong, jangan beritahu kakak tentang ini, karena itu juga hari ulang tahunnya, aku ingin memberinya kejutan. 
Adapun permintaan ulang tahun yang telah aku janjikan dengan kakak untuk diriku sendiri, aku berharap suaraku bisa bersinar lagi di Planet ini. 

Tinct]]
