  Mail_68926_Desc = {
    Text = [[
Kepada penjaga yang terkasih:

Tanpa terasa, setahun telah berlalu. Setiap hari di Mythag sangat menyenangkan, bisa bermain, belajar, dan makan banyak makanan enak bersama semua orang, ini adalah saat-saat paling bahagia dalam hidupku. Meskipun terkadang saat kerja aku merasa sedikit tegang, tapi bertarung bersama semua orang, Aigis tidak pernah merasa takut.
Maafkan aku, tahun ini aku telah banyak merepotkan Anda, meskipun seringkali Jenkin yang nakal, dia hanya ingin membuat semua orang senang, semoga Anda tidak keberatan dengan kelalaian dan pelanggaran kami.
Berbicara tentang Jenkin, tahun ini dia mengusulkan mengadakan kompetisi menangkap kunang-kunang pada hari ulang tahunku, dia menyiapkan banyak toples transparan, katanya ingin membuat banyak lampu kunang-kunang, dan akhirnya siapa yang membuat lampu paling terang akan mendapatkan gelar raja pemburu serangga.
Meskipun terdengar sedikit konyol, hutan yang selalu penuh dengan kunang-kunang di musim panas itu memang sangat indah. Jika Anda memiliki waktu luang di tengah kesibukan, kami sangat menyambut Anda datang bersama kami ke hutan, melihat pemandangan yang berkilau seperti bintang itu.

Aigis]]
