  Mail_68926_Sender = {Text = "Aigis"},
  Mail_68927_Desc = {
    Text = [[
Penjaga! Beberapa hari yang lalu, saat berenang di laut, Aurita bertemu dengan teman baru yang bisa mengeluarkan listrik! Bentuknya bulat, pipih, seperti pizza besar! 
Awalnya, Aurita mencoba menyapanya, tapi tiba-tiba merasakan sensasi kesemutan di tubuhnya, dan teman barunya itu langsung pergi. 
Setelah kembali, Boneka memberitahuku bahwa itu adalah pari listrik yang sedang mengeluarkan listrik. Aurita tidak terlalu mengerti, tapi merasa teman barunya sangat hebat! Kebetulan ulang tahun Aurita sudah tiba, Penjaga, ayo kita jemput teman baru itu untuk tinggal bersama teman-teman Aurita! Sensasi kesemutan itu pasti akan disukai Penjaga juga! 

Aurita]]
