  Mail_68928_Desc = {
    Text = [[
Yang Terhormat Penjaga: 

Ulang tahun di masa kecil bagi saya adalah permintaan ayah yang tanpa basa-basi, adalah latihan bermain musik tanpa sedikit pun waktu untuk bersantai. 
Tidak boleh sombong, tidak boleh gegabah, tidak boleh malas. Kecuali ibu diam-diam menyiapkan sepotong kecil kue untuk saya, hari itu hanyalah teguran ketat tanpa alasan, untuk menunjuk segala kekurangan saya selama setahun terakhir. 
Hingga hari ini, saya bukan lagi murid musik, dan karena Anda dapat menyentuh pintu megah itu, masuk ke dalam istana musik tertinggi. Namun, ajaran sejak kecil telah membuat saya tidak memiliki keinginan apa pun terhadap kesenangan duniawi. 
Hanya musik, hanya memainkan lagu penghiburan takdir itu untuk Anda, adalah pencapaian akhir hidup saya, adalah saat-saat satu-satunya saya merasa ada makna dalam hidup. 
Jika Anda bersedia memberikan waktu menjelang tidur malam ini kepada saya, saya bersedia memainkan lagu yang terukir di Jiwa saya sepanjang malam untuk Anda, sampai fajar tiba. 

Hameln]]
  },
  Mail_68928_Name = {
    Text = "Keinginan untuk bermain..."
  },
  Mail_68928_Sender = {Text = "Hameln"},
  Mail_68929_Desc = {
    Text = [[
Anak muda: 

Sejak datang ke sini, kupikir akhirnya bisa terbebas dari wanita gila yang kaku itu, tapi aturan di tempat kalian bahkan lebih banyak daripada dia! Sudah lama aku tidak merasakan apa itu kebebasan! 
Minum anggur dengan bebas tidak boleh, menggoda wanita cantik tidak boleh, pesta api unggun tidak boleh, bahkan daging panggang di sini jauh lebih buruk daripada di Filistin! Entah bagaimana kalian bisa bertahan hidup dalam kehidupan yang begitu hambar. 
Namun, orang kuat tidak mengeluh tentang lingkungan. Setelah melalui berbagai pertempuran, aku telah menjadi pemimpin geng besar di kotamu. 
Pada hari ulang tahun tuan Goliath yang agung ini, dengan murah hati aku mengundangmu untuk hadir di pesta yang diadakan oleh anak buahku untukku. Anggur dan daging enak serta wanita-wanita cantik akan tersedia, pasti akan membuka mata bocah ingusan sepertimu yang belum pernah melihat dunia. 
Melihat hubungan kita sebelumnya, aku tidak akan meminta Hadiah darimu. Kamu hanya perlu membawa rasa hormatmu untuk memberikan doa atas kebangkitan kembali sang penguasa. 
Lihatlah dengan baik dan saksikanlah, pada hari ini tahun depan, atau bahkan dua tahun lagi, di mana pun aku berada, aku akan membuka jalan baru. 

Goliath]]
  },
  Mail_68929_Name = {
    Text = "Perjalanan…"
  },
  Mail_68929_Sender = {Text = "Goliath"},
  Mail_68930_Desc = {
    Text = [[
Penjaga: 

Awalnya, aku tak pernah berpikir untuk merayakan ulang tahun tubuh yang fana ini, hanya menganggapnya sebagai hari biasa untuk berlatih. Namun, pagi ini Raja menemukanku dan memberikan titah lisan bahwa hari ini aku tidak boleh melakukan apapun yang berhubungan dengan Raja atau latihan. Aku harus sepenuhnya menghabiskan hari ini untuk diriku sendiri. 
Selama bertahun-tahun, inilah pertama kalinya Raja begitu memperhatikanku, membuatku merasa sangat cemas sekaligus sangat bersyukur. Namun, aku telah mengabdikan seluruh hidupku kepada Raja, jadi aku bingung harus pergi ke mana dan apa yang harus kulakukan. 
Setelah merenung sejenak, satu-satunya hal yang bisa disebut sedikit disesalkan adalah rasa bersalahku terhadap anak itu, Murphy. Meski demi kebangkitan kembali negara asalku, aku tak pernah menyesal sedikitpun. Hutang yang kumiliki padanya, aku tahu tak dapat dibayar atau diperbaiki. 
Namun, jika ada sesuatu yang benar-benar ingin kulakukan dari hati, mungkin aku ingin dengan malu-malu mencoba sekali lagi menjadi seorang ibu seperti yang seharusnya. 
Aku sengaja membeli kue manis yang dulu ia sukai, anggap saja ini untuk memenuhi permintaan seorang ibu yang hina dan gagal. Bisakah kau membantuku memberikan hadiah ini kepadanya? Jangan katakan bahwa ini dariku, cukup katakan bahwa ini dari persiapanmu. 
Berharap kau menerimanya, aku sangat berterima kasih. 

Miryam]]
  },
  Mail_68930_Name = {
    Text = "Mengkompensasi…"
  },
  Mail_68930_Sender = {Text = "Miryam"},
  Mail_68931_Desc = {
    Text = [[
Ah, setelah mempertimbangkan dengan bijaksana, aku sudah sepenuhnya memahami makna di balik hari ulang tahun manusia. Hari spesial yang dikhususkan untuk seseorang ini memberikan kesempatan langka untuk menggunakan hak istimewa, mendapatkan barang-barang berharga, dan kesempatan untuk mengutarakan keinginan kepada orang lain dengan percaya diri. 
Bahkan keinginan yang biasanya tidak berani atau tidak terpikirkan untuk diungkapkan, pada hari itu ada kemungkinan untuk terpenuhi. Ha, ini benar-benar hari pesta yang lebih mendebarkan daripada hari libur apa pun. 
Tampaknya selama bertahun-tahun aku telah melewatkan begitu banyak kesempatan istimewa ini, tapi untungnya dengan umurku yang panjang, aku masih memiliki banyak ulang tahun di masa depan untuk mengucapkan harapan. 
Jadi, bukankah keinginan untuk meminta semua orang bermain denganku sepuasnya di hari ulang tahunku adalah keinginan yang mudah dipenuhi? 

Lotan]]
  },
  Mail_68931_Name = {
    Text = "Hak istimewa sang bintang ulang tahun…"
  },
  Mail_68931_Sender = {Text = "Lotan"},
  Mail_68932_Desc = {
    Text = [[
Penjaga: 

Seiring bertambahnya usia, hari ulang tahun perlahan-lahan menjadi hari yang akan diabaikan oleh kalender, sering kali saat teringat tidak sengaja, ulang tahun sudah berlalu seperti aliran air.
Di dunia orang dewasa, merayakan ulang tahun hanyalah hak istimewa anak-anak dan orang-orang membosankan, saya di bidang ini juga menjadi orang dewasa yang membosankan, yang telah kehilangan semua harapan akan ulang tahun.
Dulu, ada satu tahun saya terlintas dalam pikiran untuk mengukir patung kue yang indah untuk diri sendiri, dan selama bertahun-tahun berikutnya, saya tidak pernah melewatkan memesan kue karena lupa ulang tahun, melainkan langsung mencari alat perayaan yang tidak akan membusuk ini dari gudang pada hari ulang tahun, untuk merasakan ritual meniup lilin, dan ulang tahun dapat dianggap telah dirayakan.
Sampai datang ke Mythag, saya baru menyadari bahwa orang yang membosankan dan yang sibuk dapat ada dalam satu diri, dan orang-orang di sini tidak hanya puas dengan kebosanan mereka sendiri, tetapi juga harus menarik semua orang untuk ikut membosankan.
Dua tahun terakhir di Mythag, jumlah perayaan ulang tahun yang saya hadiri jauh lebih banyak daripada semua perayaan ulang tahun yang saya hadiri dalam hidup saya sebelumnya, yang lebih lucu adalah saya menemukan sedikit kesenangan aneh dalam perayaan yang membosankan ini.
Mungkin selain tema yang menyedihkan dan serius, menggambarkan beberapa pemandangan konyol dalam kehidupan sehari-hari juga bisa dipenuhi dengan keindahan seni.
Berbicara tentang ini, rencana kreasi tahun ini adalah mengukir patung setengah badan Penjaga yang tersenyum bodoh, untuk memegang kue patung saya.
Ingat untuk datang lebih awal ke studionya, model muses saya.

Sanga]]
  },
  Mail_68932_Name = {
    Text = "Kesenangan yang membosankan…"
  },
  Mail_68932_Sender = {Text = "Sanga"},
  Mail_68933_Desc = {
    Text = [[
Kepada yang terkasih:

Setelah mempertimbangkan lama, aku menulis surat ini di dunia yang sunyi dan hampa ini. Sudah lama aku hampir melupakan hari ulang tahunku sendiri, dan merayakannya di dunia seperti ini tentu saja tidak ada artinya.
Namun, sejak bertemu denganmu, aku menjadi semakin serakah, hari demi hari berlalu, bahkan kesendirian yang biasa kurasakan pun mulai terasa sulit untuk ditanggung.
Setiap kali seperti itu, muncul perasaan aneh dalam hatiku, membuatku iri pada diriku di duniamu, mungkin juga ada sedikit rasa cemburu yang tak terdeteksi. Lihatlah, seseorang yang mengaku rasional seperti aku juga bisa memiliki pikiran yang begitu rendah suatu hari, tampaknya keadilan dan rasionalitas manusia memiliki batasnya masing-masing.
Aku tahu apa yang akan kamu katakan untuk mengundangku, tetapi bagi ruang dan waktu, gangguan yang tidak perlu harus dihindari semaksimal mungkin, aku tidak seharusnya dan tidak akan pergi ke duniamu.
Saat menulis ini, aku sedang menatap alam semesta, menatap tempat terowongan terbuka, jika kebetulan kamu juga sedang menengadah, maka kita bisa dikatakan sedang memandang langit yang sama bersama-sama.
Semoga surat ini dapat menggantikanku, melintasi ruang dan waktu, mengalir ke telapak tanganmu, melewati matamu, bibirmu, dan gigimu, bertemu denganmu, dan berdampingan denganmu.
Ketika kamu memeluk kertas surat ini, aku di ujung dunia ini membayangkan memelukmu.

"Ramona"]]
  },
  Mail_68933_Name = {
    Text = "Bersama-sama menatap ke kejauhan…"
  },
  Mail_68933_Sender = {
    Text = "Ramona: Timeworn"
  },
  Mail_68934_Desc = {
    Text = "Tahanan kecil·ku: \n\nApakah kamu tahu, seperti hewan yang berbeda memiliki resep makanan yang berbeda, kebutuhan orang terhadap kehangatan juga berbeda-beda. Ada orang yang cukup mengenakan satu lapis pakaian untuk menghangatkan diri, ada yang membutuhkan sepasang tangan yang hangat, pelukan yang hangat, dan ada juga yang membutuhkan suhu sepanas lilin yang meleleh. \nSuhu yang begitu panas dan kental itu tercetak di setiap ujung saraf, dengan jelas mencerminkan jejak tetesan lilin yang melengkung, sensasi nyeri yang samar, sentuhan yang membuat gemetar, hingga pada saat tidak bisa menahan diri untuk berteriak, barulah bisa merasakan keberadaan diri sendiri dengan lega. \nTerkadang aku berubah menjadi lilin, menikmati kebahagiaan membawa Orison. Terkadang aku juga terpikat oleh suhu lilin, mendambakan kehangatan yang menyakitkan namun manis itu. \nMusim dingin Mythag telah tiba, akhir-akhir ini aku sering merasa kedinginan, serta kesepian yang dibawa oleh dingin itu. Sayang, kamu pasti tahu hari apa ini, harapanku sangat sederhana, aku yakin seseorang yang baik sepertimu pasti bersedia memberiku kehangatan untuk mengusir kesendirian ini. \n\nPandia"
  },
  Mail_68934_Name = {
    Text = "Kebutuhan yang hangat…"
  },
  Mail_68934_Sender = {Text = "Pandia"},
  Mail_68935_Desc = {
    Text = "Penjaga: \n\nTahun ini saya dan Tinct saling berjanji, keinginan ulang tahun kami hanya boleh tentang diri sendiri, tidak boleh untuk mengharapkan sesuatu bagi orang lain. \nMeskipun dia yang pertama kali mengusulkan perjanjian ini dengan nada kesal, tampaknya hal ini juga membuatnya bingung. \nKami terlalu lama terikat satu sama lain, hingga berpikir secara mandiri seperti orang biasa pun menjadi sulit. Namun, dilahirkan kembali dalam kehidupan baru yang penuh dengan bantuan dan perhatian, tidak ada waktu yang lebih baik dari sekarang untuk belajar berdiri sendiri. \nSetelah mempertimbangkan dengan matang, saya sudah memutuskan keinginan yang ingin saya ucapkan tahun ini: berteman dengan lima orang baru… ah, mungkin tiga saja. Bagaimanapun, mengubah diri sendiri adalah proses yang harus dilakukan sedikit demi sedikit. \nSebagai satu-satunya teman saya saat ini yang begitu populer, mungkinkah kamu bisa mengajari saya beberapa rahasia untuk mendapatkan teman? \n\nPingsan"
  },
  Mail_68935_Name = {
    Text = "Keinginan untuk berteman…"
  },
  Mail_68935_Sender = {Text = "Faint"},
  Mail_68936_Desc = {
    Text = "Penjaga: \n\nSetiap kali ulang tahun, aku selalu berharap hal yang sama — transformasi sempurna dari darahku. Sebenarnya, aku selalu tahu bahwa obsesiku terhadap darah mungkin dianggap keras kepala, konyol, atau bahkan menyedihkan dan hina oleh orang lain.\nNamun, kamu berbeda. Tak peduli apa pun yang terjadi, aku tahu kamu akan selalu mendukungku di jalan ini, meskipun aku gagal, jatuh, atau pulang dengan tangan kosong. Di tengah tawa orang lain, kamu adalah orang pertama yang memperhatikanku.\nMungkin baik kamu maupun siapa pun tidak bisa benar-benar memahami apa yang harus ditanggung seseorang yang sejak kecil tertindas dan dihina. Namun, tidak masalah, semua penderitaan dalam perjalanan transformasi ini telah menjadi bagian dari Caro dan nutrisiku, menopangku untuk terus bangkit dan melawan.\nAku bukan lagi diriku yang lemah di masa muda. Meskipun ujian berat menanti, aku akan tetap teguh sampai akhir.\nSebelum itu, tolong pandangi aku dan tunggu keberhasilanku.\nNgomong-ngomong, lima puluh yang kamu berikan padaku dulu, aku sudah bilang akan mengembalikannya. Sekarang aku sudah menabung cukup, bahkan ada dua kelebihan. Anggap saja sebagai ucapan terima kasih dariku.\n\nCaecus"
  },
  Mail_68936_Name = {
    Text = "Mengembalikan uang…"
  },
  Mail_68936_Sender = {Text = "Caecus"},
  Mail_68937_Desc = {
    Text = [[
Kepada Penjaga yang terhormat: 

Halo, selamat datang untuk mengisi survei inspeksi tahunan boneka otomatis Erica. Saya akan mengumpulkan pengalaman nyata dan masalah yang Anda temui selama menggunakan Erica dalam setahun ini. Saran Anda adalah arah perbaikan Erica di masa depan. 
Di bawah ini, silakan berikan penilaian dari rendah ke tinggi pada pertanyaan terkait dalam balasan Anda. Terima kasih banyak atas umpan balik Anda. 
Tingkat kemudahan saat digunakan: 1-5 poin 
Kecepatan respons saat digunakan: 1-5 poin 
Tingkat pemahaman terhadap kebutuhan: 1-5 poin 
Tingkat perhatian terhadap emosi pengguna: 1-5 poin 
Akurasi saat mencari informasi: 1-5 poin 
Tingkat kepraktisan solusi yang diajukan: 1-5 poin 
Terakhir, harap deskripsikan secara singkat masalah yang Anda temui saat menggunakan Erica dan bagian yang tidak memuaskan. Masalah-masalah ini mungkin akan diperbaiki di kemudian hari. 
Setelah menyelesaikan survei, hadiah peringatan ulang tahun akan dikirim ke kamar Anda. Dalam setahun ke depan, asisten paling setia Anda, Erica, masih akan tetap ada di sisi Anda. Sekali lagi, terima kasih atas penggunaannya, sampai jumpa lagi. 

Erica]]
  },
  Mail_68937_Name = {
    Text = "Kuesioner Penyelidikan Tahunan…"
  },
  Mail_68937_Sender = {Text = "Erica"},
  Mail_68938_Desc = {
    Text = [[
Penjaga: 

Setiap hari ulang tahun, saya selalu menghabiskan seharian untuk merenungkan kembali masa lalu di dalam pikiran saya dan menuliskan kembali jurnal yang sama. 
Semakin lama saya jauh dari Rumah, memori lama tampaknya semakin kabur. Hari-hari ketika saya menunggu seseorang pulang mengikuti cahaya, hari-hari ketika saya memandang hormat pada keagungan Raja, semuanya sudah tidak terlalu jelas lagi dalam ingatan. 
Namun, saya tidak mau melupakan. Saya tidak akan pernah melupakan, meskipun harus menunggu tanpa akhir, meskipun harus membakar Jiwa saya, cahaya ini tidak akan pernah pudar hingga hari kebangkitan negara asal. Saya adalah sinar pertama yang akan menjawab panggilan Memanggil. 
Saya telah membayangkan berbagai skenario pertemuan kembali, tetapi tak pernah terpikirkan bahwa saya akan bertemu kembali dengan Raja dan Pendeta di tempat ini. Menggunakan ungkapan kalian, jika tempat hati tenang adalah Rumah, maka tempat ini bisa dianggap sebagai rumah kedua saya. Catatan harian saya pun akhirnya berubah dari sekadar memori menjadi kenangan baru setiap hari. 
Tidak diperlukan penghargaan atau Hadiah apa pun, bisa sekali lagi mengikuti Raja adalah kebahagiaan terbesar. 
Jika cahaya tubuh ini tidak dapat menyinari dasar laut di tanah kelahiran, maka biarlah ia mengikuti langkah Raja dan untuk sementara menerangi negeri daratan ini. 

Faros]]
  },
  Mail_68938_Name = {
    Text = "Mengikuti Tuan kami…"
  },
  Mail_68938_Sender = {Text = "Faros"},
  Mail_68939_Desc = {
    Text = "Penjaga: \n\nSelamat untukku, dan selamat untukmu, selamat untuk Mythag, selamat untuk kita yang telah selamat setahun lagi di bawah kejaran teror hitam. \nHari ini bukanlah hari ulang tahun yang biasa, hari ini adalah hari peringatan aku masih hidup, hari pujian untuk kehidupanku yang gigih. \nHidup, dua kata yang sederhana ini mengandung begitu banyak kesulitan, semangat hidup yang membara ini hanya bisa dibandingkan dengan aroma kopi yang panas, mari bergabung dalam kultus kopi, Penjaga, mari kita puji kesadaran, puji setiap \n\nKertas yang dikirim bersamaan dengan surat: \nAh, orang ini, Wenker, telah meminum kopi secara berlebihan lagi, dengan sarafnya yang terjaga dan kelelahan berlebihan, langsung pingsan di meja. Aku sudah menempatkannya di ruang perawat, tidak perlu khawatir. \nNamun sebelum dia pingsan, dia mengeluarkan sekantong biji kopi yang disimpan dan surat, sepertinya ingin memberikannya padamu, aku sudah melampirkannya bersama surat ini, semoga setelah dia bangun, dia tidak menyesal. \nMengenai ulang tahunnya, mungkin memberi dia kesempatan untuk beristirahat adalah hadiah terbaik daripada pesta perayaan. \n——Sylvia"
  },
  Mail_68939_Name = {
    Text = "Memuji hidup…"
  },
  Mail_68939_Sender = {Text = "Winkle"},
  Mail_68940_Desc = {
    Text = [[
Penjaga: 

Hahaha! Setelah aku dengan gigih mengukir 12 pengingat di berbagai sudut ruangan dan menulis 36 catatan (mungkin lebih, tapi aku tidak bisa menemukannya lagi), akhirnya aku berhasil mengingat bahwa hari ini adalah ulang tahunku!
Tidak disangka, kan? Bahkan aku sendiri baru ingat pagi ini. Tapi semua ini berkat usahaku selama setahun terakhir, aku tidak mau melewatkan hari baik seperti ini.
Pesta terakhir yang kuhadiri bersama teman-teman sangat menyenangkan, terutama permainan yang kumainkan dengan siapa ya, dan juga ada makanan penutup manis... Ah, sudahlah, intinya sangat menyenangkan!
Saat masih kecil, setiap ulang tahun ibu selalu membelikanku sebuah buku cerita petualangan. Kami berdua akan membacanya bersama sebelum tidur, dan dalam mimpi aku akan bermimpi tentang petualangan yang luar biasa. Meskipun aku cepat melupakannya setelah bangun, kebahagiaan itu tetap tinggal di pikiranku. Aku percaya bahwa emosi yang berharga tidak akan pernah dilupakan.
Lagi pula, pelupa juga punya keuntungannya. Meskipun aku tidak ingat apa yang kulakukan di pesta sebelumnya, hari ini aku bisa mengalami semuanya lagi! Kebahagiaan dari waktu itu, tolong berikan padaku sekali lagi!

Nautila yang penuh harapan]]
  },
  Mail_68940_Name = {
    Text = "Coba lagi…"
  },
  Mail_68940_Sender = {Text = "Nautila"},
