  Mail_74841_Desc = {
    Text = [[
Pasangan: 

Pada hari ini tahun lalu, aku sama sekali tidak pernah membayangkan bahwa setahun kemudian, aku hanya bisa memasukkan surat ini ke kotak surat yang kosong. 
Pada saat itu, kamu baru saja masuk ke Mythag, dan tampak tak berbeda dengan siswa yang nakal dan malas. Bahkan sekarang, aku sering merasa terlalu keras terhadapmu dan terlalu peduli dengan topeng rasional dan angkuhku sendiri. 
Sebenarnya, pada hari ini tahun lalu, aku membeli seikat bunga. Aku berdiri di depan pintu perpustakaan, menatap mawar yang terbaring di antara pita merah dan kertas pembungkus hijau tua untuk waktu yang lama, dan akhirnya meletakkannya di samping tempat tidurku. 
Setahun berlalu, bunga itu telah layu, hanya pita merah terang yang kujadikan sebagai hiasan di Kunci Perak nomor K-0617, masih segar seperti baru. 
Betapa, betapa ingin aku membeli seikat mawar lagi, namun sekarang mereka hanya akan layu lagi di samping tempat tidurku tanpa tujuan lain. 
Terbiasa mencantumkan solusi terperinci untuk semua hal, rasa penyesalan adalah sesuatu yang begitu baru dan pahit bagiku. 
Namun, aku selalu memegang keyakinan buta bahwa jiwamu belum pergi. Mungkin kamu sedang menjelajahi suatu tempat di alam semesta untuk sementara, tetapi pada akhirnya kamu akan kembali ke sini, kembali ke sisiku. 
Aku tidak menganggap ini sebagai fantasi orang bodoh, karena setiap kali aku datang ke Kolam Hitam untuk melihat wajahmu dari kejauhan, aku masih bisa merasakan kehangatan samar dari tautan dan resonansi denganmu di dalam hatiku. 
Aku akan selalu percaya dan berharap untuk hari pertemuan kembali itu. Pada saat tangan kita bertautan kembali, aku akan memberikan mawar yang kuhutang hari ini langsung ke tanganmu. 

Ramona]]
  },
  Mail_74841_Name = {Text = "Mawar…"},
  Mail_74841_Sender = {Text = "Ramona"},
