  Mail_79646_Desc = {
    Text = "Kepada Penjaga yang terhormat:\nKegiatan \"Terpendam dalam memori\" telah berakhir, sekarang akan mengonversi sisa \"Laporan Diagnostik\" milik Penjaga menjadi \"Rose Scrip\" × 40 untuk setiap koin, silakan ingat untuk memeriksa."
