  },
  Mail_79646_Sender = {
    Text = "Dewan Sekolah Mythag"
  },
  Mail_80091_Desc = {
    Text = "Penjaga:\n\nKetika kamu membuka surat ini, itu berarti petunjuk yang aku tanamkan di hatimu sudah mulai berfungsi.\nHa, jangan khawatir. Ini hanya hipnosis kecil yang digunakan untuk memastikan pestaku berjalan dengan baik, tidak akan mempengaruhi kamu.\nSelanjutnya, kamu akan merasakan dorongan dari hati untuk berbelanja, ikuti dorongan itu dan pergi ke jalan, pilihlah satu hadiah yang paling sesuai dengan hatiku dari jendela etalase yang berkilau, lalu berikan ke tanganku.\nAku tahu kebingunganmu saat ini, dan setuju dengan keabsahannya, tetapi sebagai orang yang berulang tahun, aku pasti memiliki beberapa hak istimewa, bukan? Aku melakukannya hanyalah takut kamu lupa hari istimewa ini. Bagaimanapun, kamu adalah tamu yang sangat aku nantikan.\nAkhirnya, aku akan sabar menunggu kedatanganmu—jangan lupa hadiah. \n\nKlemantin"
  },
  Mail_80091_Name = {
    Text = "“Hadiah” yang “dipilih” secara pribadi"
  },
  Mail_80091_Sender = {Text = "Clementine"},
  Mail_81288_Desc = {
    Text = "Kepada Penjaga yang terhormat: \n        Terima kasih atas dukungan dan pengakuan Anda terhadap \"Morimens\". Untuk memberikan pengalaman bermain yang lebih baik bagi Penjaga di Universitas Mythag, kami mengundang Anda untuk mengisi kuesioner pengalaman berikut. Sebagai penghargaan atas kerjasama Anda, kami telah menyiapkan \"Perak\"× 200 sebagai imbalan, yang dapat diambil setelah menyelesaikan kuesioner. Batas waktu pengisian kuesioner adalah 14 April pukul 09:00, harap diperhatikan untuk mengisinya tepat waktu. \n        <SurveyLink:[Klik di sini untuk mengisi]>\n        Kami akan dengan serius mendengarkan setiap saran dari Penjaga, dan umpan balik Anda pasti akan membuat Universitas Mythag semakin baik! \n        ——Semoga Kunci Perak membimbing jalan ke depan."
  },
  Mail_81288_Name = {
    Text = "Kuesioner Survei Pengalaman Versi V2.2.0"
  },
  Mail_81288_Sender = {
    Text = "Mythag Bureau of School Affairs"
  },
  Mail_81326_Desc = {
    Text = "Tuan:\n\nHari ini adalah satu-satunya hari festival dalam setahun bagi saya dan Polyxus. Ketika di gereja, kami tidak diperbolehkan untuk terlalu mementingkan makna diri, semua nilai kami hanya ada dalam pengabdian kepada karya abadi para pembawa lampu, di hadapan keyakinan semacam itu, festival lainnya hanyalah ilusi yang tidak berarti.\nNamun pada hari ulang tahun ini, saya dan Polyxus tetap merayakan secara diam-diam, kami akan menyiapkan hadiah yang sekecil mungkin untuk satu sama lain tanpa sepengetahuan pelayan, kemudian secara rahasia menantikan kedatangannya.\nMomen perayaan ulang tahun biasanya terjadi di tengah malam—itu adalah satu-satunya waktu kebebasan kami dalam sehari, tangan dan ide brilian Polyxus selalu membuat hadiahnya melebihi milik saya, suatu kali dia bahkan menjalin bunga mekar dari bulu-bulu yang jatuh.\nSebenarnya saya tidak ahli dalam menyiapkan kejutan, Polyxus selalu mengatakan ekspresi saya selama ini sudah mengkhianati segalanya, dan barang yang saya miliki pasti lebih membosankan di mata Anda, namun hari ini saya sudah memikirkan cara yang sangat baik untuk berbagi kebahagiaan dengan Anda.\nKetika Anda mendengar ketukan di jendela sebanyak tiga kali di malam hari, jangan takut, buka jendela, saya akan membawa Anda merasakan sentuhan awan dan angin malam.\n\nCastor"
  },
  Mail_81326_Name = {
    Text = "Malam berkeliaran..."
  },
  Mail_81326_Sender = {Text = "Castor"},
  Mail_84142_Desc = {
    Text = [[
Penjaga: 

Sebelum bertemu, aku menulis surat ini, secara resmi mengundang dan memperkenalkan "Pelayaran Ulang Tahun" ku. 
Tujuan pertama dari pelayaran ini adalah Sungai Thames. Kami akan naik kapal barang yang telah dimodifikasi menjadi restoran bergerak, sambil berlayar, sambil menikmati nanas manis dalam kaleng dan rum. Ini adalah hidangan yang hanya tersedia pada ulang tahun awak kapal, semoga kamu menyukainya. 
Tujuan kedua adalah dek pengamat pelabuhan. Jangan khawatir, aku sudah meminta izin pengamatan dari Asosiasi Balon Udara Panas. Ketika balon udara terbang tinggi dan melihat semua jalur London, kami akan bersama-sama memotong kue sebagai perayaan. 
Dahulu, kondisi pelayaran terbatas, kue ulang tahun yang dimaksud hanya model yang dibuat oleh tukang kayu menggunakan kayu ek dan karamel, jadi aku tidak tahu rasa kue tersebut, kali ini dapat mencicipinya bersamamu, selain keindahan makanan, aku berharap untuk mendapatkan lebih banyak. 
Tujuan ketiga, atau seharusnya disebut tahap ketiga, adalah peta bintang kustom. Aku telah menandai posisi benda langit saat aku lahir di peta laut, jika kamu tidak keberatan, aku ingin menandai milikmu juga, sehingga peta laut yang unik ini akan menjadi hadiah yang paling berharga untuk disimpan. 
Sebenarnya, saat menulis surat ini, aku sempat ragu. Tindakan ini tanpa diragukan melewati batas normal, tetapi hari ini adalah hari istimewa, dan kamu adalah orang yang istimewa bagiku, layak untuk ku langgar aturan. 
Oleh karena itu, jangan ragu untuk menolak dan wawancara tepat waktu. 

 
Kepersan]]
  },
  Mail_84142_Name = {
    Text = "\"Berlayar\" undangan"
  },
  Mail_84142_Sender = {Text = "Corposant"},
  Mail_84355_Desc = {
    Text = "Yth. Penjaga: \n Kegiatan \"Dalam hujan lebat, bergoyang\" telah berakhir. Saat ini, sisa mata uang kegiatan \"Bendera Sinyal\" milik Penjaga akan dikumpulkan sesuai dengan rasio setiap 1 ditukar menjadi \"Rose Scrip\" × 40. Harap Penjaga ingat untuk memeriksa."
