  Mail_94424_Desc = {
    Text = "Kepada Penjaga yang terhormat:\nKegiatan \"Pembakuan Agung\" telah berakhir, sekarang akan mengonversi sisa \"Daging panggang lezat dari Leo\" milik Penjaga menjadi \"Rose Scrip\" × 40 untuk setiap koin, harap Penjaga ingat untuk memeriksa."
