  },
  Mail_94425_Desc = {
    Text = "Yang terhormat Penjaga: \n Acara \"Pembakuan Agung\" telah berakhir, sekarang akan mengonversi \"Kupon Desain Pakaian Fantasi Minimalis (Edisi Kedua)\" yang tersisa untuk Penjaga menjadi \"Undangan dari Yang Tidak Berbentuk\" × 1 dengan rasio 1:1, harap Penjaga ingat untuk memeriksa."
