  },
  Mail_94503_Desc = {
    Text = [[
Pelita saya:

Sejak saya dan Castor datang ke sini, perhatian Anda terhadap kami sama seperti memberi kami kehidupan baru, terima kasih atas kue ulang tahun yang Anda siapkan dengan hati-hati untuk kami, meskipun saya sangat menyesal telah salah mengidentifikasi dua burung kecil yang Anda gambar di atas kue sebagai kupu-kupu, tetapi kami benar-benar menyukai hadiah ini, ini juga merupakan hadiah ulang tahun pertama yang kami terima dari orang lain.
Kami juga menerima kartu ucapan dari Dekan Czort, di dalam amplop putih itu terpasang segel emas yang megah, dipenuhi dengan harapan yang baik, ini adalah tempat yang sangat hangat, kami tidak pernah merasakan momen sebahagia sekarang dalam hidup kami.
Silakan datang untuk merayakan ulang tahun bersama saya dan Castor, ini adalah ritual yang kami jalani sejak kecil, sebagai kebaikan kami, kami juga telah menyiapkan hadiah timbal balik untuk Anda, sebuah mahkota yang saya buat dari bulu yang terjatuh dari Castor.
Saya mempersembahkan mahkota kasar ini kepada Anda, sebagai bentuk penghargaan kecil kami, saya bersedia menghabiskan sisa hidup saya mengikuti Anda, mewujudkan visi besar sekolah ini, untuk menghilangkan kejahatan dan kegelapan yang sejati.
Sudah lama saya tidak melakukan hal semacam ini, Castor bahkan mengejek bahwa keterampilan saya tidak sebagus semasa kecil, semoga Anda tidak keberatan.

Pollux]]
  },
  Mail_94503_Name = {
    Text = "Mahkota bulu..."
  },
  Mail_94503_Sender = {Text = "Pollux"},
  Mail_95382_Desc = {
    Text = "Makhluk kecil yang lucu:\n\nMakhluk kecil, hari ini adalah hari kedatanganku.\nBukan sebagai bola api yang terus menyala, tetapi sebagai ulang tahun gadis bernama Kathygula.\nSesuai dengan kebiasaan semasa hidupku, pada hari ini kami akan mengadakan pesta besar, menikmati anggur dan daging bakar sepuasnya.\nTentu saja, selalu ada bocah nakal yang tidak peduli suasana dan mengejekku bahwa aku sudah setahun lebih tua, jadi aku menyambut mereka dengan tinjuku.\nSekarang, pesta ini memiliki fungsi tambahan, untuk mengenang masa-masa yang pernah kami lalui.\nTahun ini aku berencana menambahkan satu acara lagi, yaitu—memburu makhluk kecil kita!\nTahukah kamu, aku sudah tidak sabar ingin menangkapmu ke pestaku, menghiasinya dengan ekspresi malu dan bingungmu, tatapan mata lemah setengah mabukmu, dan aroma manis yang keluar darimu, ini akan menjadi hadiah ulang tahunku yang terbaik sejak aku lahir!\nSudah terlambat untuk mempersiapkan rencana pelarian karena ketika kamu melihat surat ini… aku sudah berada di depan pintumu.\nJangan takut, makhluk kecil, jika semuanya berjalan dengan baik, kamu hanya akan mendengarkan cerita terbaik di sini, menikmati makanan yang paling lezat.\nTentu saja, makhluk kecil yang terlihat ditangkap, adalah hal biasa jika terjadi beberapa kejadian yang tidak terduga, bukan?\nAyo ikuti aku makhluk kecil, malam ini masa indahmu, ditakdirkan untuk dihabiskan bersamaku.\n\nKathygula"
  },
  Mail_95382_Name = {
    Text = "Pesta waktu…"
  },
  Mail_95382_Sender = {Text = "Katyugula"},
  Mail_95465_Desc = {
