  Mail_95875_Desc = {
    Text = "Yang terhormat Penjaga: \n Kegiatan \"Estetika Nekrotik\" telah berakhir, sekarang sisa \"Tulang Tangan Busuk\" Penjaga akan dikonversi dengan rasio setiap satu ditukar dengan \"Rose Scrip\" × 40, harap Penjaga ingat untuk menerima."
