  },
  Mail_96012_Desc = {
    Text = "Yth. Penjaga: \n Acara \"Ribu Cahaya Terang yang Jatuh\" telah berakhir. Sisa \"Cap Kekayaan\", \"Cap Darah Segar\", dan \"Cap Perang\" milik Penjaga akan dikonversi dengan rasio setiap item menjadi \"Rose Scrip\" × 40. Harap Penjaga ingat untuk memeriksa."
  },
  Mail_96012_Name = {
    Text = "Pengambilan peluru"
  },
  Mail_96012_Sender = {
    Text = "Dewan Sekolah Mythag"
  },
  Mail_96323_Desc = {
    Text = "Yang Mulia Penjaga:\n\nOrang hidup merayakan ulang tahun, adalah untuk mengambil makna dalam waktu yang tersisa. Sedangkan aku hanya memanfaatkan malam ini untuk meningkatkan aroma kematian lebih harum.\nMereka yang tidak lagi berjuang, tidak lagi terikat, adalah yang dulunya penuh noda, semuanya telah dicuci bersih, penyesalan mereka bagaikan garam halus, mengalir pada saat yang tepat di antara garis darah, membentuk wangi yang lembab dan lembut. Tulang mereka akan mengeluarkan suara retak yang lembut, kulit yang mengeluarkan lemak semerbak seperti mint, dan kata-kata tak terucap di dalam jiwa mereka akan perlahan-lahan keluar saat dimasak, meninggalkan sedikit manis yang halus. Aku sudah mulai membayangkan wujudmu yang menjadi sesuatu yang tenang—suara retak saat kulit mengencang di depan api, emosi yang menguap di antara daging dan tulang, rasa manis yang perlahan melahap jiwamu yang murni...\nTapi kau berbeda.\nKau masih bersinar, masih berdetak, namun memiliki aroma yang tak dapat dibandingkan dengan arwah mana pun, membuat orang terpesona. Kau adalah sesuatu yang aku ingin tunggu, aku bahkan berharap penantian ini dapat berlangsung lebih lama dari keabadian.\nDalam banyaknya siklus tahun yang berulang, kehadiranmu memberi makna pada ulang tahunku. Bukan sekadar untuk pengalaman makan yang indah, tetapi juga untuk nyawa yang masih bergerak di dalam dirimu.\n\nDullesain"
  },
  Mail_96323_Name = {
    Text = "Menunggu selamanya…"
  },
  Mail_96323_Sender = {Text = "Doresain"},
